window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0237", [{"word":"have an effect on","ipa_uk":"/hæv ən ɪˈfekt ɒn/","ipa_us":"/hæv ən ɪˈfekt ɑːn/","definition_zh":"对……产生影响；对……起作用，使事物在状态、数量或结果上发生变化","definition_en":"to produce a change in something or someone, especially in its state, amount or result","core_image":"一枚石子投进静水，涟漪一圈圈推到岸边的浮标","scene":"池塘里投下一枚石子，波纹一圈圈推到岸边的浮标。These new rules have an effect on every household in the district.","sceneCN":"这里指新规定对家家户户产生实际影响（第 1 个义项：对……产生一般性的影响）；句意为这些新规定对本区每一户人家都有影响。图中可辨识物件：池塘、石子、波纹、浮标。","pos":[{"tag":"v. phr.","zh":"动词短语：对……产生影响"},{"tag":"idiom","zh":"固定搭配：产生作用"}],"collocations":[{"phrase":"have a significant effect on","zh":"对……有显著影响"},{"phrase":"have little effect on","zh":"对……几乎没有影响"},{"phrase":"have an adverse effect on","zh":"对……有不利影响"},{"phrase":"have a lasting effect on","zh":"对……有持久影响"},{"phrase":"have an effect on the outcome","zh":"对结果产生影响"},{"phrase":"have no effect on","zh":"对……没有作用"}],"forms":[{"label":"原形","form":"have an effect on"},{"label":"第三人称单数","form":"has an effect on"},{"label":"过去式","form":"had an effect on"},{"label":"情态结构","form":"can have an effect on"},{"label":"名词短语","form":"an effect on"}],"derivatives":[{"word":"effect","pos":"n.","zh":"由拉丁语「做出、完成」的过去分词而来，义为「效果；影响」"},{"word":"effective","pos":"adj.","zh":"由该名词加「可……的」形容词尾构成，义为「有效的」"},{"word":"effectiveness","pos":"n.","zh":"由形容词加表示性质的名词尾构成，义为「有效性」"},{"word":"affect","pos":"v.","zh":"同出拉丁语「做出」一系，但走的是另一个动词形式，义为「影响」；与本短语的名词形分工明确"},{"word":"ineffective","pos":"adj.","zh":"由否定前缀加形容词构成，义为「无效的」"},{"word":"effectual","pos":"adj.","zh":"由该名词加形容词尾构成，义为「奏效的」（较书面）"}],"senses":[{"no":"01","title":"A change in a state or result","titleCN":"对状态或结果产生影响","definition":"to make a difference in how something turns out","definitionCN":"使某件事的最终状态或结果与原来不同","example":"Long delays can have an effect on the final cost of a project.","exampleCN":"长期拖延会对项目的最终成本产生影响。","why":"The noun names the change itself, while the verb have merely carries it, so a preposition must introduce the object changed.","whyCN":"名词指变化本身，动词只表示「施加」，因此必须用介词引出被改变的对象。"},{"no":"02","title":"An action on a body or material","titleCN":"作用于物体或身体","definition":"to act physically on an object, substance or organ","definitionCN":"在物理层面对物体、物质或器官发生作用","example":"Low humidity can have an effect on how wood expands in summer.","exampleCN":"湿度过低会影响木材在夏季的膨胀程度。","why":"When the object is a material, the change is physical rather than statistical, but the frame stays the same.","whyCN":"当对象是材料时，改变是物理性的而非统计性的，但句式框架不变。"},{"no":"03","title":"Working as intended","titleCN":"产生预期作用","definition":"to produce the result that was planned or hoped for","definitionCN":"产生原本计划或期待的结果","example":"The new filter should have an effect on the water within a week.","exampleCN":"新滤芯应在一周内对水质产生作用。","why":"This sense adds expectation: the speaker already assumes a mechanism and only asks whether it works.","whyCN":"这一义项带有预期：说话人已假定存在某种机制，只问它是否奏效。"},{"no":"04","title":"A harmful or side effect","titleCN":"产生不良作用","definition":"to cause an unwanted change, often with adverse or side-effect as the modifier","definitionCN":"引起不想要的变化，常与「不利」「副作用」一类修饰语连用","example":"Some drugs have an effect on liver function when taken daily.","exampleCN":"有些药物每天服用会对肝功能产生影响。","why":"The frame itself is neutral; harm comes from the modifier, which is why adverse sits so often before effect.","whyCN":"句式本身是中性的，害处来自修饰语，所以「不利」一词常放在名词前。"},{"no":"05","title":"Influence on a decision","titleCN":"影响决定","definition":"to sway how a person or body chooses","definitionCN":"左右个人或机构作出选择","example":"Public protests have an effect on how councils set parking fees.","exampleCN":"公众抗议会影响市议会对停车费的设定。","why":"When the object is a decision or policy, the change happens inside an institution rather than in matter.","whyCN":"当对象是决定或政策时，改变发生在机构内部，而不在物质层面。"},{"no":"06","title":"A weak or strong force","titleCN":"影响有强弱之分","definition":"to matter to a greater or lesser degree, often graded by little, some or no","definitionCN":"以不同程度起作用，常由「几乎没有」「一些」「没有」等词标示强弱","example":"Single reviews rarely have an effect on overall sales.","exampleCN":"单条评价很少会对整体销量产生影响。","why":"Because the noun is countable here, the phrase can be graded by articles and quantifiers, which is how writers calibrate force.","whyCN":"这里的名词可数，因而能用冠词与量词调节力度，写作者借此控制影响的强弱。"},{"no":"07","title":"In academic causal writing","titleCN":"学术因果表述","definition":"used in research prose to name one variable that changes another","definitionCN":"在学术写作中标出改变另一个变量的某个因素","example":"Both temperature and light have an effect on the rate at which enzymes work.","exampleCN":"温度与光照都会对酶的作用速率产生影响。","why":"Research writing prefers this frame over a bare verb because it keeps cause and affected variable in separate slots.","whyCN":"学术写作偏爱这一框架而非单个动词，因为它把原因与受影响变量分置两处。"},{"no":"08","title":"Mattering over time","titleCN":"长期起作用","definition":"to leave a trace that shows up later rather than at once","definitionCN":"留下稍后才显现的痕迹，而非立即见效","example":"Early schooling can have an effect on later earnings.","exampleCN":"早期教育会对日后的收入产生影响。","why":"With a long time span the change is a trace, not an event, so the phrase often takes can and a future-time adverbial.","whyCN":"时间跨度一长，改变是痕迹而非事件，因此常与情态词和将来时间状语连用。"}],"etymology":{"intro":{"en":"Effect and its verb come from Latin efficere, built on ex-, out, and facere, to do or make. The noun effectus then passed through Old French into English. The fixed English phrase is later than the noun, and its first date is approximate.","cn":"effect 及其动词源自拉丁语 efficere，由 ex-「出」与 facere「做、造」构成；名词 effectus 经古法语进入英语。英语固定短语晚于名词出现，确切首见年代为约数。"},"items":[{"era":"LATIN FACERE","en":"Facere means to do or to make and underlies factory, fiction and manufacture.","cn":"facere 意为「做、造」，也是 factory、fiction、manufacture 的根基。"},{"era":"LATIN EX-","en":"The prefix ex- means out, so the compound pictures a result being worked out.","cn":"前缀 ex- 意为「出」，复合词画出结果被「做出来」的画面。"},{"era":"LATIN EFFICERE","en":"Efficere means to work out, accomplish or bring about.","cn":"efficere 意为「做出、完成、促成」。"},{"era":"LATIN EFFECTUS","en":"The fourth-declension noun effectus names the thing accomplished.","cn":"第四变格法名词 effectus 指「被完成之事」。"},{"era":"OLD FRENCH AND ENGLISH","en":"Effect entered English through Old French; the modern noun is recorded from the Middle English period.","cn":"effect 经古法语进入英语，现代名词形自中古英语时期有记录。"},{"era":"ENGLISH FIXED PHRASE","en":"The collocation is a modern English frame; the exact first date is approximate.","cn":"这一「动词加名词加介词」的搭配属近代英语框架，确切首见年代为约数。"}]},"similar":{"note":{"en":"The first group keeps the same noun slot but changes the force or the verb; the second group holds verbs that describe the change itself.","cn":"第一组保留同一名词位置，只改变力度或动词；第二组是直接描述改变本身的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"have an impact on","ipa":"/hæv ən ˈɪmpækt ɒn/","tag":"stronger force","definition":"Impact suggests a sharp, often decisive blow; effect can be slight or gradual.","definitionCN":"impact 暗示猛烈、往往有决定性的冲击；effect 可以是轻微或渐进的。"},{"word":"have an influence on","ipa":"/hæv ən ˈɪnfluəns ɒn/","tag":"people and gradual change","definition":"Influence is preferred for shaping opinions, habits or people over time.","definitionCN":"influence 多用于长期塑造观点、习惯或人。"},{"word":"have an effect upon","ipa":"/hæv ən ɪˈfekt əˈpɒn/","tag":"formal variant","definition":"Upon is the bookish alternative to on and appears in older or legal prose.","definitionCN":"upon 是 on 的书面替代，多见于较早或法律文本。"},{"word":"have an affect on","ipa":"/hæv ən əˈfekt ɒn/","tag":"nonstandard confusion","definition":"Affect is the verb and effect the noun; this spelling is a common error, not a variant.","definitionCN":"affect 是动词、effect 是名词，这种写法是常见错误而非变体。"}]},{"heading":"NEAR MEANING","entries":[{"word":"affect","ipa":"/əˈfekt/","tag":"verb, direct object","definition":"It takes the object directly, with no preposition: the delay affected cost.","definitionCN":"它直接带宾语，不用介词：拖延影响了成本。"},{"word":"influence","ipa":"/ˈɪnfluəns/","tag":"verb or noun","definition":"It stresses shaping a choice or course rather than producing a measurable change.","definitionCN":"它强调塑造选择或走向，而非产生可测量的改变。"},{"word":"shape","ipa":"/ʃeɪp/","tag":"outcome and development","definition":"It pictures the slow forming of a result, common in social science.","definitionCN":"它画出结果被慢慢塑形的过程，多见于社会科学。"},{"word":"alter","ipa":"/ˈɔːltə/","tag":"make different","definition":"It states that something becomes different, without naming a cause or degree.","definitionCN":"它只说明某物变得不同，不点出原因或程度。"}]}]},"mnemonics":{"normalIntro":{"en":"The normal associations use the real Latin pair, the countable noun and the preposition rule.","cn":"正常联想使用真实拉丁语对、可数名词与介词规则。"},"normal":[{"en":"Facere is to make, so an effect is something made out.","cn":"facere 是「造」，effect 就是被造出来的东西。"},{"en":"The verb have carries the action; effect is only the thing carried.","cn":"动词只负责「施加」，effect 只是被施加之物。"},{"en":"On names the target, never a clause: effect on sales, not effect that sales rose.","cn":"介词引出对象，从不接从句。"},{"en":"Because effect is countable, little and no can grade it.","cn":"effect 可数，因此能用「几乎没有」「没有」计量。"},{"en":"Affect is the verb, effect the noun, and one letter separates them.","cn":"一个字母之差：前者是动词，后者是名词。"}],"abstract":[{"en":"Like a stone dropped in still water: the circles reach the far buoy.","cn":"像石子落入静水，波纹一直推到远处的浮标。"},{"en":"Like a hand pressed on a scale: the needle moves, the hand is not the weight.","cn":"像手按在天平上：指针动了，手本身不是重量。"},{"en":"Like a slow dye spreading through cloth, visible only after some time.","cn":"像染料在布上慢慢洇开，过些时候才看得见。"}]},"examples":[{"en":"Rising sea levels have an effect on coastal farmland.","cn":"海平面上升会对沿海农田产生影响。"},{"en":"The training programme can have an effect on how staff handle complaints.","cn":"培训计划会影响员工处理投诉的方式。"},{"en":"Even a small change in pH may have an effect on fish populations.","cn":"即便酸碱度的小变化也可能影响鱼类种群。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「哈夫 安 艾费克特 昂」——往水面丢一颗石子，波纹一路推到浮标：对……有影响","word":"have an effect on"},"root":"effect 源自拉丁语 effectus，出自动词 efficere，由表示「出」的前缀与 facere「做、造」构成；该固定搭配的首见年代为约数。","sensesIntro":{"en":"Eight senses split by the kind of object affected and by the force of the change: state, material, intended working, side effect, decision, graded strength, academic variables and long-term traces.","cn":"八个义项按受影响对象的类别与力度区分：状态、材料、预期作用、副作用、决定、强弱分级、学术变量、长期痕迹。"},"semanticMap":{"core":{"en":"CORE IMAGE: a stone dropped into still water, its rings travelling outward to a buoy.","cn":"核心意象：石子落入静水，波纹向外推到浮标。"},"chain":["MAKE OUT","REACH A STATE","ACT ON MATTER","WORK AS PLANNED","SIDE EFFECT","MEASURED TRACE"],"branches":[{"senses":"01 · 07","en":"THE MEASURABLE CHANGE: a variable alters another and the result can be recorded.","cn":"可测量的改变：一个变量改变另一个变量，结果能被记录。"},{"senses":"02","en":"THE MATERIAL: the object is physical, so the change shows in size, weight or structure.","cn":"材料：对象是实物，改变体现在尺寸、重量或结构上。"},{"senses":"03","en":"THE MECHANISM THAT WORKS: expectation is added and the question is whether it functions.","cn":"奏效的机制：加上预期，问题变成它是否起作用。"},{"senses":"04","en":"THE UNWANTED CHANGE: harm comes from the modifier rather than the frame.","cn":"不想要的变化：害处来自修饰语而非句式。"},{"senses":"05 · 06 · 08","en":"THE DEGREE: decisions, graded force and long traces all ask how much and for how long.","cn":"程度：决定、分级力度与长期痕迹都在问影响多大、持续多久。"}]},"affixes":{"intro":{"en":"The core is Latin facere with the prefix ex-; the noun effectus supplies the English noun inside the phrase.","cn":"核心是拉丁语 facere 加前缀 ex-；名词 effectus 提供短语中的英语名词。"},"latinIntro":{"en":"The Latin pair is ex-, out, and facere, to do or make; efficere combines them.","cn":"拉丁语成分是 ex-「出」与 facere「做、造」，efficere 由两者合成。"},"items":[{"word":"facere","structure":"Latin verb, third conjugation","meaning":"to do; to make","meaningCN":"做；造","example":"Facere underlies many English words about making.","exampleCN":"这个词是许多表示「制造」的英语词的根基。"},{"word":"ex-","structure":"Latin prefix","meaning":"out; forth","meaningCN":"出；向外","example":"The prefix pictures a result coming out of an action.","exampleCN":"前缀画出结果被做出来的画面。"},{"word":"efficere","structure":"ex- + facere, Latin verb","meaning":"to work out; accomplish","meaningCN":"做出；完成","example":"The compound verb supplies both the noun and the adjective.","exampleCN":"复合动词同时提供名词与形容词。"},{"word":"effectus","structure":"Latin noun, fourth declension","meaning":"the thing accomplished","meaningCN":"被完成之事；结果","example":"The noun names what an action leaves behind.","exampleCN":"名词指行动留下的东西。"},{"word":"effect","structure":"English noun","meaning":"result; influence","meaningCN":"效果；影响","example":"The English noun fills the middle slot of the phrase.","exampleCN":"英语名词占据短语中间的位置。"},{"word":"effective","structure":"effect + -ive","meaning":"producing the intended result","meaningCN":"有效的","example":"The adjective judges whether the effect happened.","exampleCN":"形容词判断效果是否发生。"},{"word":"effectiveness","structure":"effective + -ness","meaning":"the quality of working","meaningCN":"有效性","example":"The noun measures how well the effect is produced.","exampleCN":"名词衡量效果产生的程度。"},{"word":"affect","structure":"Latin afficere, related verb","meaning":"to act on; influence","meaningCN":"影响","example":"A related verb from the same root, now used as the verb partner.","exampleCN":"同根的另一动词，现作动词搭档使用。"},{"word":"ineffective","structure":"in- + effective","meaning":"not producing the result","meaningCN":"无效的","example":"The negative form marks a missing effect.","exampleCN":"否定形式标示效果缺失。"}],"latinEntries":[{"word":"facere","structure":"facere, facio, feci, factum (verb, third conjugation)","meaning":"to do; make","meaningCN":"做；造"},{"word":"efficere","structure":"efficere, efficio, effeci, effectum (ex- + facere)","meaning":"to work out; accomplish","meaningCN":"做出；完成"},{"word":"effectus","structure":"effectus, -us (noun, fourth declension)","meaning":"result; accomplishment","meaningCN":"结果；成效"}],"derivatives":[{"word":"effect","pos":"n.","zh":"效果；影响"},{"word":"effective","pos":"adj.","zh":"有效的"},{"word":"effectiveness","pos":"n.","zh":"有效性"},{"word":"affect","pos":"v.","zh":"影响（动词形）"},{"word":"ineffective","pos":"adj.","zh":"无效的"}]}},{"word":"in comparison with","ipa_uk":"/ɪn kəmˈpærɪsn wɪð/","ipa_us":"/ɪn kəmˈperɪsn wɪð/","definition_zh":"与……相比；把两者放在同一标准上衡量，以看出高低或异同","definition_en":"used when two things are weighed on the same scale in order to show how they differ in amount, quality or level","core_image":"两块厚薄不同的布样并排摆在同一条刻度尺上，指针各停在一格","scene":"质检台上两块布样并排压在同一条刻度尺下，指针各停在一格。In comparison with last year's fabric, this year's is slightly thinner.","sceneCN":"这里指把今年与去年的布料放在同一标准上量（第 1 个义项：与……相比）；句意为与去年的布料相比，今年的略薄一些。图中可辨识物件：布样、刻度尺、指针。","pos":[{"tag":"prep. phr.","zh":"介词短语：与……相比"},{"tag":"adv. phr.","zh":"状语短语：比较之下"}],"collocations":[{"phrase":"in comparison with the previous year","zh":"与上一年相比"},{"phrase":"in comparison with other regions","zh":"与其他地区相比"},{"phrase":"in comparison with the standard model","zh":"与标准型号相比"},{"phrase":"in comparison with earlier studies","zh":"与早先研究相比"},{"phrase":"in direct comparison with","zh":"与……直接比较"},{"phrase":"in comparison with the average","zh":"与平均值相比"}],"forms":[{"label":"原形","form":"in comparison with"},{"label":"介词变体","form":"in comparison to"},{"label":"独立连接语","form":"by comparison"},{"label":"动词短语","form":"compare with"},{"label":"名词","form":"comparison"}],"derivatives":[{"word":"compare","pos":"v.","zh":"由拉丁语「配对、等同」动词经法语而来，义为「比较」"},{"word":"comparison","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「比较」"},{"word":"comparable","pos":"adj.","zh":"由该名词加「可……的」形容词尾构成，义为「可比的」"},{"word":"comparative","pos":"adj./n.","zh":"由该词干加表示关系的形容词尾构成，义为「比较的；比较级」"},{"word":"comparably","pos":"adv.","zh":"由形容词加副词尾构成，义为「同样地」"},{"word":"incomparable","pos":"adj.","zh":"由否定前缀加形容词构成，义为「无可比拟的」"}],"senses":[{"no":"01","title":"Weighing two like things","titleCN":"把同类事物放在同一标准上比","definition":"used to set two comparable things on one scale","definitionCN":"把两个可比的对象放在同一个衡量标准上","example":"In comparison with the earlier model, the new engine uses far less fuel.","exampleCN":"与早先的型号相比，新发动机耗油少得多。","why":"The phrase assumes a shared measure; that is why the two items must belong to the same class.","whyCN":"这一短语预设存在共同的衡量标准，因此两个对象必须属于同一类别。"},{"no":"02","title":"The fronted frame","titleCN":"句首框架：相比之下","definition":"placed at the front of a clause to name the benchmark before making the point","definitionCN":"置于从句开头，先说基准，再给出结论","example":"In comparison with earlier estimates, the final figure looks modest.","exampleCN":"与早先的估计相比，最终数字显得温和。","why":"Fronting the phrase tells the reader which item is the yardstick before the judgement arrives.","whyCN":"把它提到句首，读者先知道哪一项是尺子，再收到判断。"},{"no":"03","title":"Statistical comparison","titleCN":"数据与统计比较","definition":"used when two sets of figures are set side by side","definitionCN":"把两组数字并置时使用","example":"In comparison with the 2018 figures, the 2024 figures rose by a fifth.","exampleCN":"与 2018 年的数字相比，2024 年的数字上升了五分之一。","why":"Numbers need a declared baseline, and this phrase supplies it in one stroke.","whyCN":"数字需要明确的基准，这个短语一笔就交代清楚。"},{"no":"04","title":"Benchmarking against a standard","titleCN":"以标准为基准衡量","definition":"used in quality work to measure a product against an agreed standard","definitionCN":"在质量管理中把产品与约定标准对照","example":"In comparison with the industry standard, the sample failed on two measures.","exampleCN":"与行业标准相比，该样品在两项指标上不合格。","why":"Here the second item is not a rival product but a fixed yardstick, so the phrase measures compliance rather than preference.","whyCN":"这里的第二项不是竞争产品而是固定标尺，因此衡量的是合规而非喜好。"},{"no":"05","title":"Academic group comparison","titleCN":"学术对照组比较","definition":"used in research writing to contrast an experimental group with a baseline group","definitionCN":"在研究写作中把实验组与基线组并置","example":"In comparison with the baseline group, the trained group recalled more words.","exampleCN":"与基线组相比，受训组回忆出的单词更多。","why":"Research prose needs the baseline named explicitly, and this frame keeps the two groups in one sentence.","whyCN":"研究写作需要明确点出基线，这一框架把两组放进同一句。"},{"no":"06","title":"A relative judgement","titleCN":"评价优劣的相对判断","definition":"used to judge one thing as better, worse or larger than another","definitionCN":"判断一物比另一物更好、更差或更大","example":"In comparison with the older treatment, the new one is both cheaper and safer.","exampleCN":"与旧疗法相比，新疗法既便宜又安全。","why":"The phrase licenses a comparative adjective in the main clause, because a scale has already been set.","whyCN":"短语为主句里的比较级形容词提供依据，因为尺度已经立好。"},{"no":"07","title":"A share of the whole","titleCN":"相对于整体的比例","definition":"used to set a part against the total it belongs to","definitionCN":"把部分与它所属的整体对照","example":"In comparison with the whole budget, the research share is tiny.","exampleCN":"与整个预算相比，研究所占的份额很小。","why":"A part-to-whole ratio is still a comparison, but the second term is the container rather than a rival.","whyCN":"部分与整体的比率仍是比较，只是第二项是容器而非对手。"},{"no":"08","title":"Comparison, not opposition","titleCN":"比较而非对立","definition":"used to measure degree on a shared scale, where in contrast to would mark opposition","definitionCN":"在同一尺度上衡量程度，而「与……形成对照」则标示对立","example":"In comparison with the northern route, the southern route is merely longer.","exampleCN":"与北线相比，南线只是更长一些。","why":"The two phrases divide the work: comparison weighs, contrast opposes, and mixing them blurts the point.","whyCN":"两个短语分工：比较负责称量，对照负责对立，混用会让重点含糊。"}],"etymology":{"intro":{"en":"Comparison comes from Latin comparatio, built on comparare, to pair or match, itself from com-, together, and par, equal. The noun passed through Old French into English; the prepositional phrase is later and its first date is approximate.","cn":"comparison 源自拉丁语 comparatio，出自动词 comparare「配对、使相等」，后者由 com-「一起」与 par「相等」构成。名词经古法语进入英语；介词短语更晚，首见年代为约数。"},"items":[{"era":"LATIN PAR","en":"Par means equal and also gives parity and peer in English.","cn":"par 意为「相等」，也给出英语的 parity 与 peer。"},{"era":"LATIN COM-","en":"Com- means together, so the verb pictures two things placed side by side.","cn":"com- 意为「一起」，动词便画出两物并排的画面。"},{"era":"LATIN COMPARARE","en":"Comparare means to pair, match or bring together for weighing.","cn":"comparare 意为「配对、使相配、放在一起称量」。"},{"era":"LATIN COMPARATIO","en":"The noun names the act of setting two things on one scale.","cn":"名词指把两物放在同一尺度上的行为。"},{"era":"OLD FRENCH AND ENGLISH","en":"The word entered English through Old French comparaison in the Middle English period.","cn":"该词经古法语 comparaison 于中古英语时期进入英语。"},{"era":"ENGLISH PHRASE","en":"The frame in comparison with belongs to modern written English; its exact first date is approximate.","cn":"这一介词框架属近代书面英语，确切首见年代为约数。"}]},"similar":{"note":{"en":"The first group occupies the same slot and can be mistaken for this phrase; the second group holds other ways of naming a yardstick.","cn":"第一组占同一位置，容易被误认作本短语；第二组是其他点出标尺的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"in comparison to","ipa":"/ɪn kəmˈpærɪsn tuː/","tag":"same meaning, other preposition","definition":"To and with are interchangeable here, with with slightly more common in British writing.","definitionCN":"两个介词在此可互换，其中 with 在英式写作里略常见。"},{"word":"in contrast to","ipa":"/ɪn ˈkɒntrɑːst tuː/","tag":"opposition, not measurement","definition":"It stresses that two things are opposite rather than merely different in degree.","definitionCN":"它强调两物相反，而不只是程度不同。"},{"word":"compared with","ipa":"/kəmˈpeəd wɪð/","tag":"reduced participle","definition":"The participle drops the noun and works as a leaner opener.","definitionCN":"分词形式省去名词，作更精简的开头。"},{"word":"by comparison","ipa":"/baɪ kəmˈpærɪsn/","tag":"stand-alone connector","definition":"It stands alone between clauses and takes no benchmark after it.","definitionCN":"它独立用于句间，后面不带基准。"}]},{"heading":"NEAR MEANING","entries":[{"word":"relative to","ipa":"/ˈrelətɪv tuː/","tag":"proportional framing","definition":"It sets a value against a base, often in technical writing.","definitionCN":"它把数值放在基准之上，多用于技术写作。"},{"word":"against","ipa":"/əˈɡenst/","tag":"figures on a baseline","definition":"In charts, against introduces the standard that the data are plotted on.","definitionCN":"在图表中，它引出数据所依据的基准。"},{"word":"beside","ipa":"/bɪˈsaɪd/","tag":"side-by-side reading","definition":"It pictures two items placed next to each other for the eye to judge.","definitionCN":"它画出两物并排放置、由眼睛判断的画面。"},{"word":"versus","ipa":"/ˈvɜːsəs/","tag":"two sides in opposition","definition":"It sets two parties or options against each other, often in disputes.","definitionCN":"它把两方或两个选项对立起来，多用于争执。"}]}]},"mnemonics":{"normalIntro":{"en":"The normal associations use the real Latin pair, the real prepositions and the comparison-contrast division of labour.","cn":"正常联想使用真实拉丁语对、真实介词以及比较与对照的分工。"},"normal":[{"en":"Par means equal, so comparison first makes the two items level.","cn":"par 意为「相等」，比较先要把两项摆平。"},{"en":"Com- means together, so the phrase always needs a second item.","cn":"com- 意为「一起」，短语总要有第二项。"},{"en":"With and to both work; with is the safer choice in British prose.","cn":"两个介词都可用，英式文字里 with 更稳妥。"},{"en":"Comparison weighs degree; contrast declares opposition.","cn":"比较称量程度，对照宣告对立。"},{"en":"The benchmark may be a rival, a standard or the whole that contains the part.","cn":"基准可以是对手、标准，也可以是包含部分的整体。"}],"abstract":[{"en":"Like two cloth samples pressed under one ruler, each pointer stopping at its own mark.","cn":"像两块布样压在同一把尺下，指针各停一格。"},{"en":"Like a balance beam with two pans, the reading only exists because both are loaded.","cn":"像两端都放了砝码的天平，读数因两边同时受载才存在。"},{"en":"Like a map scale bar: the distance means nothing until the bar is laid beside it.","cn":"像地图上的比例尺，不放上去距离就没有意义。"}]},"examples":[{"en":"In comparison with the 2019 survey, the 2024 survey found fewer first-time buyers.","cn":"与 2019 年的调查相比，2024 年的调查发现首次购房者更少。"},{"en":"In comparison with the control group, the treated group recovered faster.","cn":"与对照组相比，治疗组恢复得更快。"},{"en":"In comparison with the whole budget, training costs remain small.","cn":"与整个预算相比，培训费用仍然很小。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「因 康帕瑞森 维兹」——两块布样压在同一把尺下，指针各停一格：与……相比","word":"in comparison with"},"root":"comparison 源自拉丁语 comparatio，出自动词 comparare，由表示「一起」的前缀与 par「相等」构成；该介词框架属近代书面英语，首见年代为约数。","sensesIntro":{"en":"Eight senses split by the role of the second item: a like rival, a fronted benchmark, two data sets, an industry standard, a control group, a comparative judgement, a part-to-whole ratio, and the comparison-versus-contrast division.","cn":"八个义项按第二项的角色区分：同类对手、前置基准、两组数据、行业标准、对照组、优劣判断、部分与整体、比较与对照的分工。"},"semanticMap":{"core":{"en":"CORE IMAGE: two cloth samples pressed under one ruler, each pointer stopping at its own mark.","cn":"核心意象：两块布样压在同一把尺下，指针各停一格。"},"chain":["PAIR AS EQUALS","SET ONE SCALE","FRONT THE BENCHMARK","READ THE GAP","JUDGE BETTER OR WORSE","SHARE OF A WHOLE"],"branches":[{"senses":"01 · 02","en":"THE SHARED SCALE: two like things are levelled before any judgement is made.","cn":"共同尺度：两个同类先被摆平，再作判断。"},{"senses":"03 · 05","en":"THE TWO GROUPS: figures and control groups need a named baseline.","cn":"两组对象：数字与对照组都需要点明基准。"},{"senses":"04","en":"THE STANDARD: the second item is a fixed rule, so the reading measures compliance.","cn":"标准：第二项是固定规则，读数衡量的是合规。"},{"senses":"06","en":"THE VERDICT: a comparative adjective follows because the scale is already set.","cn":"判断：尺度既定，比较级形容词才随之出现。"},{"senses":"07 · 08","en":"THE CONTAINER AND THE CONTRAST: part against whole, comparison against opposition.","cn":"容器与对立：部分对整体，比较对对立的划分。"}]},"affixes":{"intro":{"en":"The Latin core is par, equal, with com-, together; comparare and comparatio supply the English family.","cn":"拉丁核心是 par「相等」加 com-「一起」；comparare 与 comparatio 提供英语同族词。"},"latinIntro":{"en":"The Latin elements are par, equal, and com-, together; the verb comparare joins them.","cn":"拉丁成分是 par「相等」与 com-「一起」，动词 comparare 由两者合成。"},"items":[{"word":"par","structure":"Latin adjective and noun","meaning":"equal","meaningCN":"相等的","example":"Par also survives in English as a golf and finance term.","exampleCN":"这个词在英语里还活用于高尔夫与金融术语。"},{"word":"com-","structure":"Latin prefix","meaning":"together; with","meaningCN":"一起；共同","example":"The prefix makes the act a joint one.","exampleCN":"前缀让这个动作成为共同行为。"},{"word":"comparare","structure":"com- + par, Latin verb","meaning":"to pair; match","meaningCN":"配对；使相等","example":"The verb supplies the whole English family.","exampleCN":"这个动词提供整族英语词。"},{"word":"comparatio","structure":"Latin noun, third declension","meaning":"a setting side by side","meaningCN":"并置比较","example":"The noun names the act, not the result.","exampleCN":"名词指行为，而非结果。"},{"word":"comparison","structure":"English noun","meaning":"the act or result of comparing","meaningCN":"比较","example":"The noun fills the middle of the fixed phrase.","exampleCN":"名词占据固定短语的中间位置。"},{"word":"compare","structure":"English verb","meaning":"to set side by side","meaningCN":"比较","example":"The verb is the plain form behind the noun.","exampleCN":"动词是名词背后的朴素形式。"},{"word":"comparable","structure":"compare + -able","meaning":"able to be compared","meaningCN":"可比的","example":"The suffix marks capacity, not achievement.","exampleCN":"后缀标记能力，而非已完成。"},{"word":"comparative","structure":"compare + -ative","meaning":"expressing comparison","meaningCN":"比较的；比较级","example":"Grammar uses the term for the -er form.","exampleCN":"语法学用这个词指比较级形式。"}],"latinEntries":[{"word":"par","structure":"par (adjective and noun)","meaning":"equal","meaningCN":"相等的"},{"word":"comparare","structure":"comparare, comparo, comparavi, comparatum (verb, first conjugation)","meaning":"to pair; match","meaningCN":"配对；使相等"}],"derivatives":[{"word":"compare","pos":"v.","zh":"比较"},{"word":"comparison","pos":"n.","zh":"比较"},{"word":"comparable","pos":"adj.","zh":"可比的"},{"word":"comparative","pos":"adj./n.","zh":"比较的；比较级"},{"word":"incomparable","pos":"adj.","zh":"无可比拟的"}]}},{"word":"in contrast to","ipa_uk":"/ɪn ˈkɒntrɑːst tuː/","ipa_us":"/ɪn ˈkɑːntræst tuː/","definition_zh":"与……形成鲜明对照；与……截然相反，用来突出两者的对立或差别","definition_en":"used to introduce a thing that differs sharply from the one just mentioned or from what would be expected","core_image":"同一张展台上左边满杯、右边空杯，两束灯光的颜色正好相反","scene":"展台两侧并排放着满杯与空杯，标签特意标出两者的差别。In contrast to the first case, the second case held an empty cup.","sceneCN":"这里指第二个展柜与第一个恰好相反（第 1 个义项：与……形成鲜明对照）；句意为与第一个展柜不同，第二个展柜里是空杯。图中可辨识物件：展台、满杯、空杯、两束灯光。","pos":[{"tag":"prep. phr.","zh":"介词短语：与……形成对照"},{"tag":"adv. phr.","zh":"状语短语：相比之下"}],"collocations":[{"phrase":"in sharp contrast to","zh":"与……形成鲜明对比"},{"phrase":"in marked contrast to","zh":"与……形成显著对照"},{"phrase":"in direct contrast to","zh":"与……截然相反"},{"phrase":"in contrast to earlier findings","zh":"与早先的发现相反"},{"phrase":"in contrast to popular belief","zh":"与普遍看法相反"},{"phrase":"stand in contrast to","zh":"与……形成对照"},{"phrase":"in contrast to the situation elsewhere","zh":"与别处的情况相反"}],"forms":[{"label":"原形","form":"in contrast to"},{"label":"介词变体","form":"in contrast with"},{"label":"独立连接语","form":"by contrast"},{"label":"名词","form":"contrast"},{"label":"动词","form":"contrast with"}],"derivatives":[{"word":"contrast","pos":"n./v.","zh":"由拉丁语「对立而站」一系经意大利语、法语而来，义为「对照；形成对比」"},{"word":"contrastive","pos":"adj.","zh":"由该名词加「有……性质」的形容词尾构成，义为「对比的」"},{"word":"contrastingly","pos":"adv.","zh":"由形容词加副词尾构成，义为「对比之下」"},{"word":"by contrast","pos":"adv. phr.","zh":"由介词加名词构成的独立连接语，义为「相比之下」"},{"word":"contrast with","pos":"v. phr.","zh":"由动词加介词构成，义为「与……形成对比」"}],"senses":[{"no":"01","title":"A sharp opposition","titleCN":"与……截然相反","definition":"used to set a thing against another that is sharply different","definitionCN":"把一物与另一明显不同之物并置","example":"In contrast to the coastal towns, the inland villages lost population.","exampleCN":"与沿海城镇相反，内陆村庄人口减少。","why":"The preposition names the second term, and the sentence asserts a difference rather than a shared measure.","whyCN":"介词点出第二项，句子断言的是差异而不是共同的尺度。"},{"no":"02","title":"The fronted frame","titleCN":"句首框架：相比之下","definition":"placed at the front of a clause to announce that the opposite case follows","definitionCN":"置于从句开头，宣告接下来是相反的情形","example":"In contrast to the north, the south relies on service industries.","exampleCN":"与北方相反，南方依靠服务业。","why":"Fronting makes the contrast structural: the reader knows the second half will mirror, then reverse, the first.","whyCN":"前置让对照成为结构性的：读者知道后半句先对应、后反转前半句。"},{"no":"03","title":"Against expectation","titleCN":"与预期或普遍看法相反","definition":"used to correct an assumption that the reader is likely to hold","definitionCN":"用来纠正读者可能持有的假设","example":"In contrast to popular belief, the desert supports a rich microbial life.","exampleCN":"与普遍看法相反，沙漠里生活着丰富的微生物。","why":"Here the first term is not a fact but a belief, so the phrase does the work of a correction.","whyCN":"这里的第一项不是事实而是看法，短语因此承担纠正的功能。"},{"no":"04","title":"Against the evidence","titleCN":"与研究证据相反","definition":"used in research writing to introduce a result that opposes an earlier one","definitionCN":"在研究写作中引出与先前结果相反的结果","example":"In contrast to the earlier trial, the second trial found no benefit.","exampleCN":"与早先的试验相反，第二次试验没有发现益处。","why":"Research prose needs to mark disagreement without calling the earlier work wrong, and this frame does exactly that.","whyCN":"研究写作需要标出分歧又不判定早先工作错误，这一框架正好做到。"},{"no":"05","title":"A difference in kind","titleCN":"性质上的不同","definition":"used when two things differ in nature rather than in degree","definitionCN":"两者在性质上不同，而非程度不同","example":"In contrast to a loan, a grant never has to be repaid.","exampleCN":"与贷款不同，赠款从不需要偿还。","why":"When the difference is categorical, contrast is the right tool and comparison would understate it.","whyCN":"差异是类别性的时候，对照才合适，比较会低估它。"},{"no":"06","title":"Syntactic division of labour","titleCN":"与独立连接语的分工","definition":"used with a following noun, where by contrast would stand alone","definitionCN":"后面接名词，而独立连接语则单独使用","example":"In contrast to the first group, the second group met every target.","exampleCN":"与第一组相反，第二组达成了全部目标。","why":"The two forms split the work: this one takes a benchmark, while by contrast takes none.","whyCN":"两种形式分工：这一个带基准，另一个不带。"},{"no":"07","title":"Graded sharpness","titleCN":"强调对照的强度","definition":"used with sharp or marked to raise the force of the difference","definitionCN":"与「鲜明的」「显著的」一类词连用以提高差异的力度","example":"In contrast to last year, sales fell in every region, a sharp reversal.","exampleCN":"与去年相反，各地销量都下降了，形成鲜明反转。","why":"The modifier sits inside the phrase, so force is added without changing the frame.","whyCN":"修饰语插在短语内部，力度增强而框架不变。"},{"no":"08","title":"Parallel-structure contrast","titleCN":"平行结构中的对照","definition":"used to balance two opposite statements in one sentence","definitionCN":"在同一句中平衡两个相反的陈述","example":"In contrast to the north, where prices rose, the south saw prices fall.","exampleCN":"与物价上涨的北方相反，南方物价下跌。","why":"Parallel wording makes the reversal measurable; the phrase marks where the second half begins.","whyCN":"平行措辞让反转可衡量，短语标出后半句的起点。"}],"etymology":{"intro":{"en":"Contrast came into English through French from Italian contrastare, a verb reconstructed in Vulgar Latin from Latin contra, against, and stare, to stand. The reconstruction is reliable; the date of the English phrase is approximate.","cn":"contrast 经法语、意大利语进入英语，其动词是通俗拉丁语中由 contra「反对」与 stare「站立」构成的重构形式。该重构可靠；英语短语的年代为约数。"},"items":[{"era":"LATIN CONTRA","en":"Contra means against and appears in contradiction and contraflow.","cn":"contra 意为「反对」，也出现在 contradiction 与 contraflow 中。"},{"era":"LATIN STARE","en":"Stare means to stand, giving the picture of two things standing face to face.","cn":"stare 意为「站立」，画出两物面对面站立的画面。"},{"era":"VULGAR LATIN CONTRASTARE","en":"The reconstructed verb meant to stand against or withstand.","cn":"重构动词意为「对立而站、抵抗」。"},{"era":"ITALIAN AND FRENCH","en":"Italian contrastare passed into French as contraster and then into English in the sixteenth century.","cn":"意大利语 contrastare 传入法语作 contraster，十六世纪再进入英语。"},{"era":"ENGLISH PHRASAL USE","en":"The prepositional frame belongs to modern written English; the exact first date is approximate.","cn":"这一介词框架属近代书面英语，确切首见年代为约数。"}]},"similar":{"note":{"en":"The first group shares the contrast slot with different prepositions or functions; the second group holds other ways of marking opposition.","cn":"第一组占同一对照位置，但介词或功能不同；第二组是其他标记对立的方式。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"in contrast with","ipa":"/ɪn ˈkɒntrɑːst wɪð/","tag":"formal variant","definition":"With is the older and more bookish partner of to, with the same meaning.","definitionCN":"with 是 to 更旧、更书面的搭档，意义相同。"},{"word":"in comparison with","ipa":"/ɪn kəmˈpærɪsn wɪð/","tag":"measurement, not opposition","definition":"It weighs two items on one scale rather than declaring them opposite.","definitionCN":"它把两项放在同一尺度上称量，而非宣告对立。"},{"word":"by contrast","ipa":"/baɪ ˈkɒntrɑːst/","tag":"stand-alone connector","definition":"It works alone between clauses and takes no noun after it.","definitionCN":"它独立用于句间，后面不接名词。"},{"word":"on the contrary","ipa":"/ɒn ðə ˈkɒntrəri/","tag":"denial of a negative","definition":"It rejects a stated negative claim; contrast merely sets two facts side by side.","definitionCN":"它否定被说出的否定命题；对照只把两件事并置。"}]},{"heading":"NEAR MEANING","entries":[{"word":"unlike","ipa":"/ʌnˈlaɪk/","tag":"preposition, single word","definition":"It simply names the different item, with no signal of rhetorical weight.","definitionCN":"它只点出不同之物，不带修辞力度的信号。"},{"word":"whereas","ipa":"/ˌweərˈæz/","tag":"clausal conjunction","definition":"It joins two full clauses that differ, common in formal and legal writing.","definitionCN":"它连接两个不同的完整从句，多见于正式与法律文本。"},{"word":"as opposed to","ipa":"/əz əˈpəʊzd tuː/","tag":"choice between alternatives","definition":"It separates two options and usually implies a preference.","definitionCN":"它把两个选项分开，通常暗示偏好。"},{"word":"conversely","ipa":"/kənˈvɜːsli/","tag":"inverse relation","definition":"It marks the reverse side of a relation rather than a plain difference.","definitionCN":"它标出关系的反面，而非单纯差异。"}]}]},"mnemonics":{"normalIntro":{"en":"The normal associations use the real Latin pair, the real prepositions and the contrast-comparison split.","cn":"正常联想使用真实拉丁语对、真实介词以及对照与比较的分工。"},"normal":[{"en":"Contra is against and stare is to stand, so the two things stand face to face.","cn":"词根一是「反」、一是「站」，两物便面对面站着。"},{"en":"To takes a noun; by contrast stands alone.","cn":"带介词的形式接名词，独立形式单独使用。"},{"en":"At the front it announces the other side; mid-sentence it pivots.","cn":"句首宣告另一面，句中完成转折。"},{"en":"Sharp and marked go inside the phrase to raise the force.","cn":"表示「鲜明」「显著」的词插在短语内部增强力度。"},{"en":"Contrast opposes; comparison weighs. Mixing them weakens both.","cn":"对照管对立，比较管称量，混用会削弱两者。"}],"abstract":[{"en":"Like two lamps of opposite colours lit at the two ends of one table.","cn":"像同一张桌子两端亮起两盏颜色相反的灯。"},{"en":"Like a hinge in the middle of a sentence, letting the second half swing the other way.","cn":"像句子中间的一枚铰链，让后半句向另一边转。"},{"en":"Like a scale with one full pan and one empty pan, both visible at once.","cn":"像一架天平，一端满一端空，同时可见。"}]},"examples":[{"en":"In contrast to the earlier model, the new model runs on a single battery.","cn":"与早先的型号相反，新机型只靠一节电池运行。"},{"en":"In contrast to the coastal group, the inland group moved less.","cn":"与沿海组相反，内陆组流动更少。"},{"en":"In contrast to last winter, this winter has been mild.","cn":"与去年冬天相反，今年冬天一直温和。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「因 康特拉斯特 图」——满杯与空杯并排摆着，灯光颜色正好相反：与……形成对照","word":"in contrast to"},"root":"contrast 经法语、意大利语进入英语，其动词由拉丁语 contra「反对」与 stare「站立」构成通俗拉丁语重构形式；该介词框架属近代书面英语，首见年代为约数。","sensesIntro":{"en":"Eight senses split by what is being opposed: another fact, a fronted opposite case, an expectation, earlier evidence, a different kind, a syntactic partner, a graded difference and a parallel clause.","cn":"八个义项按对立对象区分：另一事实、前置相反情形、预期、早先证据、不同类别、句法搭档、分级差异、平行从句。"},"semanticMap":{"core":{"en":"CORE IMAGE: one full cup and one empty cup under two lights of opposite colour.","cn":"核心意象：满杯与空杯摆在两束相反颜色的灯光下。"},"chain":["STAND AGAINST","NAME THE OTHER TERM","REVERSE THE EXPECTATION","OPPOSE THE EVIDENCE","DIFFER IN KIND","GRADE THE GAP"],"branches":[{"senses":"01 · 02","en":"THE MIRROR: the second clause mirrors the first and then reverses it.","cn":"镜像：后半句先对应前半句，再反转。"},{"senses":"03","en":"THE CORRECTION: the first term is a belief, so the phrase sets the record straight.","cn":"纠正：第一项是看法，短语借此澄清事实。"},{"senses":"04","en":"THE COUNTER-EVIDENCE: research uses it to mark disagreement without blame.","cn":"反证：研究用它标出分歧而不追责。"},{"senses":"05 · 08","en":"THE CATEGORICAL GAP: two kinds or two parallel clauses are set apart.","cn":"类别落差：两个类别或两个平行从句被分开。"},{"senses":"06 · 07","en":"THE FRAME AND ITS FORCE: a following noun, plus sharp or marked inside.","cn":"框架与力度：后接名词，内部可加「鲜明」「显著」。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin preposition of opposition to a Latin verb of standing; the verb reached English through Italian and French.","cn":"短语把表对立的拉丁介词与表站立的拉丁动词结合起来；动词经意大利语、法语进入英语。"},"latinIntro":{"en":"The Latin etyma are contra, against, and stare, to stand; contrastare is the reconstructed Vulgar Latin link.","cn":"拉丁语词源是 contra「反对」与 stare「站立」；contrastare 是通俗拉丁语的重构环节。"},"items":[{"word":"contra","structure":"Latin preposition","meaning":"against; opposite","meaningCN":"反对；相对","example":"Contra appears in many English compounds of opposition.","exampleCN":"这个词出现在许多表对立的英语复合词里。"},{"word":"stare","structure":"Latin verb, first conjugation","meaning":"to stand","meaningCN":"站立","example":"The verb supplies the image of standing one's ground.","exampleCN":"这个动词提供「站定不退」的画面。"},{"word":"contrastare","structure":"Vulgar Latin verb, reconstructed","meaning":"to stand against","meaningCN":"对立而站","example":"The reconstructed verb links Latin to Italian.","exampleCN":"重构动词把拉丁语与意大利语接上。"},{"word":"contraster","structure":"Old French verb","meaning":"to contrast","meaningCN":"形成对比","example":"French carried the verb into English in the sixteenth century.","exampleCN":"法语在十六世纪把这个动词带入英语。"},{"word":"contrast","structure":"English noun and verb","meaning":"difference set side by side","meaningCN":"并置的差异","example":"The noun names the difference that the phrase points to.","exampleCN":"名词命名短语所指出的差异。"},{"word":"contrastive","structure":"contrast + -ive","meaning":"expressing contrast","meaningCN":"表示对比的","example":"Linguistics speaks of contrastive pairs.","exampleCN":"语言学讲「对比对」。"},{"word":"in contrast to","structure":"preposition + noun + preposition, fixed phrase","meaning":"by way of contrast with","meaningCN":"与……形成对照","example":"The phrase takes a noun as its benchmark.","exampleCN":"这个短语以名词作基准。"},{"word":"by contrast","structure":"preposition + noun, fixed phrase","meaning":"as a contrast","meaningCN":"相比之下（独立连接）","example":"Its twin usually stands alone between sentences.","exampleCN":"它的双胞胎通常在句间独立使用。"}],"latinEntries":[{"word":"contra","structure":"contra (preposition, with ablative)","meaning":"against","meaningCN":"反对"},{"word":"stare","structure":"stare, sto, steti, statum (verb, first conjugation)","meaning":"to stand","meaningCN":"站立"}],"derivatives":[{"word":"contrast","pos":"n./v.","zh":"对比；形成对照"},{"word":"contrastive","pos":"adj.","zh":"对比的；对照的"},{"word":"contrastingly","pos":"adv.","zh":"对比之下（少见）"},{"word":"by contrast","pos":"adv. phr.","zh":"相比之下"},{"word":"contrast with","pos":"v. phr.","zh":"与……形成对比"}]}},{"word":"lead to","ipa_uk":"/ˈliːd tuː/","ipa_us":"/ˈliːd tuː/","definition_zh":"导致；通向；引向某一结果、地点或结论","definition_en":"to cause something to happen, or to guide someone or something towards a place or result","core_image":"两条小路从山谷分头向上，尽头是同一间小屋","scene":"山脚两条小路一段段向上，尽头是一间小屋。Two paths from the valley lead to a small hut above the treeline.","sceneCN":"这里指小路通向山顶的小屋（第 2 个义项：通向某处）；句意为山谷里的两条小路都通向树线以上的一间小屋。图中可辨识物件：小路、山坡、树线、小屋。","pos":[{"tag":"v. phr.","zh":"动词短语：导致；通向"},{"tag":"idiom","zh":"固定搭配：引向某一结果"}],"collocations":[{"phrase":"lead to a decline","zh":"导致下降"},{"phrase":"lead to an increase","zh":"导致增加"},{"phrase":"lead to confusion","zh":"引起混乱"},{"phrase":"lead to a conclusion","zh":"引出结论"},{"phrase":"lead to serious consequences","zh":"导致严重后果"},{"phrase":"lead to the discovery of","zh":"引向……的发现"}],"forms":[{"label":"原形","form":"lead to"},{"label":"第三人称单数","form":"leads to"},{"label":"过去式","form":"led to"},{"label":"过去分词","form":"led to"},{"label":"现在分词","form":"leading to"}],"derivatives":[{"word":"lead","pos":"v./n.","zh":"由古英语「使行进」动词而来，义为「带领；引导」"},{"word":"leader","pos":"n.","zh":"由该动词加表示施事者的名词尾构成，义为「领导者」"},{"word":"leading","pos":"adj./n.","zh":"由该动词加形容词尾构成，义为「领先的；引导」"},{"word":"mislead","pos":"v.","zh":"由「错」前缀加该动词构成，义为「误导」"},{"word":"lead-up","pos":"n.","zh":"由该动词加副词构成的复合名词，义为「前奏；准备阶段」"}],"senses":[{"no":"01","title":"A causal chain","titleCN":"导致某一结果","definition":"to bring about a result through a chain of events","definitionCN":"通过一连串事件带来某个结果","example":"Poor drainage can lead to flooding in the lower fields.","exampleCN":"排水不畅会导致低处农田被淹。","why":"The preposition points to the end of a process, so the cause is presented as a route rather than a single blow.","whyCN":"介词指向过程终点，因此原因被呈现为一条路线，而非一次打击。"},{"no":"02","title":"A physical path","titleCN":"通向某处","definition":"to go in the direction of a place, of a road or passage","definitionCN":"道路或通道朝某个地点延伸","example":"Both paths lead to a small hut above the treeline.","exampleCN":"两条小路都通向树线以上的一间小屋。","why":"This is the literal sense: the verb keeps its old meaning of guiding, and to marks the destination.","whyCN":"这是字面义：动词保留「引导」的旧义，介词标出目的地。"},{"no":"03","title":"A medical consequence","titleCN":"引发疾病或症状","definition":"to cause a disease or symptom to develop","definitionCN":"使疾病或症状发生","example":"Repeated strain can lead to a torn ligament.","exampleCN":"反复劳损会引发韧带撕裂。","why":"In medicine the result is a condition rather than an event, and the chain is often gradual.","whyCN":"在医学里结果是状态而非事件，链条常是渐进的。"},{"no":"04","title":"Bringing about a decision","titleCN":"促成决定或行动","definition":"to cause someone or a group to decide or act","definitionCN":"使某人或某机构作出决定或采取行动","example":"The report can lead to a review of the safety rules.","exampleCN":"这份报告可能促成对安全规则的复查。","why":"Here the result is an institutional act, so the phrase describes influence on a decision process.","whyCN":"这里结果是机构行为，短语描述的是对决策过程的影响。"},{"no":"05","title":"A multi-step route to a conclusion","titleCN":"引向结论","definition":"to bring the argument or inquiry to a particular conclusion","definitionCN":"把论证或探究引到某个结论","example":"The same evidence can lead to two opposite conclusions.","exampleCN":"同一份证据可能引出两个相反的结论。","why":"With conclusions, the emphasis falls on the steps taken rather than on a single cause.","whyCN":"涉及结论时，重点在走过的步骤，而不在单一原因。"},{"no":"06","title":"Into trouble or dispute","titleCN":"使陷入困境或争议","definition":"to cause someone to enter a difficult or disputed situation","definitionCN":"使人进入困难或有争议的处境","example":"One careless remark can lead to a long dispute.","exampleCN":"一句不慎的话可能引发一场长期争执。","why":"The result here is a state one is stuck in, so the phrase often carries a negative colour.","whyCN":"这里的结果是陷进去的状态，因此短语常带负面色彩。"},{"no":"07","title":"Opening a topic","titleCN":"引出话题或问题","definition":"to move a conversation or text towards a new question","definitionCN":"把对话或文本引向新的问题","example":"These data lead to the question of who pays for the repair.","exampleCN":"这些数据引出了由谁支付修理费的问题。","why":"In exposition the phrase is a bridge, carrying the reader from one point to the next.","whyCN":"在说明文里，这个短语是一座桥，把读者从一点带到下一点。"},{"no":"08","title":"A long-term trend","titleCN":"最终造成长期趋势","definition":"to produce a tendency that shows only over a long period","definitionCN":"产生只有长期才显现的走势","example":"Years of small cuts can lead to a collapse of the service.","exampleCN":"多年小幅削减最终会导致该服务崩溃。","why":"When the outcome is a trend, the cause accumulates, which is why lead to suits it better than cause.","whyCN":"当结果是趋势时，原因在累积，因此用「通向」比用「造成」更合适。"}],"etymology":{"intro":{"en":"Lead comes from Old English lædan, to cause to go, from a Germanic causative verb reconstructed as laidijan, related to the verb behind load. The phrasal use with to is English and its first date is approximate.","cn":"lead 源自中古英语之前的 lædan，意为「使行进」，出自日耳曼语使动动词的重构形式，与 load 背后的动词同源。带介词的短语用法属英语，首见年代为约数。"},"items":[{"era":"OLD ENGLISH LÆDAN","en":"Lædan meant to cause to go or to guide, and it already took a direct object.","cn":"lædan 意为「使行进、引导」，且已可直接带宾语。"},{"era":"GERMANIC CAUSATIVE","en":"The reconstructed verb laidijan is a causative form, meaning to make something travel.","cn":"重构形式是使动形态，意为「使某物行进」。"},{"era":"GERMANIC FAMILY","en":"Related verbs survive in Dutch leiden and German leiten.","cn":"同族动词仍见于荷兰语与德语。"},{"era":"MIDDLE ENGLISH","en":"The verb settled into its modern spelling and kept the sense of guiding.","cn":"该动词在中古英语中定下现代拼写，保留「引导」义。"},{"era":"ENGLISH PHRASE","en":"The fixed frame is modern; the path of a process is the dominant image.","cn":"这一固定框架属近代用法，过程路径是其主要意象。"}]},"similar":{"note":{"en":"The first group shares the verb and changes the particle; the second group holds other causal verbs with different strengths.","cn":"第一组共用该动词而更换小品词；第二组是力度不同的其他因果动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"lead into","ipa":"/ˈliːd ˈɪntuː/","tag":"entering a topic or place","definition":"It marks entry into something, often a discussion or a room.","definitionCN":"它标记进入某物，常指话题或空间。"},{"word":"lead up to","ipa":"/ˈliːd ˈʌp tuː/","tag":"preparation over time","definition":"It covers the steps that prepare an event rather than the result itself.","definitionCN":"它覆盖为事件作准备的过程，而非结果本身。"},{"word":"lead on","ipa":"/ˈliːd ˈɒn/","tag":"deception","definition":"It means to mislead someone into following or believing, with no result named.","definitionCN":"意为诱使某人跟随或相信，不点出结果。"},{"word":"led to","ipa":"/led tuː/","tag":"past form","definition":"The past tense changes the vowel, a frequent error point.","definitionCN":"过去式换元音，是常见的错误点。"}]},{"heading":"NEAR MEANING","entries":[{"word":"result in","ipa":"/rɪˈzʌlt ɪn/","tag":"direct outcome","definition":"It states the outcome directly and leaves the process in the background.","definitionCN":"它直接说出结果，把过程退到背景。"},{"word":"cause","ipa":"/kɔːz/","tag":"single cause","definition":"It asserts a direct cause with no image of a route.","definitionCN":"它断言直接原因，不带路径意象。"},{"word":"bring about","ipa":"/brɪŋ əˈbaʊt/","tag":"deliberate change","definition":"It often implies an agent who intentionally produces the result.","definitionCN":"它常暗示有施事者有意造成结果。"},{"word":"give rise to","ipa":"/ɡɪv raɪz tuː/","tag":"formal origin","definition":"It pictures a result rising from a source, common in formal prose.","definitionCN":"它画出结果自源头升起，多见于正式文字。"}]}]},"mnemonics":{"normalIntro":{"en":"The normal associations use the real Old English verb, the irregular past form and the route image.","cn":"正常联想使用真实的古英语动词、不规则过去式与路径意象。"},"normal":[{"en":"The verb once meant to make something travel, so to marks the end of the route.","cn":"动词旧义是「使行进」，介词便标出路线终点。"},{"en":"The past tense is led, not leaded; the vowel changes.","cn":"过去式换元音，不是规则加尾。"},{"en":"With results, the phrase shows a process, which is why it fits slow accumulation.","cn":"涉及结果时它呈现过程，因此适合缓慢累积。"},{"en":"With places, the same frame is literal: a path leads to a hut.","cn":"涉及地点时同一框架是字面的：小路通向小屋。"},{"en":"It is weaker than cause on purpose: a route may have several steps.","cn":"它有意弱于「造成」：路线可以有多步。"}],"abstract":[{"en":"Like a staircase climbing a slope, each step invisible from the bottom.","cn":"像沿坡而上的石阶，站在山脚看不见每一级。"},{"en":"Like a river choosing a channel: the water ends somewhere, but the course explains how.","cn":"像河流选定了河道：水终会到某处，路线解释了过程。"},{"en":"Like a thread pulled through cloth, joining one point to the next.","cn":"像一根线穿过布面，把一点连到下一点。"}]},"examples":[{"en":"A shortage of parts can lead to delays across the whole line.","cn":"零件短缺会导致整条生产线延误。"},{"en":"The corridor can lead to a reading room on the second floor.","cn":"这条走廊可通向二楼的一间阅览室。"},{"en":"These findings lead to a simple conclusion about soil quality.","cn":"这些发现引出一个关于土壤质量的简单结论。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「利德 图」——山谷两条小路分头向上，尽头是同一间小屋：通向；导致","word":"lead to"},"root":"lead 源自中古英语之前的 lædan「使行进」，出自日耳曼语使动动词的重构形式，与 load 背后的动词同源；这一短语属近代英语，首见年代为约数。","sensesIntro":{"en":"Eight senses split by the kind of endpoint: a result, a place, a disease, a decision, a conclusion, a dispute, a new question and a long trend.","cn":"八个义项按终点类别区分：结果、地点、疾病、决定、结论、争执、新问题、长期趋势。"},"semanticMap":{"core":{"en":"CORE IMAGE: two paths climbing from the valley towards one small hut at the top.","cn":"核心意象：两条小路从山谷向上，尽头是同一间小屋。"},"chain":["CAUSE TO GO","MARK THE ENDPOINT","REACH A PLACE","TRIGGER A STATE","SHAPE A DECISION","ACCUMULATE OVER TIME"],"branches":[{"senses":"01 · 08","en":"THE ROUTE: the result arrives through steps, so slow accumulation fits the frame.","cn":"路线：结果经多步抵达，缓慢累积最合此框架。"},{"senses":"02","en":"THE DESTINATION: a path ends at a place and the verb stays literal.","cn":"终点：道路止于某地，动词仍是字面义。"},{"senses":"03 · 06","en":"THE STATE: disease and dispute are conditions one enters and stays in.","cn":"状态：疾病与争执是进入后停留的处境。"},{"senses":"04 · 05","en":"THE DECISION AND THE CONCLUSION: an institution acts, an argument closes.","cn":"决定与结论：机构采取行动，论证走向收束。"},{"senses":"07","en":"THE BRIDGE: exposition uses it to carry the reader to the next question.","cn":"桥接：说明文用它把读者带到下一个问题。"}]},"affixes":{"intro":{"en":"Lead is a Germanic verb, not a Latin one, so the affix set traces the Old English verb and its English family.","cn":"lead 是日耳曼语动词而非拉丁语动词，因此词缀部分追溯古英语动词及其英语同族词。"},"latinIntro":{"en":"There is no Latin etymon here; the root is the Old English verb lædan and its Germanic causative.","cn":"此处没有拉丁语词源；词根是古英语动词 lædan 及其日耳曼语使动形式。"},"items":[{"word":"lædan","structure":"Old English verb","meaning":"to cause to go; guide","meaningCN":"使行进；引导","example":"The Old English verb already implied an agent.","exampleCN":"古英语动词已隐含施事者。"},{"word":"laidijan","structure":"Germanic causative, reconstructed","meaning":"to make travel","meaningCN":"使行进","example":"The reconstructed form explains the modern vowel.","exampleCN":"重构形式解释了现代元音。"},{"word":"lead","structure":"English verb and noun","meaning":"to guide; the front position","meaningCN":"引导；领先位置","example":"The verb keeps both the guiding and the leading senses.","exampleCN":"动词兼有「引导」与「领先」两义。"},{"word":"leader","structure":"lead + -er","meaning":"one who guides","meaningCN":"领导者","example":"The agent noun is regular and old.","exampleCN":"施事名词规则且古老。"},{"word":"leading","structure":"lead + -ing","meaning":"guiding; in front","meaningCN":"引导的；领先的","example":"The participle works as adjective and noun.","exampleCN":"分词兼作形容词与名词。"},{"word":"mislead","structure":"mis- + lead","meaning":"to guide wrongly","meaningCN":"误导","example":"The negative prefix reverses the direction of guidance.","exampleCN":"否定前缀反转引导方向。"},{"word":"lead-up","structure":"lead + up, compound noun","meaning":"the preparatory period","meaningCN":"前奏；准备阶段","example":"The compound names the steps before an event.","exampleCN":"复合名词指事件之前的步骤。"},{"word":"lead to","structure":"verb + preposition, fixed phrase","meaning":"to end in; guide towards","meaningCN":"导致；通向","example":"The frame fixes the endpoint as the object of to.","exampleCN":"框架把终点固定为介词宾语。"}],"latinEntries":[],"derivatives":[{"word":"lead","pos":"v./n.","zh":"带领；引导；领先"},{"word":"leader","pos":"n.","zh":"领导者"},{"word":"leading","pos":"adj./n.","zh":"领先的；引导"},{"word":"mislead","pos":"v.","zh":"误导"},{"word":"lead-up","pos":"n.","zh":"前奏；准备阶段"}]}},{"word":"make up","ipa_uk":"/meɪk ʌp/","ipa_us":"/meɪk ʌp/","definition_zh":"构成；占（比例）；编造；化妆；和解；补足；凑齐；补做；铺床；排版","definition_en":"to form a whole, to invent something untrue, to put on cosmetics, to become friendly again, or to supply what is missing","core_image":"一桌散落的零件被逐件拼回，最后拼成一台完整的机器","scene":"桌上散着一堆零件，工人一件件拾起拼装，最后拼成一台整机。Ten parts make up the whole device.","sceneCN":"这里指零件合起来构成整台装置（第 1 个义项：构成整体）；句意为十个零件构成了整台装置。图中可辨识物件：零件、桌面、装好的机器。","pos":[{"tag":"v. phr.","zh":"动词短语：构成；编造；化妆；和解"},{"tag":"idiom","zh":"固定搭配：补足；凑齐"}],"collocations":[{"phrase":"make up the majority","zh":"占多数"},{"phrase":"make up a story","zh":"编造故事"},{"phrase":"make up an excuse","zh":"编个借口"},{"phrase":"make up a team","zh":"凑成一支队伍"},{"phrase":"make up the difference","zh":"补足差额"},{"phrase":"make up with someone","zh":"与某人和解"},{"phrase":"make up a page","zh":"拼排一个版面"}],"forms":[{"label":"原形","form":"make up"},{"label":"第三人称单数","form":"makes up"},{"label":"过去式","form":"made up"},{"label":"过去分词","form":"made up"},{"label":"现在分词","form":"making up"},{"label":"名词","form":"makeup"}],"derivatives":[{"word":"make","pos":"v.","zh":"由古英语「塑造、建造」动词而来，义为「做；使成为」"},{"word":"makeup","pos":"n.","zh":"由该短语连写而成的名词，义为「化妆品；构成」"},{"word":"maker","pos":"n.","zh":"由该动词加表示施事者的名词尾构成，义为「制造者」"},{"word":"remake","pos":"v./n.","zh":"由「再」前缀加该动词构成，义为「重做；翻拍」"},{"word":"making","pos":"n.","zh":"由该动词加名词尾构成，义为「制作；形成过程」"}],"senses":[{"no":"01","title":"To form a whole","titleCN":"构成整体","definition":"to combine into a complete whole","definitionCN":"合起来成为一个完整的整体","example":"Ten parts make up the whole device.","exampleCN":"十个零件构成了整台装置。","why":"This is the oldest figurative sense: the parts, taken together, are the whole.","whyCN":"这是最古老的引申义：各部分合起来就是整体。"},{"no":"02","title":"To account for a share","titleCN":"占一定比例","definition":"to form a specified part of a total, often with a fraction or percentage","definitionCN":"构成总量中的某一份额，常与分数或百分比连用","example":"Women make up half of the workforce in this sector.","exampleCN":"在这一行业，女性占劳动力的一半。","why":"A share is a whole seen from inside, so the same verb serves counting and proportion.","whyCN":"份额是从内部看的整体，因此同一动词兼管计数与比例。"},{"no":"03","title":"To invent something false","titleCN":"编造（故事、借口）","definition":"to create an untrue story or excuse","definitionCN":"捏造不真实的故事或借口","example":"Children often make up a story when they are late.","exampleCN":"孩子迟到时常常编一个故事。","why":"The invented thing is made as if assembled, which is how the verb slides from building to fabricating.","whyCN":"编造之物仿佛被拼装出来，动词便从「建造」滑向「捏造」。"},{"no":"04","title":"To apply cosmetics","titleCN":"化妆","definition":"to put on cosmetics or to prepare an actor's face","definitionCN":"涂抹化妆品，或为演员上妆","example":"The actors make up before every evening show.","exampleCN":"演员每场晚场演出前都要化妆。","why":"Here the object is a face, and the verb means to build a surface appearance.","whyCN":"这里对象是脸，动词意为「造出一层表面」。"},{"no":"05","title":"To become friendly again","titleCN":"和解","definition":"to end a quarrel and become friends again","definitionCN":"结束争吵并重新和好","example":"The two neighbours make up after every quarrel.","exampleCN":"这两位邻居每次争吵后都会和好。","why":"The image is repairing a broken whole, which links this sense to the first one.","whyCN":"意象是修补破碎的整体，与第一个义项相连。"},{"no":"06","title":"To supply what is missing","titleCN":"补足差额","definition":"to add what is needed to reach a required amount","definitionCN":"添上所缺部分以达到所需数量","example":"A second grant will make up the shortfall.","exampleCN":"第二笔拨款将补足缺口。","why":"The missing amount is treated as a gap to be filled, so the verb keeps its building image.","whyCN":"缺少的数额被当作待填的缺口，动词保留其建造意象。"},{"no":"07","title":"To assemble a group","titleCN":"凑成一支队伍","definition":"to gather enough people or things to form a group","definitionCN":"凑够人或物以组成一个团体","example":"We can make up a team from the volunteers.","exampleCN":"我们可以从志愿者中凑出一支队伍。","why":"This sense is close to the whole-forming one, but the emphasis is on gathering rather than resulting.","whyCN":"这一义项接近「构成整体」，但重点在收集而非结果。"},{"no":"08","title":"To do missed work","titleCN":"补做（考试、功课）","definition":"to complete work or a test that was missed","definitionCN":"完成错过的功课或考试","example":"Students can make up the missed test on Friday.","exampleCN":"学生可以在星期五补做错过的考试。","why":"The missed task is the gap, and the verb fills it, as in the compensation sense.","whyCN":"错过的任务就是缺口，动词把它填上，与补偿义同理。"},{"no":"09","title":"To prepare a bed","titleCN":"铺床","definition":"to arrange a bed for use, especially in a hotel","definitionCN":"把床铺整理好以供使用，尤指旅馆","example":"The staff make up the beds each morning.","exampleCN":"工作人员每天早上整理床铺。","why":"Making a bed is literally assembling layers, which is why this sense survives in housekeeping.","whyCN":"铺床字面上就是逐层拼装，因此这一义项保留在客房服务里。"},{"no":"10","title":"To lay out a printed page","titleCN":"拼版排版","definition":"in printing, to arrange text and images into a page","definitionCN":"印刷中将文字与图像拼排成一页","example":"The editor will make up the front page tonight.","exampleCN":"编辑今晚会拼排头版。","why":"The trade sense treats a page as a whole assembled from blocks, the same pattern as the first sense.","whyCN":"行业义把一页看作由版块拼成的整体，与第一个义项同一模式。"}],"etymology":{"intro":{"en":"Make is an Old English verb, macian, to form or construct, from a Germanic root reconstructed as makōjan. Up is the Old English adverb upp. The two-word verb is English, and its many senses grew in the modern period; first dates are approximate.","cn":"make 是古英语动词 macian，意为「塑造、建造」，出自日耳曼语重构词根；up 是古英语副词 upp。两词组合的动词属英语，众多义项在近代发展出来，首见年代为约数。"},"items":[{"era":"OLD ENGLISH MACIAN","en":"Macian meant to form, build or construct, and it was already used for both objects and arrangements.","cn":"macian 意为「塑造、建造」，当时已用于实物与安排。"},{"era":"GERMANIC ROOT","en":"The reconstructed root makōjan underlies Dutch maken and German machen.","cn":"重构词根也是荷兰语与德语同义词的来源。"},{"era":"OLD ENGLISH UPP","en":"Upp is the adverb meaning upward, preserves the picture of completing an action.","cn":"upp 是表示「向上」的副词，保留「把动作做完」的画面。"},{"era":"PHRASAL VERB","en":"The combination make up appears in the early modern period with the sense of completing or assembling.","cn":"组合形式在近代早期出现，带「完成、拼合」之义。"},{"era":"MODERN SENSES","en":"Cosmetics, reconciliation, compensation and printing senses all develop later; exact dates are approximate.","cn":"化妆、和解、补偿与排版诸义都更晚出现，确切年代为约数。"}]},"similar":{"note":{"en":"The first group shares the verb or the spelling and changes the particle; the second group holds verbs that cover one of the many senses.","cn":"第一组共用该动词或同一拼写而更换小品词；第二组是分别覆盖某一义项的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"make up for","ipa":"/meɪk ʌp fɔː/","tag":"compensate","definition":"The extra for marks compensation for a loss, while bare make up only fills a gap.","definitionCN":"多出的介词标出对损失的补偿，单独的短语只表示填补缺口。"},{"word":"make out","ipa":"/meɪk aʊt/","tag":"perceive or understand","definition":"It means to see, hear or understand with difficulty, or to write a cheque.","definitionCN":"意为费力地看清、听清或理解，也指开票据。"},{"word":"make off","ipa":"/meɪk ɒf/","tag":"leave quickly","definition":"It means to hurry away, often after taking something.","definitionCN":"意为匆匆离开，常指拿了东西就走。"},{"word":"makeup","ipa":"/ˈmeɪkʌp/","tag":"one-word noun","definition":"The single word is a noun for cosmetics or composition, never a verb.","definitionCN":"连写的单词是名词，指化妆品或构成，不能作动词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"constitute","ipa":"/kənˈstɪtjuːt/","tag":"formal whole-forming","definition":"It states that parts form a whole, chiefly in formal or legal prose.","definitionCN":"它说明部分构成整体，多见于正式或法律文字。"},{"word":"comprise","ipa":"/kəmˈpraɪz/","tag":"whole and parts","definition":"It names the whole and its parts, with the whole as subject.","definitionCN":"它点出整体与部分，主语是整体。"},{"word":"invent","ipa":"/ɪnˈvent/","tag":"fabrication","definition":"It covers the false-story sense and also genuine creation.","definitionCN":"它覆盖编造故事一义，也指真正的发明。"},{"word":"reconcile","ipa":"/rɪˈkɒnsaɪl/","tag":"formal reconciliation","definition":"It is the formal verb for ending a quarrel, where make up is conversational.","definitionCN":"它是结束争吵的正式说法，而本短语偏口语。"}]}]},"mnemonics":{"normalIntro":{"en":"The normal associations use the real Old English pair, the particle contrast and the four core layers.","cn":"正常联想使用真实的古英语两词、小品词对比与四层核心义。"},"normal":[{"en":"Macian is to build, so the first sense is parts forming a whole.","cn":"古英语动词意为「建造」，所以第一义是部分构成整体。"},{"en":"Up completes the action, which is why the phrase also means filling a gap.","cn":"up 表示做完，因此短语也有「填上缺口」之义。"},{"en":"The same verb covers counting a share and inventing a story.","cn":"同一动词既管计数份额，也管编造故事。"},{"en":"Cosmetics, reconciliation and printing are later layers on the same image.","cn":"化妆、和解与排版都是同一意象上较晚的层次。"},{"en":"The single-word noun is written solid, the verb stays two words.","cn":"连写的是名词，动词保持两词。"}],"abstract":[{"en":"Like scattered parts gathered on one table until a machine stands complete.","cn":"像散落零件在桌上被逐件拾起，直到整机立起来。"},{"en":"Like a torn page mended with tape, the break closed and the whole readable again.","cn":"像撕破的书页用胶带补好，裂口合上，整页又能读。"},{"en":"Like a face painted for the stage, a surface built layer by layer.","cn":"像为登台而化的妆，一层层造出表面。"}]},"examples":[{"en":"Five departments make up the research division.","cn":"五个部门构成了这个研究分部。"},{"en":"Imports make up a third of the country's food supply.","cn":"进口占该国食品供应的三分之一。"},{"en":"The two brothers make up soon after every argument.","cn":"两兄弟每次争吵后很快就会和好。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「梅克 阿普」——桌上散落的零件一件件拼起来，最后成一台整机：构成；拼合","word":"make up"},"root":"make 是古英语动词 macian「塑造、建造」，出自日耳曼语重构词根；up 是古英语副词 upp。组合形式属英语，众多义项在近代发展出来，首见年代为约数。","sensesIntro":{"en":"Ten senses split the phrase into four core layers and six extensions: forming a whole, counting a share, inventing, cosmetics, reconciliation, compensation, assembling a group, doing missed work, making a bed and laying out a page.","cn":"十个义项把短语分成四层核心义与六项延伸：构成整体、占份额、编造、化妆、和解、补偿、凑队、补做、铺床、拼版。"},"semanticMap":{"core":{"en":"CORE IMAGE: scattered parts gathered on a table until a complete machine stands.","cn":"核心意象：散落零件在桌上被拼成一台完整机器。"},"chain":["BUILD A WHOLE","COUNT THE SHARE","INVENT A STORY","PAINT THE FACE","MEND A QUARREL","FILL THE GAP"],"branches":[{"senses":"01 · 07 · 10","en":"THE WHOLE: parts, people or type blocks are assembled into one complete thing.","cn":"整体：零件、人或版块被拼成一个完整之物。"},{"senses":"02","en":"THE SHARE: the whole is viewed from inside as a fraction or percentage.","cn":"份额：从内部把整体看作分数或百分比。"},{"senses":"03","en":"THE FABRICATION: an untrue story is assembled as if it were real.","cn":"捏造：不实故事被拼装得像真的。"},{"senses":"04","en":"THE SURFACE: a face is built up layer by layer for the stage.","cn":"表面：为登台把脸一层层造出来。"},{"senses":"05 · 06 · 08 · 09","en":"THE REPAIR: quarrels, shortfalls, missed work and beds are all gaps to close.","cn":"修补：争执、缺口、错过的功课与床铺都是待合的缺口。"}]},"affixes":{"intro":{"en":"The phrase is native English, so the affix set traces the Old English verb and adverb rather than Latin elements.","cn":"这个短语是英语本族组合，因此词缀部分追溯古英语动词与副词，而非拉丁语成分。"},"latinIntro":{"en":"There is no Latin etymon here; the root is the Old English verb macian and the adverb upp.","cn":"此处没有拉丁语词源；词根是古英语动词 macian 与副词 upp。"},"items":[{"word":"macian","structure":"Old English verb","meaning":"to form; construct","meaningCN":"塑造；建造","example":"The verb applied to both objects and arrangements.","exampleCN":"这个动词既用于实物，也用于安排。"},{"word":"makōjan","structure":"Germanic root, reconstructed","meaning":"to make","meaningCN":"做；造","example":"The reconstructed root is shared by Dutch and German.","exampleCN":"重构词根为荷兰语与德语共有。"},{"word":"make","structure":"English verb","meaning":"to produce; cause to be","meaningCN":"做；使成为","example":"The verb is one of the most productive in English.","exampleCN":"这个动词是英语里最能产的之一。"},{"word":"up","structure":"Old English adverb","meaning":"upward; completely","meaningCN":"向上；完全","example":"The adverb adds completion to the verb.","exampleCN":"副词为动词加上「完成」义。"},{"word":"makeup","structure":"make + up, compound noun","meaning":"cosmetics; composition","meaningCN":"化妆品；构成","example":"The solid spelling marks the noun.","exampleCN":"连写标示名词。"},{"word":"maker","structure":"make + -er","meaning":"one who makes","meaningCN":"制造者","example":"The agent noun is regular.","exampleCN":"施事名词规则。"},{"word":"remake","structure":"re- + make","meaning":"to make again","meaningCN":"重做；翻拍","example":"The prefix repeats the action.","exampleCN":"前缀表示重复动作。"},{"word":"make up","structure":"verb + adverb, fixed phrase","meaning":"to form; invent; reconcile","meaningCN":"构成；编造；和解","example":"The phrase has grown a wide range of senses.","exampleCN":"这个短语长出了一大片义项。"}],"latinEntries":[],"derivatives":[{"word":"make","pos":"v.","zh":"做；使成为"},{"word":"makeup","pos":"n.","zh":"化妆品；构成"},{"word":"maker","pos":"n.","zh":"制造者"},{"word":"remake","pos":"v./n.","zh":"重做；翻拍"},{"word":"making","pos":"n.","zh":"制作；形成过程"}]}},{"word":"play a role in","ipa_uk":"/pleɪ ə ˈrəʊl ɪn/","ipa_us":"/pleɪ ə ˈroʊl ɪn/","definition_zh":"在……中起作用；在……中扮演角色、承担职责或参与其中","definition_en":"to have a share in bringing something about, or to act a part in a play, film or process","core_image":"舞台侧幕旁，一名演员正走向台口，灯光落在他身上","scene":"剧场侧幕旁，一名演员整了整衣角，向台口走去。Two young actors play a role in the opening scene.","sceneCN":"这里指演员在开场戏里扮演角色（第 2 个义项：在戏剧中扮演角色）；句意为两名年轻演员在开场一幕中出演。图中可辨识物件：侧幕、演员、追光、舞台。","pos":[{"tag":"v. phr.","zh":"动词短语：起作用；扮演角色"},{"tag":"idiom","zh":"固定搭配：参与其中"}],"collocations":[{"phrase":"play a key role in","zh":"在……中起关键作用"},{"phrase":"play a major role in","zh":"在……中起主要作用"},{"phrase":"play a minor role in","zh":"在……中起次要作用"},{"phrase":"play a role in shaping","zh":"在塑造……中起作用"},{"phrase":"play a role in decision-making","zh":"在决策中发挥作用"},{"phrase":"play a role in the process","zh":"在过程中发挥作用"}],"forms":[{"label":"原形","form":"play a role in"},{"label":"第三人称单数","form":"plays a role in"},{"label":"过去式","form":"played a role in"},{"label":"现在分词","form":"playing a role in"},{"label":"限定变体","form":"play a key role in"}],"derivatives":[{"word":"play","pos":"v./n.","zh":"由古英语「活动、嬉戏」动词而来，义为「扮演；玩耍」"},{"word":"role","pos":"n.","zh":"由古法语「卷轴」一词而来，义为「角色；作用」"},{"word":"player","pos":"n.","zh":"由该动词加表示施事者的名词尾构成，义为「演员；参与者」"},{"word":"playwright","pos":"n.","zh":"由该动词加表示制作者的名词构成，义为「剧作家」"},{"word":"playhouse","pos":"n.","zh":"由该动词加「房屋」构成的复合名词，义为「剧院」"}],"senses":[{"no":"01","title":"To have a share in an outcome","titleCN":"在结果中起作用","definition":"to contribute to a result without being its only cause","definitionCN":"对某一结果有所贡献，但不是唯一原因","example":"Small firms play a role in keeping local skills alive.","exampleCN":"小企业在维系本地技艺方面起着作用。","why":"The phrase pictures a cast: each contributor has a part, and no single part owns the result.","whyCN":"这个短语画出演员表：每个贡献者都有一份，没有哪一份独占结果。"},{"no":"02","title":"To act a part on stage","titleCN":"在戏剧中扮演角色","definition":"to perform a character in a play, film or opera","definitionCN":"在戏剧、电影或歌剧里出演一个人物","example":"Two young actors play a role in the opening scene.","exampleCN":"两名年轻演员在开场一幕中出演。","why":"This is the literal theatrical sense from which the figurative ones borrow their image.","whyCN":"这是字面的戏剧义，其他引申义都借用它的意象。"},{"no":"03","title":"To take part in an activity","titleCN":"参与某项活动","definition":"to be one of the people involved in an activity","definitionCN":"作为参与者之一加入某项活动","example":"Local volunteers play a role in the annual clean-up.","exampleCN":"本地志愿者在年度清理活动中出力。","why":"Involvement is looser than causation: the part may be small and still count as a role.","whyCN":"参与比因果更宽松：戏份可以很小，仍算一个角色。"},{"no":"04","title":"A decisive part","titleCN":"起关键作用","definition":"to be a decisive factor, usually with key or major as modifier","definitionCN":"成为决定性因素，常与「关键」「主要」等修饰语连用","example":"Several factors play a role in crop yield, and moisture is the decisive one.","exampleCN":"若干因素对作物产量起作用，其中湿度是决定性的。","why":"The modifier upgrades the part from one voice in the cast to the leading one.","whyCN":"修饰语把戏份从众多声音之一提升为主角。"},{"no":"05","title":"A limited part","titleCN":"起次要作用","definition":"to be only one of several factors, often with minor","definitionCN":"只是若干因素之一，常与「次要」连用","example":"Advertising plays only a small part, yet many factors play a role in the success of this product.","exampleCN":"广告只占很小一部分，但这一产品的成功有众多因素起作用。","why":"Downgrading the role protects the writer from overstating a cause.","whyCN":"降低戏份能让写作者避免夸大某一原因。"},{"no":"06","title":"A factor in a process","titleCN":"在过程中充当因素","definition":"used in research writing to name one factor among several","definitionCN":"在研究写作中点出若干因素中的一个","example":"Ocean currents play a role in the distribution of larvae.","exampleCN":"洋流在幼体分布中起作用。","why":"Research prose needs a way to name a factor without claiming sole causation, and this frame supplies it.","whyCN":"研究写作需要一种只点出因素而不宣称唯一因果的说法，这一框架正好提供。"},{"no":"07","title":"A function in a system","titleCN":"在系统中发挥功能","definition":"to serve a function within a machine, body or institution","definitionCN":"在机器、身体或机构内部承担一项功能","example":"Microbes play a role in the digestion of plant fibre.","exampleCN":"微生物在植物纤维的消化中发挥作用。","why":"Here the part is structural: remove it and the system performs worse.","whyCN":"这里的戏份是结构性的：去掉它，系统就运转得更差。"},{"no":"08","title":"To act as a party or representative","titleCN":"充当某一方或代表","definition":"to serve as one of the parties in a negotiation or arrangement","definitionCN":"在谈判或安排中作为一方出现","example":"Trade unions play a role in the talks between staff and management.","exampleCN":"工会在员工与管理层的谈判中充当一方。","why":"The phrase can name an institutional actor, not only a cause, which is why it fits politics and law.","whyCN":"这个短语可以指机构行动者，而不只是原因，因此适用于政治与法律。"}],"etymology":{"intro":{"en":"Play comes from Old English plegian, to exercise or take part in lively activity; its deeper origin is uncertain, though a Germanic source is generally assumed. Role comes through Old French from Latin rotulus, a little roll of paper, from rota, wheel. Fixed use as a phrase is modern and its first date is approximate.","cn":"play 源自中古英语之前的 plegian，意为「活动、参与热闹之事」，更深来源不确定，一般认为出自日耳曼语。role 经古法语来自拉丁语 rotulus「小纸卷」，后者出自 rota「轮」。短语为近代用法，首见年代为约数。"},"items":[{"era":"OLD ENGLISH PLEGIAN","en":"Plegian meant to exercise, frolic or engage in lively activity.","cn":"plegian 意为「活动、嬉闹、参与热闹之事」。"},{"era":"UNCERTAIN DEEPER SOURCE","en":"The deeper origin of the verb is uncertain; a Germanic source is generally assumed but not proved.","cn":"这个动词更深的来源不确定，一般认为出自日耳曼语，但未获确证。"},{"era":"LATIN ROTA","en":"Rota means wheel and also underlies rotate and rotary.","cn":"rota 意为「轮」，也是 rotate 与 rotary 的根基。"},{"era":"LATIN ROTULUS","en":"Rotulus, a little roll, named the scroll on which an actor's part was written.","cn":"rotulus 意为「小卷」，指写有演员台词的小纸卷。"},{"era":"OLD FRENCH ROLLE","en":"Old French rolle carried the word into English as the part an actor takes.","cn":"古法语 rolle 把该词带入英语，指演员承担的角色。"},{"era":"ENGLISH PHRASE","en":"The frame extends the stage image to causes and institutions; first dates are approximate.","cn":"这一框架把舞台意象扩展到原因与机构，首见年代为约数。"}]},"similar":{"note":{"en":"The first group shares the noun role or the verb play and changes the particle; the second group holds verbs of contribution.","cn":"第一组共用名词或动词而更换介词；第二组是表示贡献的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"play a part in","ipa":"/pleɪ ə pɑːt ɪn/","tag":"same image, plainer noun","definition":"Part is the everyday twin of role and is more common in speech.","definitionCN":"part 是 role 的日常双胞胎，口语中更常见。"},{"word":"play the role of","ipa":"/pleɪ ðə rəʊl ɒv/","tag":"a named character","definition":"Of introduces the character or function itself, not the setting.","definitionCN":"介词引出人物或职能本身，而非场合。"},{"word":"take a role in","ipa":"/teɪk ə rəʊl ɪn/","tag":"assume a part","definition":"It stresses accepting a part rather than performing it.","definitionCN":"它强调承担角色，而非出演角色。"},{"word":"play a role in","ipa":"/pleɪ ə rəʊl ɪn/","tag":"the phrase itself","definition":"Note that in introduces the field or process, never the character.","definitionCN":"注意后面的介词引出领域或过程，从不引出人物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"contribute to","ipa":"/kənˈtrɪbjuːt tuː/","tag":"add to a result","definition":"It states plainly that something adds to an outcome.","definitionCN":"它直白地说明某物对结果有所添加。"},{"word":"be involved in","ipa":"/biː ɪnˈvɒlvd ɪn/","tag":"participation","definition":"It marks participation without any claim about importance.","definitionCN":"它标记参与，不对重要性作任何断言。"},{"word":"participate in","ipa":"/ˌpɑːtɪsɪˈpeɪt ɪn/","tag":"take part","definition":"It is the neutral verb for joining an activity.","definitionCN":"它是加入活动的中性动词。"},{"word":"figure in","ipa":"/ˈfɪɡə ɪn/","tag":"appear as a factor","definition":"It means to appear as an element in a situation or calculation.","definitionCN":"意为作为要素出现在某种情形或计算中。"}]}]},"mnemonics":{"normalIntro":{"en":"The normal associations use the real stage image, the real noun history and the modifier scale.","cn":"正常联想使用真实的舞台意象、真实的名词历史与修饰语梯度。"},"normal":[{"en":"A role was once a paper roll holding an actor's lines.","cn":"role 原指写有演员台词的小纸卷。"},{"en":"The stage image explains why the phrase suits causes: each factor has a part.","cn":"舞台意象解释了它为何适合原因：每个因素都有一份戏。"},{"en":"Key and major raise the part; minor lowers it.","cn":"「关键」「主要」抬高戏份，「次要」压低戏份。"},{"en":"The final preposition names the field, not the character.","cn":"最后的介词引出领域，而非人物。"},{"en":"Part is the everyday substitute and means the same.","cn":"日常可用「part」替换，意义相同。"}],"abstract":[{"en":"Like a small part in a long play: a few lines change how the audience reads the whole.","cn":"像长剧里的一个小角色：几句台词就改变观众对全剧的理解。"},{"en":"Like one musician in an orchestra, audible only when the section plays together.","cn":"像乐团里的一名乐手，只有声部合奏时才听得出来。"},{"en":"Like a hinge on a gate: unnoticed until it stops working.","cn":"像门上的铰链：不出问题就没人注意。"}]},"examples":[{"en":"Diet and exercise both play a role in heart health.","cn":"饮食与运动对心脏健康都起作用。"},{"en":"Several factors play a role in the formation of these dunes.","cn":"若干因素在这些沙丘的形成中起作用。"},{"en":"Local guides play a role in the visitor programme.","cn":"本地向导在游客项目中承担角色。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「普雷 阿 柔 因」——侧幕旁演员整了整衣角，向台口走去：扮演角色；起作用","word":"play a role in"},"root":"play 源自中古英语之前的 plegian「活动、嬉闹」，更深来源不确定，一般认为出自日耳曼语；role 经古法语来自拉丁语 rotulus「小纸卷」，出自 rota「轮」。该短语为近代用法，首见年代为约数。","sensesIntro":{"en":"Eight senses split the phrase by the kind of part: a share in a result, a stage character, an activity, a decisive factor, a limited factor, a research variable, a system function and an institutional party.","cn":"八个义项按角色类别区分：结果中的一份、舞台人物、活动参与、决定因素、次要因素、研究变量、系统功能、机构一方。"},"semanticMap":{"core":{"en":"CORE IMAGE: an actor at the side curtain stepping into the light towards the stage front.","cn":"核心意象：侧幕旁的演员走向台口，灯光落在他身上。"},"chain":["TAKE A PART","ENTER THE SCENE","SHARE THE OUTCOME","RAISE OR LOWER THE PART","SERVE A FUNCTION","ACT AS A PARTY"],"branches":[{"senses":"02 · 03","en":"THE STAGE: a character is performed, or a volunteer simply joins in.","cn":"舞台：或出演人物，或只是参与其中。"},{"senses":"01 · 06","en":"THE FACTOR: one contributor among several, named without claiming sole cause.","cn":"因素：若干贡献者之一，只点名不独占因果。"},{"senses":"04 · 05","en":"THE SCALE: key and major raise the part, minor lowers it.","cn":"梯度：关键与主要抬高戏份，次要将其压低。"},{"senses":"07","en":"THE MECHANISM: a part inside a system whose removal weakens it.","cn":"机制：系统内部的角色，去掉就变弱。"},{"senses":"08","en":"THE PARTY: unions, states or agencies act as one side in a proceeding.","cn":"一方：工会、国家或机构作为程序中的一方。"}]},"affixes":{"intro":{"en":"The phrase combines an Old English verb of uncertain deeper origin with a noun from a Latin word for a paper roll.","cn":"短语把一个更深来源存疑的古英语动词，与一个出自拉丁语「纸卷」的名词组合起来。"},"latinIntro":{"en":"The Latin etymon is rotulus, a little roll, from rota, wheel; play has no Latin source.","cn":"拉丁语词源是 rotulus「小卷」，出自 rota「轮」；play 没有拉丁语来源。"},"items":[{"word":"plegian","structure":"Old English verb","meaning":"to exercise; frolic","meaningCN":"活动；嬉闹","example":"The verb named lively activity before it named acting.","exampleCN":"这个动词先指热闹活动，后指表演。"},{"word":"play","structure":"English verb and noun","meaning":"to perform; a drama","meaningCN":"扮演；戏剧","example":"The verb widened from play to acting.","exampleCN":"动词从「玩耍」扩大到「表演」。"},{"word":"rota","structure":"Latin noun, first declension","meaning":"wheel","meaningCN":"轮","example":"The word also gives rotate and rotary.","exampleCN":"这个词也给出「旋转」一系词。"},{"word":"rotulus","structure":"Latin noun, diminutive of rota","meaning":"a little roll","meaningCN":"小卷","example":"A scroll held the words of one part.","exampleCN":"一卷纸写着某角色的台词。"},{"word":"rolle","structure":"Old French noun","meaning":"roll; the part taken","meaningCN":"卷；所担角色","example":"French narrowed the scroll to the actor's part.","exampleCN":"法语把「纸卷」这一意义收窄为演员所担的角色。"},{"word":"role","structure":"English noun","meaning":"a part; a function","meaningCN":"角色；作用","example":"The noun now covers stage, work and causal senses.","exampleCN":"名词现覆盖舞台、职务与因果三义。"},{"word":"player","structure":"play + -er","meaning":"one who plays","meaningCN":"演员；参与者","example":"The agent noun covers both games and drama.","exampleCN":"施事名词兼指游戏与戏剧。"},{"word":"play a role in","structure":"verb + article + noun + preposition, fixed phrase","meaning":"to take part in","meaningCN":"在……中起作用","example":"The frame fixes the field after the final preposition.","exampleCN":"框架把领域固定在最后介词之后。"}],"latinEntries":[{"word":"rota","structure":"rota, -ae (noun, first declension)","meaning":"wheel","meaningCN":"轮"},{"word":"rotulus","structure":"rotulus, -i (noun, diminutive)","meaning":"a little roll; scroll","meaningCN":"小卷；卷轴"}],"derivatives":[{"word":"play","pos":"v./n.","zh":"扮演；玩耍；戏剧"},{"word":"role","pos":"n.","zh":"角色；作用"},{"word":"player","pos":"n.","zh":"演员；参与者"},{"word":"playwright","pos":"n.","zh":"剧作家"},{"word":"playhouse","pos":"n.","zh":"剧院"}]}},{"word":"result in","ipa_uk":"/rɪˈzʌlt ɪn/","ipa_us":"/rɪˈzʌlt ɪn/","definition_zh":"导致；造成；以……为结果（先说原因，再说后果）","definition_en":"to cause a particular outcome, with the cause as subject and the outcome after the preposition","core_image":"第一张多米诺骨牌被推倒，后面的牌依次倒下，最后一张压住了终点线","scene":"长桌上排好一串骨牌，第一张被轻轻一推，后面的牌依次倒下。One careless push can result in the fall of the whole row.","sceneCN":"这里指一次推动导致整排骨牌倒下（第 1 个义项：导致某一结果）；句意为一次不小心的推动就能导致整排倒下。图中可辨识物件：骨牌、长桌、终点线。","pos":[{"tag":"v. phr.","zh":"动词短语：导致；造成"},{"tag":"idiom","zh":"固定搭配：结果为导向的因果表达"}],"collocations":[{"phrase":"result in a decline","zh":"导致下降"},{"phrase":"result in an increase","zh":"导致上升"},{"phrase":"result in damage","zh":"造成损害"},{"phrase":"result in failure","zh":"导致失败"},{"phrase":"result in higher costs","zh":"导致成本上升"},{"phrase":"result in a change","zh":"导致变化"}],"forms":[{"label":"原形","form":"result in"},{"label":"第三人称单数","form":"results in"},{"label":"过去式","form":"resulted in"},{"label":"过去分词","form":"resulted in"},{"label":"现在分词","form":"resulting in"}],"derivatives":[{"word":"result","pos":"n./v.","zh":"由拉丁语「弹回」动词经法语而来，义为「结果；导致」"},{"word":"resultant","pos":"adj./n.","zh":"由该动词加形容词尾构成，义为「由此产生的；合力」"},{"word":"resulting","pos":"adj.","zh":"由该动词加分词尾构成，义为「由此产生的」"},{"word":"result from","pos":"v. phr.","zh":"同根的反向框架，义为「由……造成」"},{"word":"result-oriented","pos":"adj.","zh":"由名词加形容词构成的复合词，义为「结果导向的」"}],"senses":[{"no":"01","title":"Cause to outcome","titleCN":"前因导致后果","definition":"used when the subject is the cause and the object is the outcome","definitionCN":"主语是原因，介词后是后果","example":"A single missed inspection can result in a recall of the batch.","exampleCN":"漏检一次就可能导致整批产品被召回。","why":"The preposition points forward along the arrow, so the sentence runs from cause to effect.","whyCN":"介词沿箭头向前指，句子便从原因走向结果。"},{"no":"02","title":"Damage or accident","titleCN":"造成损害或事故","definition":"used when the outcome is harm, loss or an accident","definitionCN":"后果是伤害、损失或事故时使用","example":"Poor wiring can result in a fire.","exampleCN":"布线不当可能造成火灾。","why":"With harmful outcomes the phrase often stands beside a warning or a safety rule.","whyCN":"后果有害时，这个短语常与警告或安全规则并置。"},{"no":"03","title":"Experimental reading","titleCN":"实验得出的结果","definition":"used in reports to state what a treatment or condition produced","definitionCN":"在报告中说明某种处理或条件产生了什么","example":"The higher dose can result in a faster response.","exampleCN":"较高剂量可带来更快的反应。","why":"Research prose uses the frame to keep the manipulated variable in subject position.","whyCN":"研究写作借此把被操纵的变量留在主语位置。"},{"no":"04","title":"A gain or improvement","titleCN":"带来收益或改进","definition":"used when the outcome is a benefit or an advance","definitionCN":"后果是益处或进步时使用","example":"Better training can result in fewer accidents.","exampleCN":"更好的培训可以减少事故。","why":"The frame is neutral about value, so gains and losses both fit the same slot.","whyCN":"这一框架对价值中性，收益与损失都进同一个位置。"},{"no":"05","title":"A medical outcome","titleCN":"引起疾病或症状","definition":"used when a condition produces a symptom or illness","definitionCN":"某种状况引发症状或疾病时使用","example":"Long exposure can result in hearing loss.","exampleCN":"长期暴露可能导致听力损失。","why":"In medicine the outcome is often a state that develops slowly and cannot be undone.","whyCN":"在医学里结果常是缓慢形成且不可逆的状态。"},{"no":"06","title":"Ending in a consequence","titleCN":"以某种后果告终","definition":"used when an action ends in a penalty, dismissal or ruling","definitionCN":"某行为以处罚、解职或裁决告终时使用","example":"Repeated breaches can result in dismissal.","exampleCN":"屡次违规可能导致解雇。","why":"Here the outcome is a formal consequence imposed by an authority.","whyCN":"这里的结果是由权威施加的正式后果。"},{"no":"07","title":"Academic causal chain","titleCN":"学术因果链","definition":"used to link a variable to a measured outcome in research writing","definitionCN":"在研究写作中把一个变量与测量结果连起来","example":"Warmer water can result in the migration of the species.","exampleCN":"水温升高可能导致该物种迁移。","why":"The mirror phrase result from reverses the arrow, and the pair marks the direction of causation.","whyCN":"反向框架把箭头倒过来，两者共同标出因果方向。"},{"no":"08","title":"Policy consequences","titleCN":"政策导致的长期后果","definition":"used when a decision produces effects that appear over time","definitionCN":"某项决定产生随时间显现的影响时使用","example":"Short-term subsidies can result in long-term dependence.","exampleCN":"短期补贴可能导致长期依赖。","why":"Policy writing uses the frame to trace delayed effects that were not obvious at the start.","whyCN":"政策写作借此追踪起初并不明显的延迟后果。"}],"etymology":{"intro":{"en":"Result comes from Latin resultare, to spring back, from re-, back, and saltare, to leap, a frequentative of salire, to jump. The verb passed through French into English; the phrasal frame with in is modern and its first date is approximate.","cn":"result 源自拉丁语 resultare「弹回」，由 re-「回」与 saltare「跳」构成，后者是 salire「跳跃」的反复形式。动词经法语进入英语；带介词的框架属近代，首见年代为约数。"},"items":[{"era":"LATIN SALIRE","en":"Salire means to jump and also underlies assault and assail.","cn":"salire 意为「跳」，也是 assault 与 assail 的根基。"},{"era":"LATIN SALTARE","en":"Saltare is the frequentative, to keep jumping or dance.","cn":"saltare 是反复形式，意为「不断跳、舞蹈」。"},{"era":"LATIN RESULTARE","en":"Resultare means to spring back, the image of something bouncing off a surface.","cn":"resultare 意为「弹回」，画出某物从表面弹开的画面。"},{"era":"FRENCH RESULTER","en":"French resulter shifted the image towards what follows from an action.","cn":"法语 resulter 把意象转向「由行为产生的结果」。"},{"era":"ENGLISH VERB AND NOUN","en":"English first used result as a verb, then as a noun for the outcome itself.","cn":"英语先用它作动词，再作指结果本身的名词。"},{"era":"ENGLISH PHRASE","en":"The frame fixes the outcome after the preposition; first dates are approximate.","cn":"这一框架把后果固定在介词之后，首见年代为约数。"}]},"similar":{"note":{"en":"The first group looks identical but reverses the arrow or changes the particle; the second group holds causal verbs of different strength.","cn":"第一组形似但箭头相反或小品词不同；第二组是力度不同的因果动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"result from","ipa":"/rɪˈzʌlt frɒm/","tag":"reversed arrow","definition":"It takes the outcome as subject and the cause after from, the mirror of this phrase.","definitionCN":"它以后果作主语、原因放在介词后，是本短语的镜像。"},{"word":"lead to","ipa":"/ˈliːd tuː/","tag":"process, not single step","definition":"It pictures a route with steps; result in states the outcome more directly.","definitionCN":"它画出有步骤的路线；本短语更直接地说出结果。"},{"word":"result in","ipa":"/rɪˈzʌlt ɪn/","tag":"the phrase itself","definition":"Note that the outcome, not the cause, is the object of in.","definitionCN":"注意介词宾语是后果，而非原因。"},{"word":"resulting in","ipa":"/rɪˈzʌltɪŋ ɪn/","tag":"participle","definition":"The participle attaches to a clause and explains the outcome of an action.","definitionCN":"分词形式挂在从句上，说明行为的结果。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cause","ipa":"/kɔːz/","tag":"direct assertion","definition":"It asserts causation plainly, with no image of a bouncing object.","definitionCN":"它直白地断言因果，没有弹回物的意象。"},{"word":"bring about","ipa":"/brɪŋ əˈbaʊt/","tag":"deliberate action","definition":"It usually implies an agent who intentionally produces the outcome.","definitionCN":"它通常暗示施事者有意造成后果。"},{"word":"give rise to","ipa":"/ɡɪv raɪz tuː/","tag":"formal origin","definition":"It pictures an outcome rising from a source, common in formal prose.","definitionCN":"它画出后果自源头升起，多见于正式文字。"},{"word":"produce","ipa":"/prəˈdjuːs/","tag":"manufacture image","definition":"It treats the outcome as something made, often deliberately.","definitionCN":"它把后果当作被制造出来的东西，常带有意为之。"}]}]},"mnemonics":{"normalIntro":{"en":"The normal associations use the real Latin leap, the arrow direction and the contrasting frame.","cn":"正常联想使用真实的拉丁语「跳」、箭头方向与反向框架。"},"normal":[{"en":"The Latin verb meant to spring back, so a result is what bounces out of an action.","cn":"拉丁动词意为「弹回」，结果就是行为弹出来的东西。"},{"en":"In this frame the subject is the cause and the object is the outcome.","cn":"此框架里主语是原因，宾语是后果。"},{"en":"Its mirror result from puts the outcome first; the two mark the arrow.","cn":"镜像短语把后果放前，两者共同标出箭头。"},{"en":"The frame is value-neutral: gains and losses both fit.","cn":"框架对价值中性，收益与损失都能进。"},{"en":"Compared with lead to, it states the endpoint more directly.","cn":"与「通向」相比，它更直接地说出终点。"}],"abstract":[{"en":"Like the first domino: one push, and the whole row falls in order.","cn":"像第一张骨牌：一推之下，整排依次倒下。"},{"en":"Like a ball striking a wall and rebounding into the player's hands.","cn":"像球撞墙弹回，落进球员手里。"},{"en":"Like a stone thrown into a pond, the splash arriving after the throw.","cn":"像石子投进池塘，水花在抛出之后才到。"}]},"examples":[{"en":"A delay in parts can result in a week-long shutdown.","cn":"零件延迟可能导致为期一周的停工。"},{"en":"Higher humidity can result in slower drying.","cn":"湿度升高可能导致干燥变慢。"},{"en":"One missed step can result in a failed audit.","cn":"漏掉一步就可能导致审计失败。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「瑞造特 因」——第一张骨牌被轻轻一推，整排依次倒下：导致；造成","word":"result in"},"root":"result 源自拉丁语 resultare「弹回」，由表示「回」的前缀与 saltare「跳」构成；这一框架属近代用法，首见年代为约数。","sensesIntro":{"en":"Eight senses split by the outcome: a general consequence, damage, an experimental reading, a gain, a disease, a formal penalty, a research chain and a delayed policy effect.","cn":"八个义项按后果类别区分：一般后果、损害、实验读数、收益、疾病、正式处罚、研究链条、延迟的政策后果。"},"semanticMap":{"core":{"en":"CORE IMAGE: the first domino pushed, the row falling in order to the finish line.","cn":"核心意象：第一张骨牌被推倒，整排依次倒向终点线。"},"chain":["SPRING BACK","SET THE CAUSE FIRST","NAME THE OUTCOME","HARM OR GAIN","FORMAL CONSEQUENCE","DELAYED EFFECT"],"branches":[{"senses":"01 · 07","en":"THE ARROW: cause in subject position, outcome after the preposition.","cn":"箭头：原因占主语位，后果在介词后。"},{"senses":"02 · 05","en":"THE HARM: fire, hearing loss and failure are outcomes nobody wants.","cn":"损害：火灾、听力损失与失败都是不想要的后果。"},{"senses":"03 · 04","en":"THE READING: experiments and training report measured gains or speeds.","cn":"读数：实验与培训报告可测量的收益或速度。"},{"senses":"06","en":"THE PENALTY: an authority imposes dismissal or a ruling.","cn":"处罚：权威施加解职或裁决。"},{"senses":"08","en":"THE DELAYED EFFECT: subsidies produce dependence only later.","cn":"延迟后果：补贴要到后来才造成依赖。"}]},"affixes":{"intro":{"en":"The Latin core is re-, back, plus saltare, to leap; resultare gives the English noun and verb.","cn":"拉丁核心是 re-「回」加 saltare「跳」；resultare 提供英语名词与动词。"},"latinIntro":{"en":"The Latin elements are re-, back, and saltare, to leap repeatedly; resultare joins them.","cn":"拉丁成分是 re-「回」与 saltare「反复跳」，resultare 由两者合成。"},"items":[{"word":"re-","structure":"Latin prefix","meaning":"back; again","meaningCN":"回；再","example":"The prefix turns a leap into a rebound.","exampleCN":"前缀把跳跃变成弹回。"},{"word":"salire","structure":"Latin verb, fourth conjugation","meaning":"to jump","meaningCN":"跳跃","example":"The verb underlies several English words of leaping.","exampleCN":"这个动词是若干表示跳跃的英语词的根基。"},{"word":"saltare","structure":"Frequentative of salire","meaning":"to keep jumping; dance","meaningCN":"反复跳；舞蹈","example":"The frequentative adds repeated motion.","exampleCN":"反复形式加上重复动作。"},{"word":"resultare","structure":"re- + saltare, Latin verb","meaning":"to spring back","meaningCN":"弹回","example":"The verb supplies the English family.","exampleCN":"这个动词提供英语同族词。"},{"word":"result","structure":"English noun and verb","meaning":"outcome; to follow as a consequence","meaningCN":"结果；导致","example":"The word works as both noun and verb.","exampleCN":"这个词兼作名词与动词。"},{"word":"resultant","structure":"result + -ant","meaning":"following as a consequence","meaningCN":"由此产生的；合力","example":"Physics uses the noun for a combined force.","exampleCN":"物理学用这个名词指合力。"},{"word":"result from","structure":"result + from, fixed phrase","meaning":"to be caused by","meaningCN":"由……造成","example":"The mirror frame reverses the arrow.","exampleCN":"镜像框架把箭头倒过来。"},{"word":"result in","structure":"result + in, fixed phrase","meaning":"to cause","meaningCN":"导致","example":"The frame fixes the outcome after the preposition.","exampleCN":"框架把后果固定在介词后。"}],"latinEntries":[{"word":"salire","structure":"salire, salio, salui, saltum (verb, fourth conjugation)","meaning":"to jump","meaningCN":"跳跃"},{"word":"resultare","structure":"resultare, resulto, resultavi (re- + saltare)","meaning":"to spring back","meaningCN":"弹回"}],"derivatives":[{"word":"result","pos":"n./v.","zh":"结果；导致"},{"word":"resultant","pos":"adj./n.","zh":"由此产生的；合力"},{"word":"resulting","pos":"adj.","zh":"由此产生的"},{"word":"result from","pos":"v. phr.","zh":"由……造成"},{"word":"result-oriented","pos":"adj.","zh":"结果导向的"}]}},{"word":"result from","ipa_uk":"/rɪˈzʌlt frɒm/","ipa_us":"/rɪˈzʌlt frɑːm/","definition_zh":"由……造成；因……而产生（先说后果，再追原因）","definition_en":"to happen as a consequence of something, with the outcome as subject and the cause after the preposition","core_image":"河床上散落的石块被水流磨圆，镜头顺着来水方向追到上游的岩壁","scene":"河床上散着一层被磨圆的石块，镜头顺着来水方向追到上游的岩壁。Most of these stones result from years of water erosion.","sceneCN":"这里指石块是多年水流侵蚀造成的（第 1 个义项：由……造成）；句意为这些石块大多由多年水流侵蚀造成。图中可辨识物件：河床、圆石、上游岩壁、水流。","pos":[{"tag":"v. phr.","zh":"动词短语：由……造成；起因于"},{"tag":"idiom","zh":"固定搭配：后果追因"}],"collocations":[{"phrase":"result from a lack of","zh":"因缺乏……而产生"},{"phrase":"result from the interaction of","zh":"由……的相互作用造成"},{"phrase":"result from changes in","zh":"由……的变化造成"},{"phrase":"result from the fact that","zh":"由于……这一事实而产生"},{"phrase":"result from years of neglect","zh":"由多年忽视造成"},{"phrase":"result from a combination of factors","zh":"由多种因素共同造成"}],"forms":[{"label":"原形","form":"result from"},{"label":"第三人称单数","form":"results from"},{"label":"过去式","form":"resulted from"},{"label":"过去分词","form":"resulted from"},{"label":"现在分词","form":"resulting from"}],"derivatives":[{"word":"result","pos":"n./v.","zh":"由拉丁语「弹回」动词经法语而来，义为「结果；导致」"},{"word":"resultant","pos":"adj./n.","zh":"由该动词加形容词尾构成，义为「由此产生的；合力」"},{"word":"resulting","pos":"adj.","zh":"由该动词加分词尾构成，义为「由此产生的」"},{"word":"result in","pos":"v. phr.","zh":"同根的反向框架，义为「导致」"},{"word":"as a result","pos":"adv. phr.","zh":"由介词加名词构成，义为「因此」"}],"senses":[{"no":"01","title":"Outcome traced to its cause","titleCN":"后果追到原因","definition":"used when the subject is the outcome and the cause follows the preposition","definitionCN":"主语是后果，原因放在介词之后","example":"Most of these stones result from years of water erosion.","exampleCN":"这些石块大多由多年水流侵蚀造成。","why":"The preposition points backward along the arrow, so the sentence starts at the effect and ends at the source.","whyCN":"介词沿箭头向后指，句子便从结果起笔，落到源头。"},{"no":"02","title":"Coming from a source","titleCN":"源于某一原因","definition":"used to name the origin of a situation or condition","definitionCN":"点出某种情形或状况的来源","example":"The shortage can result from a single failed shipment.","exampleCN":"短缺可能源于一次失败的运货。","why":"The cause is a single identifiable event, so the frame reads like a receipt showing where something came from.","whyCN":"原因是单一可识别事件，框架读起来像一张标明来源的收据。"},{"no":"03","title":"A medical origin","titleCN":"因……而产生（疾病）","definition":"used when a disease or symptom has a stated cause","definitionCN":"疾病或症状有明确原因时使用","example":"Hearing loss can result from prolonged exposure to noise.","exampleCN":"听力损失可能因长期接触噪声而产生。","why":"Medicine uses the frame to separate a condition from the exposure that produced it.","whyCN":"医学用这一框架把病症与造成它的接触分开。"},{"no":"04","title":"A dispute or problem","titleCN":"由……引起（争议、问题）","definition":"used when a problem or conflict has an identifiable origin","definitionCN":"问题或冲突有可识别源头时使用","example":"Much of the dispute can result from a simple misunderstanding.","exampleCN":"这场争执很大程度可能由一次简单的误解引起。","why":"With disputes, tracing the origin is often the first step towards settling it.","whyCN":"涉及争执时，追源往往是化解的第一步。"},{"no":"05","title":"The source of data","titleCN":"数据来源于","definition":"used to state where figures or samples came from","definitionCN":"说明数字或样本的来源","example":"These figures can result from a sample of only forty farms.","exampleCN":"这些数字可能来自仅四十个农场的样本。","why":"In data writing the frame warns the reader that the numbers are an artefact of the method.","whyCN":"在数据写作中，这一框架提醒读者数字是方法的产物。"},{"no":"06","title":"A weaker attribution","titleCN":"弱化版的归因","definition":"used to attribute an outcome without the force of be attributed to","definitionCN":"把结果归到某原因，但力度弱于「被归因于」","example":"The fall in sales can result from seasonal factors.","exampleCN":"销量下降可能由季节因素造成。","why":"The frame names a mechanism rather than an author, which is why it is softer than direct attribution.","whyCN":"这一框架点出机制而非责任者，因此比直接归因更软。"},{"no":"07","title":"Arising from conditions","titleCN":"起因于条件或环境","definition":"used when circumstances rather than agents produce the outcome","definitionCN":"由环境条件而非施事者产生结果时使用","example":"Such losses can result from poor storage conditions.","exampleCN":"这类损失可能起因于糟糕的储存条件。","why":"Conditions are impersonal, so the sentence avoids blaming a person.","whyCN":"条件是非人格的，句子因此避免指责某个人。"},{"no":"08","title":"Derived by rule","titleCN":"由规则或制度派生","definition":"used when one arrangement follows from another by rule or logic","definitionCN":"一种安排按规则或逻辑由另一种派生时使用","example":"The obligation can result from the terms of the contract.","exampleCN":"这项义务可能由合同条款派生。","why":"Here the source is a rule, and the outcome is a consequence that follows by design.","whyCN":"这里源头是规则，结果是按设计随之而来的后果。"}],"etymology":{"intro":{"en":"Result comes from Latin resultare, to spring back, from re-, back, and saltare, to leap. French resulter narrowed the image to what follows from an action, and English borrowed the verb. The frame with from is modern and its first date is approximate.","cn":"result 源自拉丁语 resultare「弹回」，由 re-「回」与 saltare「跳」构成。法语 resulter 把意象收窄为「由行为随之而来」，英语借入该动词。带介词的框架属近代，首见年代为约数。"},"items":[{"era":"LATIN SALTARE","en":"Saltare, to leap repeatedly, derives from salire, to jump.","cn":"saltare 意为「反复跳」，出自 salire「跳跃」。"},{"era":"LATIN RESULTARE","en":"Resultare pictures something bouncing back off a surface.","cn":"resultare 画出某物从表面弹回的景象。"},{"era":"FRENCH RESULTER","en":"French shifted the sense from rebound to consequence.","cn":"法语把意义从「弹回」转向「随之产生的结果」。"},{"era":"ENGLISH NOUN AND VERB","en":"English uses result as both noun and verb, with the noun naming the outcome.","cn":"英语中该词兼作名词与动词，名词指结果。"},{"era":"ENGLISH PHRASE","en":"The frame marks the source after the preposition; first dates are approximate.","cn":"这一框架把源头放在介词后，首见年代为约数。"}]},"similar":{"note":{"en":"The first group reverses or reshapes the same frame; the second group holds other ways of naming a source.","cn":"第一组把同一框架倒转或改写；第二组是其他点明来源的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"result in","ipa":"/rɪˈzʌlt ɪn/","tag":"reversed arrow","definition":"It puts the cause first and the outcome after the preposition, the mirror of this phrase.","definitionCN":"它把原因放前、后果放后，是本短语的镜像。"},{"word":"resulting from","ipa":"/rɪˈzʌltɪŋ frɒm/","tag":"participle","definition":"The participle modifies a noun and states its source in one phrase.","definitionCN":"分词修饰名词，并在同一短语里说明来源。"},{"word":"stem from","ipa":"/stem frɒm/","tag":"deeper root","definition":"It stresses an origin or root rather than a straightforward causal link.","definitionCN":"它强调根源，而非直白的因果联系。"},{"word":"be attributed to","ipa":"/biː əˈtrɪbjuːtɪd tuː/","tag":"assigned by an observer","definition":"It reports who or what an observer credits, and can be wrong.","definitionCN":"它报告观察者把结果归给谁或什么，且可能归错。"}]},{"heading":"NEAR MEANING","entries":[{"word":"arise from","ipa":"/əˈraɪz frɒm/","tag":"formal origin","definition":"It states that something comes into being out of a source.","definitionCN":"它说明某物自某个源头产生。"},{"word":"derive from","ipa":"/dɪˈraɪv frɒm/","tag":"descent or extraction","definition":"It stresses descent or extraction, common in linguistics and history.","definitionCN":"它强调承袭或提取，多见于语言学与历史。"},{"word":"follow from","ipa":"/ˈfɒləʊ frɒm/","tag":"logical consequence","definition":"It marks a conclusion that follows by logic rather than by causation.","definitionCN":"它标出按逻辑而非因果随之而来的结论。"},{"word":"be caused by","ipa":"/biː kɔːzd baɪ/","tag":"plain causation","definition":"It states causation directly, with no image and no hedging.","definitionCN":"它直白陈述因果，没有意象也不留余地。"}]}]},"mnemonics":{"normalIntro":{"en":"The normal associations use the real Latin leap, the arrow direction and the contrast with attribution.","cn":"正常联想使用真实的拉丁语「跳」、箭头方向以及与归因的对比。"},"normal":[{"en":"The arrow points backwards here: effect first, source last.","cn":"此处箭头向后：结果在前，源头在后。"},{"en":"Its mirror result in puts the cause first.","cn":"镜像短语把原因放前。"},{"en":"From names a source, not a purpose.","cn":"介词引出源头，而非目的。"},{"en":"Compared with be attributed to, it names a mechanism rather than a judge.","cn":"与「被归因于」相比，它点出机制而非评判者。"},{"en":"If the outcome follows by rule rather than by force, this frame still works.","cn":"若结果按规则而非强力而来，这一框架同样适用。"}],"abstract":[{"en":"Like rounded stones on a riverbed, each one pointing upstream to the rock it came from.","cn":"像河床上的圆石，每一块都指向上游的岩壁。"},{"en":"Like reading a receipt backwards to find which shop issued it.","cn":"像倒着读收据，找出是哪家店开的。"},{"en":"Like a tree's rings counted back to the year the drought began.","cn":"像数年轮，一路追到干旱开始的那一年。"}]},"examples":[{"en":"The flooding can result from a blocked drain.","cn":"这场内涝可能由排水管堵塞造成。"},{"en":"These errors can result from a poorly written manual.","cn":"这些错误可能源于编写拙劣的手册。"},{"en":"The decline can result from changes in consumer habits.","cn":"销量下滑可能由消费习惯变化造成。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「瑞造特 弗龙」——河床上的圆石，一块块都指向上游的岩壁：由……造成","word":"result from"},"root":"result 源自拉丁语 resultare「弹回」，由表示「回」的前缀与 saltare「跳」构成；这一框架属近代用法，首见年代为约数。","sensesIntro":{"en":"Eight senses split by the source: an erosion-like cause, a single event, a disease, a dispute, a data sample, an attribution, a condition and a rule.","cn":"八个义项按源头类别区分：类似侵蚀的原因、单一事件、疾病、争执、数据样本、归因、条件、规则。"},"semanticMap":{"core":{"en":"CORE IMAGE: rounded stones on a riverbed, each pointing upstream to the rock face they came from.","cn":"核心意象：河床上的圆石，每一块都指向上游的岩壁。"},"chain":["SPRING BACK","PUT THE OUTCOME FIRST","TRACE THE SOURCE","NAME AN IMPERSONAL CAUSE","STATE A MEDICAL ORIGIN","FOLLOW A RULE"],"branches":[{"senses":"01 · 02","en":"THE BACKWARD ARROW: the sentence begins at the effect and ends at the source.","cn":"后指箭头：句子从结果起笔，落到源头。"},{"senses":"03 · 04","en":"THE AFFLICTION: disease and dispute are outcomes that invite tracing.","cn":"病痛与争执：都是需要追源的后果。"},{"senses":"05 · 06","en":"THE METHOD AND THE MECHANISM: samples produce figures, mechanisms produce outcomes.","cn":"方法与机制：样本产生数字，机制产生结果。"},{"senses":"07","en":"THE CONDITION: storage, climate and neglect act without a personal agent.","cn":"条件：储存、气候与忽视都在无人的情况下起作用。"},{"senses":"08","en":"THE RULE: a contract or regulation makes one arrangement follow from another.","cn":"规则：合同或法规使一种安排由另一种派生。"}]},"affixes":{"intro":{"en":"The Latin core is re-, back, plus saltare, to leap; the English noun and verb keep the image of something rebounding.","cn":"拉丁核心是 re-「回」加 saltare「跳」；英语名词与动词保留弹回的意象。"},"latinIntro":{"en":"The Latin elements are re-, back, and saltare, to leap; resultare supplies the family.","cn":"拉丁成分是 re-「回」与 saltare「跳」，resultare 提供同族词。"},"items":[{"word":"re-","structure":"Latin prefix","meaning":"back; again","meaningCN":"回；再","example":"The prefix reverses the direction of the leap.","exampleCN":"前缀把跳跃的方向反过来。"},{"word":"salire","structure":"Latin verb, fourth conjugation","meaning":"to jump","meaningCN":"跳跃","example":"The verb gives the image of motion.","exampleCN":"这个动词提供动作意象。"},{"word":"saltare","structure":"Frequentative of salire","meaning":"to keep jumping","meaningCN":"反复跳","example":"The frequentative adds repetition.","exampleCN":"反复形式加上重复。"},{"word":"resultare","structure":"re- + saltare, Latin verb","meaning":"to spring back","meaningCN":"弹回","example":"The compound verb is the source of the family.","exampleCN":"复合动词是整族词的源头。"},{"word":"result","structure":"English noun and verb","meaning":"outcome; to follow","meaningCN":"结果；随之产生","example":"The noun names what follows an action.","exampleCN":"名词指行为之后出现之物。"},{"word":"resultant","structure":"result + -ant","meaning":"following as a consequence","meaningCN":"由此产生的","example":"The adjective describes a derived effect.","exampleCN":"形容词描述派生的效果。"},{"word":"result from","structure":"result + from, fixed phrase","meaning":"to be caused by","meaningCN":"由……造成","example":"The frame puts the source after the preposition.","exampleCN":"框架把源头放在介词后。"},{"word":"as a result","structure":"preposition + noun, fixed phrase","meaning":"consequently","meaningCN":"因此","example":"The noun also works in a standalone connector.","exampleCN":"名词也用于独立连接语。"}],"latinEntries":[{"word":"salire","structure":"salire, salio, salui, saltum (verb, fourth conjugation)","meaning":"to jump","meaningCN":"跳跃"},{"word":"resultare","structure":"resultare, resulto, resultavi (re- + saltare)","meaning":"to spring back","meaningCN":"弹回"}],"derivatives":[{"word":"result","pos":"n./v.","zh":"结果；导致"},{"word":"resultant","pos":"adj./n.","zh":"由此产生的；合力"},{"word":"resulting","pos":"adj.","zh":"由此产生的"},{"word":"result in","pos":"v. phr.","zh":"导致"},{"word":"as a result","pos":"adv. phr.","zh":"因此"}]}},{"word":"stem from","ipa_uk":"/stem frɒm/","ipa_us":"/stem frɑːm/","definition_zh":"源自；由……发展而来；起因于某一根源","definition_en":"to originate in or be rooted in something, often a deeper cause rather than an immediate one","core_image":"一株植物的主茎从土壤里长出来，切口处露出旧年的年轮","scene":"田里一株植物的主茎从土里拔起，根颈处露出旧年的轮纹。All these branches stem from one old root.","sceneCN":"这里指枝条都由同一条老根生长出来（第 2 个义项：由植物主干长出）；句意为这些枝条都源自同一条老根。图中可辨识物件：主茎、土壤、根颈、轮纹。","pos":[{"tag":"v. phr.","zh":"动词短语：源自；起因于"},{"tag":"idiom","zh":"固定搭配：追到根源"}],"collocations":[{"phrase":"stem from a lack of","zh":"源自缺乏……"},{"phrase":"stem from the same cause","zh":"源自同一原因"},{"phrase":"stem from a misunderstanding","zh":"起因于误解"},{"phrase":"stem from long-standing practice","zh":"源自长期的做法"},{"phrase":"stem from economic pressure","zh":"源自经济压力"},{"phrase":"stem from a shared tradition","zh":"源自共同传统"}],"forms":[{"label":"原形","form":"stem from"},{"label":"第三人称单数","form":"stems from"},{"label":"过去式","form":"stemmed from"},{"label":"现在分词","form":"stemming from"},{"label":"名词","form":"stem"}],"derivatives":[{"word":"stem","pos":"n./v.","zh":"由古英语「树干、主茎」名词而来，义为「茎；起源于」"},{"word":"stemming","pos":"n.","zh":"由该动词加名词尾构成，义为「词干化；去茎」"},{"word":"stemless","pos":"adj.","zh":"由该名词加「无……的」形容词尾构成，义为「无茎的」"},{"word":"stem cell","pos":"n.","zh":"由该名词加「细胞」构成的复合词，义为「干细胞」"},{"word":"stem the tide","pos":"v. phr.","zh":"由该动词构成的固定说法，义为「遏制潮流」"}],"senses":[{"no":"01","title":"Rooted in a deeper cause","titleCN":"源自更深的根源","definition":"to have a deep origin rather than an immediate trigger","definitionCN":"来源较深，而非眼前的触发因素","example":"Many of these complaints stem from a single faulty design.","exampleCN":"这些投诉许多都源自一处设计缺陷。","why":"The plant image makes the cause a root: hidden, older and feeding everything above it.","whyCN":"植物意象把原因变成根：藏在地下、时间更久、供养上方的一切。"},{"no":"02","title":"Growing from a main stalk","titleCN":"由植物主干长出","definition":"literally, to grow out from the stem of a plant","definitionCN":"字面上指从植物的主茎上长出","example":"All these branches stem from one old root.","exampleCN":"这些枝条都源自同一条老根。","why":"This is the literal image; every figurative sense keeps something of its direction.","whyCN":"这是字面意象，所有引申义都保留它的方向感。"},{"no":"03","title":"The origin of a problem","titleCN":"问题的起因","definition":"used to name the root of a difficulty","definitionCN":"点出困难的根源","example":"The delay can stem from a backlog in the approval office.","exampleCN":"延误可能起因于审批部门的积压。","why":"Calling something a root suggests that removing the symptom will not fix it.","whyCN":"称之为根，意味着只去除症状并不能解决问题。"},{"no":"04","title":"A belief or tradition","titleCN":"观念或传统的来源","definition":"used when a custom or view has a long history","definitionCN":"某种习俗或看法有很长历史时使用","example":"These taboos stem from an old farming calendar.","exampleCN":"这些禁忌源自一份古老的农事历。","why":"A custom is a root that has grown for generations, so the phrase reports age rather than a trigger.","whyCN":"习俗是长了许多代的根，因此短语报告的是年岁而非触发点。"},{"no":"05","title":"A linguistic origin","titleCN":"词语或语言来源","definition":"used in language study for the source of a word or form","definitionCN":"在语言研究中指词或形式的来源","example":"Many legal terms stem from Latin formulas.","exampleCN":"许多法律术语源自拉丁语套语。","why":"Here the root is literal in the etymological sense, which is why the phrase fits so well.","whyCN":"这里的「根」是词源学意义上的字面用法，因此这个短语格外贴合。"},{"no":"06","title":"Derived by rule or form","titleCN":"由规则或形式派生","definition":"used when one form develops out of another","definitionCN":"一种形式由另一种发展而来时使用","example":"Most of these endings stem from an older suffix.","exampleCN":"这些词尾大多源自一个更古老的词缀。","why":"Forms branch from older material exactly as stems branch from a root.","whyCN":"形式自更早的材料分出，正如枝条自根分出。"},{"no":"07","title":"Rooted in attitude","titleCN":"根植于态度或心理","definition":"used when behaviour grows out of a long-held feeling","definitionCN":"行为由长期持有的情绪生长出来时使用","example":"Their resistance can stem from a fear of being judged.","exampleCN":"他们的抵触可能根植于害怕被评判。","why":"Resistance that has grown over years behaves like a root, not like a reaction to one event.","whyCN":"多年长成的抵触像根，而不像对某一事件的反应。"},{"no":"08","title":"Tracing causes in academic prose","titleCN":"学术写作中的追因","definition":"used in research writing to move from a phenomenon to its underlying cause","definitionCN":"在研究写作中从现象追到深层原因","example":"The pattern can stem from differences in local soil.","exampleCN":"这一格局可能源自各地土壤的差异。","why":"Research moves from an observed pattern to the condition that feeds it.","whyCN":"研究从观察到的格局追到供养它的条件。"}],"etymology":{"intro":{"en":"Stem is an Old English noun, stemn, meaning the main stalk of a tree, from a Germanic noun reconstructed as stamniz and related to the word for a staff. The verb use with from is a later English development; its first date is approximate.","cn":"stem 是古英语名词 stemn，指树木的主干，出自日耳曼语重构名词，与表示「杖」的词相关。与介词连用的动词用法是较晚的英语发展，首见年代为约数。"},"items":[{"era":"OLD ENGLISH STEMN","en":"Stemn named the trunk or main stalk of a tree or plant.","cn":"stemn 指树或植物的主干、主茎。"},{"era":"GERMANIC STEM","en":"The reconstructed noun stamniz is related to the word for a staff or post.","cn":"重构名词与表示「杖、柱」的词相关。"},{"era":"NAUTICAL SENSE","en":"Stem also named the upright post at the bow of a ship, from the same idea of a main upright.","cn":"该词也指船首的竖柱，取同一「主竖杆」之意。"},{"era":"ENGLISH VERB USE","en":"To stem from develops from the image of branches growing out of a stalk.","cn":"「源自」一义由枝条自主茎长出的意象发展而来。"},{"era":"MODERN PHRASE","en":"The frame is common in modern analysis; first dates are approximate.","cn":"这一框架在近代分析文字中常见，首见年代为约数。"}]},"similar":{"note":{"en":"The first group shares the noun or the verb and changes the pattern; the second group holds other verbs of origin.","cn":"第一组共用该名词或动词而改变搭配；第二组是其他表示来源的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"stem","ipa":"/stem/","tag":"the bare noun or verb","definition":"Alone it means a stalk, or to stop a flow, not to originate.","definitionCN":"单独使用时指茎，或指遏止水流，并不表示「源自」。"},{"word":"stemming","ipa":"/ˈstemɪŋ/","tag":"technical noun","definition":"In computing it means reducing words to their stems, an unrelated use.","definitionCN":"在计算机领域指把词缩减为词干，属另一用法。"},{"word":"stem the tide","ipa":"/stem ðə taɪd/","tag":"stop, not originate","definition":"Here the verb means to check or hold back, from a different sense.","definitionCN":"此处动词意为「阻挡、遏止」，来自另一义项。"},{"word":"stem from","ipa":"/stem frɒm/","tag":"the phrase itself","definition":"Note that from names the root, never the branch.","definitionCN":"注意介词引出根源，而非枝条。"}]},{"heading":"NEAR MEANING","entries":[{"word":"originate from","ipa":"/əˈrɪdʒɪneɪt frɒm/","tag":"neutral origin","definition":"It states a beginning without the depth that a root implies.","definitionCN":"它只说明起点，不带「根」所暗示的纵深。"},{"word":"derive from","ipa":"/dɪˈraɪv frɒm/","tag":"descent","definition":"It stresses descent or extraction, common in language and history.","definitionCN":"它强调承袭或提取，多见于语言与历史。"},{"word":"arise from","ipa":"/əˈraɪz frɒm/","tag":"emergence","definition":"It pictures something coming into being out of a situation.","definitionCN":"它画出某物自某种情形中产生。"},{"word":"be rooted in","ipa":"/biː ˈruːtɪd ɪn/","tag":"the same plant image","definition":"It keeps the root metaphor openly and often describes beliefs.","definitionCN":"它明用根喻，常描述观念。"}]}]},"mnemonics":{"normalIntro":{"en":"The normal associations use the real plant image, the real noun history and the contrast with neutral origins.","cn":"正常联想使用真实的植物意象、真实的名词历史以及与中性来源词的对比。"},"normal":[{"en":"A stem is the main stalk, so the cause is what feeds every branch.","cn":"主茎是主干，原因便是供养所有枝条的东西。"},{"en":"The phrase points downward: from the branch back to the root.","cn":"短语向下指：从枝条回到根。"},{"en":"From names the root, never the result.","cn":"介词引出根源，从不引出结果。"},{"en":"Bare stem means to stop a flow, a different sense entirely.","cn":"单独使用时意为遏止水流，属另一义项。"},{"en":"It claims depth, so removing the symptom will not satisfy it.","cn":"它主张纵深，只除症状并不能满足它。"}],"abstract":[{"en":"Like lifting a plant and finding the old rings at the root neck.","cn":"像拔起一株植物，在根颈处看到旧年的轮纹。"},{"en":"Like tracing a river back through tributaries to one spring.","cn":"像顺支流把河流一路追到一眼泉。"},{"en":"Like a family tree where every branch meets at one ancestor.","cn":"像族谱，所有支系都汇到同一位祖先。"}]},"examples":[{"en":"The disagreement can stem from a difference in definitions.","cn":"这场分歧可能源自定义上的差异。"},{"en":"Many of these habits stem from an older way of working.","cn":"这些习惯许多都源自更早的工作方式。"},{"en":"The rise in costs can stem from a single supply problem.","cn":"成本上升可能源自一处供应问题。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「斯泰姆 弗龙」——拔起一株植物，根颈处露出旧年的轮纹：源自；根植于","word":"stem from"},"root":"stem 是古英语名词 stemn「主干、主茎」，出自日耳曼语重构名词，与表示「杖」的词相关；这一框架是较晚的英语发展，首见年代为约数。","sensesIntro":{"en":"Eight senses split by the kind of root: a deep cause, a literal stalk, a problem, a tradition, a word, a form, an attitude and an academic explanation.","cn":"八个义项按根源类别区分：深层原因、字面主茎、问题、传统、词语、形式、态度、学术解释。"},"semanticMap":{"core":{"en":"CORE IMAGE: a plant pulled from the soil, old rings visible at the root neck.","cn":"核心意象：一株植物从土里拔起，根颈处露出旧年轮纹。"},"chain":["MAIN STALK","BRANCHES GROW OUT","TRACE TO THE ROOT","NAME A DEEP CAUSE","LANGUAGE AND FORM","ACADEMIC EXPLANATION"],"branches":[{"senses":"01 · 03","en":"THE HIDDEN ROOT: the cause lies underground, older than the symptom.","cn":"暗根：原因在地下，比症状更老。"},{"senses":"02","en":"THE LITERAL STALK: branches visibly grow out of one stem.","cn":"字面主茎：枝条明显自一根主茎长出。"},{"senses":"04 · 07","en":"THE LONG HISTORY: traditions and attitudes grow slowly and outlive one lifetime.","cn":"长历史：传统与态度慢慢生长，跨越一生。"},{"senses":"05 · 06","en":"THE WORD AND THE FORM: suffixes and terms descend from older material.","cn":"词与形式：词缀与术语自更早的材料承袭。"},{"senses":"08","en":"THE EXPLANATION: research moves from a pattern to its underlying condition.","cn":"解释：研究从格局追到其底层条件。"}]},"affixes":{"intro":{"en":"Stem is a Germanic noun, not a Latin one, so the affix set traces the Old English noun and its English family.","cn":"stem 是日耳曼语名词而非拉丁语名词，因此词缀部分追溯古英语名词及其英语同族词。"},"latinIntro":{"en":"There is no Latin etymon here; the root is the Old English noun stemn and its Germanic ancestor.","cn":"此处没有拉丁语词源；词根是古英语名词 stemn 及其日耳曼语祖形。"},"items":[{"word":"stemn","structure":"Old English noun","meaning":"trunk; main stalk","meaningCN":"主干；主茎","example":"The noun named the upright axis of a plant.","exampleCN":"名词指植物的直立主轴。"},{"word":"stamniz","structure":"Germanic noun, reconstructed","meaning":"stem; post","meaningCN":"茎；柱","example":"The reconstructed noun is shared by several Germanic languages.","exampleCN":"重构名词为若干日耳曼语共有。"},{"word":"stem","structure":"English noun and verb","meaning":"stalk; to stop a flow; to originate","meaningCN":"茎；遏止；源自","example":"The verb has two separate senses.","exampleCN":"动词有两个互不相干的义项。"},{"word":"stemming","structure":"stem + -ing","meaning":"reducing to stems","meaningCN":"词干化","example":"The technical noun belongs to computing and linguistics.","exampleCN":"这一技术名词属计算机与语言学。"},{"word":"stemless","structure":"stem + -less","meaning":"without a stalk","meaningCN":"无茎的","example":"The suffix means lacking.","exampleCN":"后缀表示「没有」。"},{"word":"stem cell","structure":"stem + cell, compound noun","meaning":"a cell that can develop into others","meaningCN":"干细胞","example":"Biology uses the stalk image for a source cell.","exampleCN":"生物学用主茎意象指源头细胞。"},{"word":"stem the tide","structure":"stem + the tide, fixed phrase","meaning":"to check a flow","meaningCN":"遏止潮流","example":"Here the verb keeps its stopping sense.","exampleCN":"此处动词保留「阻挡」义。"},{"word":"stem from","structure":"stem + from, fixed phrase","meaning":"to originate in","meaningCN":"源自","example":"The frame fixes the root after the preposition.","exampleCN":"框架把根源固定在介词后。"}],"latinEntries":[],"derivatives":[{"word":"stem","pos":"n./v.","zh":"茎；遏止；源自"},{"word":"stemming","pos":"n.","zh":"词干化；去茎"},{"word":"stemless","pos":"adj.","zh":"无茎的"},{"word":"stem cell","pos":"n.","zh":"干细胞"},{"word":"stem the tide","pos":"v. phr.","zh":"遏止潮流"}]}},{"word":"take into account","ipa_uk":"/teɪk ˈɪntuː əˈkaʊnt/","ipa_us":"/teɪk ˈɪntuː əˈkaʊnt/","definition_zh":"考虑到；把……计入；把某一因素纳入判断或计算之中","definition_en":"to include a factor in a judgement, plan or calculation so that it affects the result","core_image":"账房先生把一叠票据逐张摊开，最后在账页上添上一笔","scene":"账房里一叠票据摊在桌上，先生逐张核过后在账页上添上一笔。Good planners take into account the cost of repair, not only the price of purchase.","sceneCN":"这里指规划者把修理费用也纳入计算（第 2 个义项：把……计入计算）；句意为好的规划者会把修理成本计入，而不只看购买价格。图中可辨识物件：账本、票据、算盘、笔。","pos":[{"tag":"v. phr.","zh":"动词短语：考虑到；计入"},{"tag":"idiom","zh":"固定搭配：纳入判断"}],"collocations":[{"phrase":"take into account the cost","zh":"把成本考虑在内"},{"phrase":"take into account the needs of","zh":"顾及……的需求"},{"phrase":"take into account local conditions","zh":"考虑当地条件"},{"phrase":"take into account the time required","zh":"把所需时间计算在内"},{"phrase":"take into account all the evidence","zh":"考虑全部证据"},{"phrase":"take into account the risks involved","zh":"考虑其中的风险"}],"forms":[{"label":"原形","form":"take into account"},{"label":"第三人称单数","form":"takes into account"},{"label":"过去式","form":"took into account"},{"label":"过去分词","form":"taken into account"},{"label":"现在分词","form":"taking into account"},{"label":"被动形","form":"be taken into account"}],"derivatives":[{"word":"take","pos":"v.","zh":"由古诺斯语「抓取」动词而来，义为「拿；取」"},{"word":"account","pos":"n./v.","zh":"由古法语「账目」一词而来，义为「账；说明」"},{"word":"accountable","pos":"adj.","zh":"由该名词加「可……的」形容词尾构成，义为「负有责任的」"},{"word":"accounting","pos":"n.","zh":"由该动词加名词尾构成，义为「会计」"},{"word":"account for","pos":"v. phr.","zh":"由该动词加介词构成，义为「解释；占」"}],"senses":[{"no":"01","title":"Including a factor in a judgement","titleCN":"判断时把某因素纳入","definition":"to include something when forming an opinion or decision","definitionCN":"形成意见或决定时把某物纳入","example":"Reviewers must take into account the limits of the sample.","exampleCN":"评审者必须把样本的局限考虑在内。","why":"The phrase pictures an account book: what is not entered does not count.","whyCN":"短语画出账本：没有记入的就不算数。"},{"no":"02","title":"Including a figure in a calculation","titleCN":"计算时计入数字","definition":"to add a cost, quantity or time to a calculation","definitionCN":"把成本、数量或时间加入计算","example":"Good planners take into account the cost of repair, not only the price of purchase.","exampleCN":"好的规划者会把修理成本计入，而不只看购买价格。","why":"Here the factor has a number, so the image of the ledger becomes literal.","whyCN":"这里因素带有数字，账本意象变成字面用法。"},{"no":"03","title":"Considering someone's feelings","titleCN":"顾及他人感受","definition":"to allow for other people's needs or feelings","definitionCN":"把别人的需求或感受纳入考虑","example":"Good hosts take into account the dietary needs of every guest.","exampleCN":"周到的主人会顾及每位客人的饮食需求。","why":"The account book turns social: what is entered is another person's comfort.","whyCN":"账本转向社交：记入的是他人的舒适。"},{"no":"04","title":"Weighing a risk","titleCN":"把风险纳入评估","definition":"to include a possible hazard when assessing a plan","definitionCN":"评估计划时把可能的危险纳入","example":"Engineers must take into account the risk of flooding.","exampleCN":"工程师必须把洪水风险考虑在内。","why":"A hazard is entered as a line in the assessment, so it changes the final tally.","whyCN":"危险作为一条评估项目被记入，因此会改变最终合计。"},{"no":"05","title":"Balancing pros and cons","titleCN":"权衡利弊","definition":"to weigh advantages against disadvantages before deciding","definitionCN":"决定前把利与弊放在一起衡量","example":"Committees take into account both the benefits and the disruption.","exampleCN":"委员会会兼顾收益与扰动。","why":"Both columns are entered on the same page, so neither can be ignored.","whyCN":"两栏都记在同一页上，任何一栏都无法被忽略。"},{"no":"06","title":"Reserving time or cost in planning","titleCN":"规划时预留时间或成本","definition":"to allow time or money for something in a schedule or budget","definitionCN":"在日程或预算中为某事留出时间或钱","example":"Builders take into account the weeks lost to rain.","exampleCN":"施工方会把因雨损失的那几周计算在内。","why":"Time and money are quantities, and an unentered quantity is never budgeted.","whyCN":"时间与金钱都是数量，未记入的数量就从未被预算。"},{"no":"07","title":"Failing to allow for something","titleCN":"未把某因素考虑在内","definition":"used in the negative to say that something was overlooked","definitionCN":"用否定式说明某因素被忽略","example":"These models do not take into account the cost of transport.","exampleCN":"这些模型没有把运输成本考虑在内。","why":"The negative form is the usual way to criticise a model or a plan.","whyCN":"否定式是批评模型或计划的常用方式。"},{"no":"08","title":"Before making a decision","titleCN":"决定前的考量","definition":"used to describe the stage before a choice is fixed","definitionCN":"选择定下之前的阶段","example":"The board will take into account the latest survey before voting.","exampleCN":"董事会在投票前会把最新调查考虑进去。","why":"The entry is made before the vote, so the phrase marks sequence rather than content.","whyCN":"记入发生在投票之前，因此短语标记的是顺序而非内容。"},{"no":"09","title":"As one variable in a model","titleCN":"作为模型中的一个变量","definition":"used in statistics to say that a variable enters a model","definitionCN":"在统计中说明某变量进入模型","example":"The model can take into account age as well as income.","exampleCN":"该模型可以把年龄与收入一并纳入。","why":"A model is a ledger of variables, and only what is entered can affect the output.","whyCN":"模型是变量的账本，只有记入的才能影响输出。"}],"etymology":{"intro":{"en":"Take comes from Old Norse taka, to grasp, which replaced the older English verb in the medieval period. Account comes through Old French acont from Latin computare, to reckon, built on com-, together, and putare, to think or reckon; the deeper origin of putare has more than one explanation. The phrase is modern and its first date is approximate.","cn":"take 来自古诺斯语 taka「抓取」，在中古英语时期取代了更早的本族动词。account 经古法语 acont 来自拉丁语 computare「计算」，由 com-「一起」与 putare「思量、计算」构成；putare 的更深来源有不止一种解释。短语属近代，首见年代为约数。"},"items":[{"era":"OLD NORSE TAKA","en":"Taka meant to grasp or seize and gradually replaced the native verb.","cn":"taka 意为「抓取」，逐渐取代了本族动词。"},{"era":"LATIN COMPUTARE","en":"Computare means to reckon together, the source of count and compute.","cn":"computare 意为「合起来计算」，是 count 与 compute 的来源。"},{"era":"LATIN PUTARE","en":"Putare meant to think or reckon; a proposed link to pruning is not settled.","cn":"putare 意为「思量、计算」；把它与「修剪」相联的说法尚无定论。"},{"era":"OLD FRENCH ACONT","en":"Old French acont named a reckoning or a settled bill.","cn":"古法语 acont 指一次结算或已结清的账单。"},{"era":"ENGLISH ACCOUNT","en":"English account keeps both the ledger sense and the sense of explanation.","cn":"英语的 account 兼有账目与说明两义。"},{"era":"ENGLISH PHRASE","en":"The frame is modern; first dates are approximate.","cn":"这一框架属近代用法，首见年代为约数。"}]},"similar":{"note":{"en":"The first group shares the same image but changes one word; the second group holds verbs of consideration.","cn":"第一组共用同一意象而更换一个词；第二组是表示考量的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"take account of","ipa":"/teɪk əˈkaʊnt ɒv/","tag":"no into","definition":"The shorter form drops into and is slightly more formal.","definitionCN":"较短形式省去一个介词，略正式一些。"},{"word":"take into consideration","ipa":"/teɪk ˈɪntuː ˌkɒnsɪdəˈreɪʃn/","tag":"same frame, longer noun","definition":"It is a near synonym and often interchangeable.","definitionCN":"它几乎是同义词，常可互换。"},{"word":"take for granted","ipa":"/teɪk fɔː ˈɡræntɪd/","tag":"opposite stance","definition":"It means to assume something without allowing for it, the reverse of this phrase.","definitionCN":"意为想当然而不予考虑，与本短语相反。"},{"word":"take over","ipa":"/teɪk ˈəʊvə/","tag":"unrelated particle","definition":"The same verb with another particle means to assume control.","definitionCN":"同一动词换小品词后意为「接管」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"consider","ipa":"/kənˈsɪdə/","tag":"general verb","definition":"It is the plain verb for thinking about something; the phrase adds the idea of entering a calculation.","definitionCN":"它只是「思考」的普通动词；本短语多出「纳入计算」之意。"},{"word":"allow for","ipa":"/əˈlaʊ fɔː/","tag":"leave room for","definition":"It stresses setting aside room or time for a factor.","definitionCN":"它强调为某因素留出余地或时间。"},{"word":"factor in","ipa":"/ˈfæktə ɪn/","tag":"technical register","definition":"It is the business and statistical twin, common in modelling.","definitionCN":"它是商业与统计语境的双胞胎，多见于建模。"},{"word":"weigh","ipa":"/weɪ/","tag":"balance image","definition":"It pictures putting things on a scale and judging between them.","definitionCN":"它画出把东西放上天平、相互权衡的画面。"}]}]},"mnemonics":{"normalIntro":{"en":"The normal associations use the real ledger image, the real verb pair and the contrast with taking for granted.","cn":"正常联想使用真实的账本意象、真实的动词配对以及与「想当然」的对比。"},"normal":[{"en":"An account is a ledger, so what is not entered does not count.","cn":"account 是账本，没有记入的就不算数。"},{"en":"Into marks the movement from outside the book to inside it.","cn":"介词标出从账外移入账内的动作。"},{"en":"The phrase is stronger than consider: the factor must change the result.","cn":"它比单纯「考虑」更强：因素必须改变结果。"},{"en":"The negative form is how critics say a model missed something.","cn":"否定式是批评者指出模型遗漏的方式。"},{"en":"Take for granted is its opposite stance, not its synonym.","cn":"「想当然」是它的反面，不是同义词。"}],"abstract":[{"en":"Like a clerk spreading receipts on a desk and entering every one.","cn":"像账房先生把票据摊开，逐张记入。"},{"en":"Like packing a bag with the weight of the return trip already counted.","cn":"像打包行李时把回程的重量也算进去。"},{"en":"Like a scale that registers the last grain, not only the big weights.","cn":"像天平连最后一粒也记下，不只看大砝码。"}]},"examples":[{"en":"Any estimate must take into account the cost of maintenance.","cn":"任何估算都必须把维护成本考虑在内。"},{"en":"Teachers take into account the different starting points of students.","cn":"教师会顾及学生不同的起点。"},{"en":"The plan did not take into account the winter closure of the road.","cn":"该计划没有把冬季封路考虑在内。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「泰克 因图 阿康特」——账房先生把票据逐张摊开，在账页上添上一笔：考虑到；计入","word":"take into account"},"root":"take 来自古诺斯语 taka「抓取」，中古英语时期取代本族动词；account 经古法语 acont 来自拉丁语 computare「计算」，由表示「一起」的前缀与 putare「思量」构成。该短语属近代用法，首见年代为约数。","sensesIntro":{"en":"Nine senses split the phrase by what enters the account: a judgement, a figure, a person's needs, a risk, a balance of pros and cons, reserved time, an overlooked factor, a pre-decision stage and a model variable.","cn":"九个义项按记入内容区分：判断、数字、他人需求、风险、利弊权衡、预留时间、被忽略的因素、决定前阶段、模型变量。"},"semanticMap":{"core":{"en":"CORE IMAGE: a clerk spreading receipts on a desk and entering each one in the ledger.","cn":"核心意象：账房先生把票据摊在桌上，逐张记入账本。"},"chain":["GRASP","ENTER THE LEDGER","COUNT THE FIGURE","ALLOW FOR PEOPLE","WEIGH THE RISK","SET THE MODEL"],"branches":[{"senses":"01 · 08","en":"THE JUDGEMENT: a factor enters before an opinion is fixed.","cn":"判断：因素在意见定下之前进入。"},{"senses":"02 · 06","en":"THE LEDGER: costs and reserved weeks become entries with numbers.","cn":"账本：成本与预留周数变成带数字的条目。"},{"senses":"03 · 05","en":"THE HUMAN SCALE: guests' needs and pros and cons are weighed together.","cn":"人的尺度：客人需求与利弊一并权衡。"},{"senses":"04 · 07","en":"THE MISSED RISK: hazards must be entered, and their absence is the criticism.","cn":"遗漏的风险：危险必须记入，缺席即成批评点。"},{"senses":"09","en":"THE MODEL: statistics lets a variable enter the equation.","cn":"模型：统计学让变量进入方程。"}]},"affixes":{"intro":{"en":"The phrase joins a Norse verb of grasping to a French-Latin noun of reckoning, so the affix set spans two language families.","cn":"短语把北欧语「抓取」动词与法语—拉丁语「计算」名词组合起来，词缀因此横跨两个语族。"},"latinIntro":{"en":"The Latin element is computare, to reckon, from com-, together, and putare, to think; the verb take has a Norse source.","cn":"拉丁语成分是 computare「计算」，由 com-「一起」与 putare「思量」构成；动词 take 来自北欧语。"},"items":[{"word":"taka","structure":"Old Norse verb","meaning":"to grasp; seize","meaningCN":"抓取；拿","example":"The Norse verb replaced the native one in Middle English.","exampleCN":"这个北欧语动词在中古英语时期取代了本族词。"},{"word":"take","structure":"English verb","meaning":"to grasp; to carry","meaningCN":"拿；取","example":"The verb is basic and highly productive.","exampleCN":"这个动词基础且极其能产。"},{"word":"com-","structure":"Latin prefix","meaning":"together","meaningCN":"一起","example":"The prefix makes the reckoning a joint one.","exampleCN":"前缀让计算成为合并的行为。"},{"word":"putare","structure":"Latin verb, first conjugation","meaning":"to think; reckon","meaningCN":"思量；计算","example":"Its deeper origin has more than one explanation.","exampleCN":"其更深来源有不止一种解释。"},{"word":"computare","structure":"com- + putare, Latin verb","meaning":"to reckon together","meaningCN":"合起来计算","example":"The verb gives count, compute and account.","exampleCN":"这个动词给出「计数」「计算」「账目」诸词。"},{"word":"acont","structure":"Old French noun","meaning":"a reckoning; a bill","meaningCN":"结算；账单","example":"French carried the noun into English.","exampleCN":"法语把这个名词带入英语。"},{"word":"account","structure":"English noun and verb","meaning":"a ledger; to explain","meaningCN":"账目；说明","example":"The noun keeps both money and explanation senses.","exampleCN":"名词兼有金钱与说明两义。"},{"word":"take into account","structure":"verb + preposition + noun, fixed phrase","meaning":"to include as a factor","meaningCN":"把……考虑在内","example":"The frame fixes the factor after the noun.","exampleCN":"框架把因素固定在名词之后。"}],"latinEntries":[{"word":"putare","structure":"putare, puto, putavi, putatum (verb, first conjugation)","meaning":"to think; reckon","meaningCN":"思量；计算"},{"word":"computare","structure":"computare, computo, computavi, computatum (com- + putare)","meaning":"to reckon together","meaningCN":"合起来计算"}],"derivatives":[{"word":"take","pos":"v.","zh":"拿；取"},{"word":"account","pos":"n./v.","zh":"账目；说明"},{"word":"accountable","pos":"adj.","zh":"负有责任的"},{"word":"accounting","pos":"n.","zh":"会计"},{"word":"account for","pos":"v. phr.","zh":"解释；占"}]}},{"word":"take place","ipa_uk":"/teɪk pleɪs/","ipa_us":"/teɪk pleɪs/","definition_zh":"发生；举行；进行（多指按计划或安排在特定时间地点出现的事）","definition_en":"to happen, especially in a planned way and at a stated time or place","core_image":"礼堂门口挂着一块写明日期的牌子，椅子一排排摆好，门口站着迎宾的人","scene":"礼堂门口的牌子写明日期，椅子一排排摆好，迎宾的人站在门边。The ceremony will take place in the main hall on Friday.","sceneCN":"这里指典礼按安排在礼堂举行（第 2 个义项：举行活动）；句意为典礼将于星期五在正厅举行。图中可辨识物件：礼堂门、日期牌、椅子、迎宾者。","pos":[{"tag":"v. phr.","zh":"动词短语：发生；举行"},{"tag":"idiom","zh":"固定搭配：按安排出现"}],"collocations":[{"phrase":"take place in the main hall","zh":"在主厅举行"},{"phrase":"take place on Friday","zh":"在星期五举行"},{"phrase":"take place as planned","zh":"按计划进行"},{"phrase":"take place behind closed doors","zh":"闭门进行"},{"phrase":"take place over several years","zh":"历时数年发生"},{"phrase":"take place at short notice","zh":"临时举行"}],"forms":[{"label":"原形","form":"take place"},{"label":"第三人称单数","form":"takes place"},{"label":"过去式","form":"took place"},{"label":"过去分词","form":"taken place"},{"label":"现在分词","form":"taking place"},{"label":"情态结构","form":"will take place"}],"derivatives":[{"word":"take","pos":"v.","zh":"由古诺斯语「抓取」动词而来，义为「拿；取」"},{"word":"place","pos":"n./v.","zh":"由古法语「广场、位置」一词而来，义为「地方；放置」"},{"word":"placement","pos":"n.","zh":"由该动词加名词尾构成，义为「放置；安置」"},{"word":"displace","pos":"v.","zh":"由表示「离开」的前缀加该动词构成，义为「取代；使移位」"},{"word":"replace","pos":"v.","zh":"由表示「回、再」的前缀加该动词构成，义为「替换」"}],"senses":[{"no":"01","title":"An event happening as arranged","titleCN":"按安排发生","definition":"used when an event happens according to a plan or timetable","definitionCN":"事件按计划或时间表出现","example":"The talks will take place only if both sides agree.","exampleCN":"会谈只有在双方同意后才会举行。","why":"The verb keeps a faint sense of taking up a slot in a schedule, which is why plans fit best.","whyCN":"动词隐约保留「占去一个日程位置」之意，因此最合计划性事件。"},{"no":"02","title":"A ceremony or formal event","titleCN":"举行典礼或正式活动","definition":"used for ceremonies, meetings and official occasions","definitionCN":"用于典礼、会议与正式场合","example":"The ceremony will take place in the main hall on Friday.","exampleCN":"典礼将于星期五在正厅举行。","why":"Formal occasions are announced in advance, so this sense dominates in notices and programmes.","whyCN":"正式场合都会提前公布，因此这一义项在通知与节目单里最常见。"},{"no":"03","title":"A process being carried out","titleCN":"进行某项过程","definition":"used for experiments, negotiations or surveys in progress","definitionCN":"用于正在进行的实验、谈判或调查","example":"The trials can take place at three separate sites.","exampleCN":"试验可在三个不同地点进行。","why":"A process occupies time rather than a moment, and the phrase fits that span.","whyCN":"过程占据一段时间而非一个瞬间，短语正好配合这种跨度。"},{"no":"04","title":"A change occurring","titleCN":"出现变化","definition":"used when a change happens gradually rather than all at once","definitionCN":"变化逐渐出现而非一次完成时使用","example":"These changes take place over several years.","exampleCN":"这些变化历时数年才发生。","why":"With slow change the event is spread out, so the phrase behaves like a process verb.","whyCN":"缓慢变化中事件被拉长，短语便表现得像过程动词。"},{"no":"05","title":"Happening at a place","titleCN":"发生在某地","definition":"used with a place phrase to fix the location of an event","definitionCN":"与地点短语连用，确定事件发生的位置","example":"The meeting can take place at the old warehouse.","exampleCN":"会议可以在旧仓库举行。","why":"Place is part of the name of the phrase, so a location phrase follows naturally.","whyCN":"「位置」本就写在短语里，地点短语随之而来十分自然。"},{"no":"06","title":"Happening at a time","titleCN":"发生在某时","definition":"used with a time phrase to fix when an event occurs","definitionCN":"与时间短语连用，确定事件出现的时间","example":"The inspection will take place on the first Monday of each month.","exampleCN":"检查将在每月第一个星期一进行。","why":"Scheduled time is the clearest signal that this verb, not happen, is wanted.","whyCN":"明确的时间安排是选用这个动词而非「碰巧发生」的最清晰信号。"},{"no":"07","title":"A scene set in a story","titleCN":"文学作品中的场景设定","definition":"used to state where the action of a story is set","definitionCN":"说明故事中的情节设定在何处","example":"The final scene can take place in a railway station.","exampleCN":"最后一幕可以设定在火车站。","why":"Fiction borrows the scheduling sense: the author places a scene as a planner places an event.","whyCN":"小说借用日程义：作者安排场景，如同规划者安排事件。"},{"no":"08","title":"Events in academic narrative","titleCN":"学术叙述中的事件时点","definition":"used in reports and histories to date an event neutrally","definitionCN":"在报告与历史叙述中中性标明事件时点","example":"The survey will take place before the harvest.","exampleCN":"调查将在收获前进行。","why":"Research writing avoids the accidental colour of happen, so this frame keeps the account neutral.","whyCN":"研究写作避免「碰巧」色彩，这一框架让叙述保持中性。"}],"etymology":{"intro":{"en":"Take comes from Old Norse taka, to grasp, which replaced the older English verb in the medieval period. Place comes through Old French from Latin platea, a broad street, itself from Greek plateia hodos, a wide way. The phrase is often described as modelled on French avoir lieu; that account is generally accepted but not proved. Its first date is approximate.","cn":"take 来自古诺斯语 taka「抓取」，在中古英语时期取代本族动词。place 经古法语来自拉丁语 platea「宽街」，后者出自希腊语「宽的道路」。一般认为该短语仿自法语中意义相同的说法，此说广为接受但未获确证；首见年代为约数。"},"items":[{"era":"OLD NORSE TAKA","en":"Taka meant to grasp and slowly displaced the native verb.","cn":"taka 意为「抓取」，逐渐取代了本族动词。"},{"era":"LATIN PLATEA","en":"Platea meant a broad street and gives plaza and place.","cn":"platea 意为「宽街」，也是 plaza 与 place 的来源。"},{"era":"GREEK PLATEIA HODOS","en":"The Greek phrase meant a wide way, the source of the Latin word.","cn":"希腊语短语意为「宽的道路」，是拉丁词的来源。"},{"era":"OLD FRENCH PLACE","en":"Old French place meant an open space or a position.","cn":"古法语 place 指空地或位置。"},{"era":"POSSIBLE FRENCH MODEL","en":"The English phrase is generally thought to follow a French phrase with the same sense, though the model is not proved.","cn":"英语短语一般认为仿自法语中意义相同的说法，但此说未获确证。"},{"era":"ENGLISH PHRASE","en":"The frame settled in modern English; first dates are approximate.","cn":"这一框架在近代英语中定型，首见年代为约数。"}]},"similar":{"note":{"en":"The first group shares the verb or the noun and changes one element; the second group holds the three common verbs of occurrence.","cn":"第一组共用该动词或名词而更换一个成分；第二组是三个常见的「发生」动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"take the place of","ipa":"/teɪk ðə pleɪs ɒv/","tag":"replace","definition":"The article and of turn it into a verb of substitution, not occurrence.","definitionCN":"加冠词与介词后，它变成「取代」而非「发生」。"},{"word":"take part","ipa":"/teɪk pɑːt/","tag":"join in","definition":"It means to participate, with no reference to an event happening.","definitionCN":"意为参与，与事件发生无关。"},{"word":"take up","ipa":"/teɪk ʌp/","tag":"occupy or begin","definition":"It means to fill space or time, or to start an activity.","definitionCN":"意为占去空间或时间，或开始某项活动。"},{"word":"take place","ipa":"/teɪk pleɪs/","tag":"the phrase itself","definition":"Note that place is not a venue here but the fact of an event occupying a slot.","definitionCN":"注意此处「place」不是场地，而是事件占去一个位置这一事实。"}]},{"heading":"NEAR MEANING","entries":[{"word":"happen","ipa":"/ˈhæpən/","tag":"unplanned occurrence","definition":"It suits accidental or unplanned events and is the everyday choice.","definitionCN":"它适合偶然或未计划的事件，是日常首选。"},{"word":"occur","ipa":"/əˈkɜː/","tag":"formal or non-accidental","definition":"It is more formal and often used of events that are not random.","definitionCN":"它更正式，常用于非随机的事件。"},{"word":"go on","ipa":"/ɡəʊ ɒn/","tag":"ongoing activity","definition":"It stresses that something is continuing rather than that it starts.","definitionCN":"它强调某事在持续，而非开始。"},{"word":"be held","ipa":"/biː held/","tag":"formal scheduling","definition":"It is the passive used in notices for meetings and ceremonies.","definitionCN":"它是通知里用于会议与典礼的被动说法。"}]}]},"mnemonics":{"normalIntro":{"en":"The normal associations use the real Norse verb, the real plaza word and the planned-versus-accidental contrast.","cn":"正常联想使用真实的北欧语动词、真实的「广场」词源以及「安排」与「偶然」的对比。"},"normal":[{"en":"A place is an open square, so an event takes place by taking up a spot.","cn":"place 原指空地，事件「发生」就是占去一个位置。"},{"en":"The phrase suits plans, timetables and ceremonies.","cn":"这个短语适合计划、时间表与典礼。"},{"en":"Happen is for accidents; occur is formal; this one is scheduled.","cn":"「happen」管偶然，「occur」偏正式，本短语管安排。"},{"en":"Place and time phrases follow naturally because place is in the name.","cn":"地点与时间短语随之而来，因为「位置」就在短语名里。"},{"en":"Take the place of is a different phrase meaning replace.","cn":"加冠词与 of 后是另一短语，意为「取代」。"}],"abstract":[{"en":"Like a chair set out in a hall before the guests arrive.","cn":"像客人到来之前摆好的椅子。"},{"en":"Like a slot filled on a calendar, the event fitting exactly into its square.","cn":"像日历上的空格被填满，事件正好嵌进那一格。"},{"en":"Like a stage lit before the curtain rises.","cn":"像幕布升起前先亮起的舞台。"}]},"examples":[{"en":"The ceremony will take place in the main hall on Friday.","cn":"典礼将于星期五在正厅举行。"},{"en":"The interviews can take place at the applicant's home.","cn":"面试可以在申请人家里进行。"},{"en":"These changes take place over several years.","cn":"这些变化历时数年才发生。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「泰克 普雷斯」——礼堂门口挂好日期牌，椅子一排排摆好：发生；举行","word":"take place"},"root":"take 来自古诺斯语 taka「抓取」，中古英语时期取代本族动词；place 经古法语来自拉丁语 platea「宽街」，出自希腊语「宽的道路」。该短语一般认为仿自法语中意义相同的说法，此说未获确证，首见年代为约数。","sensesIntro":{"en":"Eight senses split by what is scheduled: an event, a ceremony, a process, a slow change, a location, a date, a fictional scene and a neutral report.","cn":"八个义项按被安排的对象区分：事件、典礼、过程、缓慢变化、地点、日期、虚构场景、中性报告。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hall with a date board, rows of chairs and a host at the door.","cn":"核心意象：礼堂门口写着日期，椅子成排，迎宾者站在门边。"},"chain":["TAKE A SPOT","NAME THE OCCASION","NAME THE PROCESS","SPREAD OVER TIME","FIX THE PLACE","FIX THE DATE"],"branches":[{"senses":"01 · 02","en":"THE OCCASION: an event or ceremony fills a slot in the timetable.","cn":"场合：事件或典礼占去日程中的一格。"},{"senses":"03 · 04","en":"THE PROCESS: trials and slow changes stretch the event across time.","cn":"过程：试验与缓慢变化把事件拉长。"},{"senses":"05 · 06","en":"THE ANCHORS: place and date phrases fix where and when.","cn":"锚点：地点与时间短语定住何处何时。"},{"senses":"07","en":"THE SCENE: fiction places an action as a planner places an event.","cn":"场景：小说安排情节，如同规划者安排事件。"},{"senses":"08","en":"THE REPORT: neutral dating keeps academic accounts free of accident.","cn":"报告：中性纪年让学术叙述不带偶然色彩。"}]},"affixes":{"intro":{"en":"The phrase joins a Norse verb of grasping to a word that came from a Greek term for a wide street.","cn":"短语把北欧语「抓取」动词与一个出自希腊语「宽街」的词组合起来。"},"latinIntro":{"en":"The Latin element is platea, a broad street, from Greek plateia hodos; take has a Norse source.","cn":"拉丁语成分是 platea「宽街」，出自希腊语；take 来自北欧语。"},"items":[{"word":"taka","structure":"Old Norse verb","meaning":"to grasp; take","meaningCN":"抓取；拿","example":"The Norse verb displaced the native one.","exampleCN":"这个北欧语动词取代了本族词。"},{"word":"take","structure":"English verb","meaning":"to grasp; to occupy","meaningCN":"拿；占","example":"The verb supplies the action in the phrase.","exampleCN":"动词为短语提供动作。"},{"word":"platea","structure":"Latin noun, first declension","meaning":"broad street","meaningCN":"宽街","example":"The Latin word gives place and plaza.","exampleCN":"这个拉丁词给出「地方」与「广场」。"},{"word":"plateia hodos","structure":"Greek phrase","meaning":"wide way","meaningCN":"宽的道路","example":"Greek supplied the Latin word.","exampleCN":"希腊语提供了这个拉丁词。"},{"word":"place","structure":"English noun and verb","meaning":"spot; to put","meaningCN":"地方；放置","example":"The noun names the slot an event occupies.","exampleCN":"名词指事件占去的位置。"},{"word":"placement","structure":"place + -ment","meaning":"the act of putting","meaningCN":"放置；安置","example":"The noun is regular and common in work contexts.","exampleCN":"这个名词规则，多用于工作场景。"},{"word":"replace","structure":"re- + place","meaning":"to put back; substitute","meaningCN":"替换","example":"The prefix adds the sense of putting back.","exampleCN":"前缀加上「放回」之义。"},{"word":"take place","structure":"verb + noun, fixed phrase","meaning":"to happen as arranged","meaningCN":"发生；举行","example":"The phrase treats occurrence as occupying a spot.","exampleCN":"短语把「发生」当作占去一个位置。"}],"latinEntries":[{"word":"platea","structure":"platea, -ae (noun, first declension)","meaning":"broad street","meaningCN":"宽街"}],"derivatives":[{"word":"take","pos":"v.","zh":"拿；取"},{"word":"place","pos":"n./v.","zh":"地方；放置"},{"word":"placement","pos":"n.","zh":"放置；安置"},{"word":"replace","pos":"v.","zh":"替换"},{"word":"displace","pos":"v.","zh":"取代；使移位"}]}},{"word":"tend to","ipa_uk":"/ˈtend tuː/","ipa_us":"/ˈtend tuː/","definition_zh":"倾向于；往往会；易于（多指一般趋势而非某一次具体行为）","definition_en":"to be likely to do something or to have a general tendency towards a state or behaviour","core_image":"一株幼苗的茎一天天弯向窗口的亮处，绳子被慢慢拉向那边","scene":"窗台上的一株幼苗，茎一天天弯向有光的一侧。Young shoots tend to bend towards the light.","sceneCN":"这里指幼苗往往朝光的方向弯（第 2 个义项：往往出现的一般倾向）；句意为幼嫩的枝条往往会朝光弯曲。图中可辨识物件：窗台、幼苗、光影、弯曲的茎。","pos":[{"tag":"v. phr.","zh":"动词短语：倾向于；往往会"},{"tag":"idiom","zh":"固定搭配：一般趋势"}],"collocations":[{"phrase":"tend to increase","zh":"往往上升"},{"phrase":"tend to be","zh":"往往是"},{"phrase":"tend to agree","zh":"倾向于同意"},{"phrase":"tend to occur","zh":"往往发生"},{"phrase":"tend to the sick","zh":"照料病人"},{"phrase":"tend to the needs of","zh":"照应……的需求"}],"forms":[{"label":"原形","form":"tend to"},{"label":"第三人称单数","form":"tends to"},{"label":"过去式","form":"tended to"},{"label":"过去分词","form":"tended to"},{"label":"现在分词","form":"tending to"},{"label":"否定形","form":"do not tend to"}],"derivatives":[{"word":"tend","pos":"v.","zh":"由拉丁语「伸展」动词经法语而来，义为「倾向；照料」"},{"word":"tendency","pos":"n.","zh":"由该动词加名词尾构成，义为「倾向；趋势」"},{"word":"tendentious","pos":"adj.","zh":"由该动词的拉丁分词加形容词尾构成，义为「有倾向性的」"},{"word":"attention","pos":"n.","zh":"由同根的另一动词而来，义为「注意」"},{"word":"attend","pos":"v.","zh":"由同根动词而来，义为「出席；照料」"}],"senses":[{"no":"01","title":"A habitual inclination","titleCN":"习惯性的倾向","definition":"used for a repeated habit or preference","definitionCN":"用于反复出现的习惯或偏好","example":"Farmers tend to start early in the dry season.","exampleCN":"旱季里农场主往往很早就开工。","why":"The verb points a weight towards one side; habit is many small pushes in the same direction.","whyCN":"动词把重量偏向一侧；习惯就是许多同方向的小推。"},{"no":"02","title":"A general trend","titleCN":"一般趋势","definition":"used for a pattern that holds in general, not in every case","definitionCN":"用于总体上成立、并非每例都成立的规律","example":"Young shoots tend to bend towards the light.","exampleCN":"幼嫩的枝条往往会朝光弯曲。","why":"The frame is deliberately loose: it allows exceptions without denying the pattern.","whyCN":"这一框架刻意留松：允许例外，又不否认规律。"},{"no":"03","title":"A liability to something bad","titleCN":"易于出现不良后果","definition":"used when something is likely to suffer a problem","definitionCN":"某物容易出现某种问题时使用","example":"Older machines tend to fail in cold weather.","exampleCN":"较旧的机器在寒冷天气里容易出故障。","why":"With bad outcomes, the inclination reads as a weakness in the thing itself.","whyCN":"后果不良时，这种倾向读作事物本身的弱点。"},{"no":"04","title":"A statistical tendency","titleCN":"统计上的趋势","definition":"used in data writing to describe a pattern across many cases","definitionCN":"在数据写作中描述跨多个样本的规律","example":"Prices tend to rise before a holiday.","exampleCN":"节假日前价格往往上升。","why":"Statistics uses the frame because it states a tendency without claiming a law.","whyCN":"统计学用这一框架，因为只陈述趋势而不宣称定律。"},{"no":"05","title":"To care for someone","titleCN":"照料、看护","definition":"to look after a person or animal, from a separate verb line","definitionCN":"照看人或动物，来自另一条动词来源","example":"Nurses tend to the patients through the night.","exampleCN":"护士整夜照看病人。","why":"This sense comes from a different Latin verb and takes a person as its object, not an action.","whyCN":"这一义项出自另一拉丁动词，宾语是人而非动作。"},{"no":"06","title":"To lean towards a view","titleCN":"倾向于某种看法","definition":"used when someone is likely to hold an opinion","definitionCN":"某人较可能持某种看法时使用","example":"Reviewers tend to favour shorter papers.","exampleCN":"评审者往往偏爱较短的论文。","why":"The object here is a judgement, so the frame reports a bias rather than a fact.","whyCN":"这里宾语是判断，因此框架报告的是偏向而非事实。"},{"no":"07","title":"A direction in a chart","titleCN":"图表上的走势","definition":"used to describe the direction in which a line or figure moves","definitionCN":"描述曲线或数字移动的方向","example":"The two curves tend to converge after week six.","exampleCN":"两条曲线在第六周后往往趋于汇合。","why":"A chart line is a weight falling forward, the oldest image of the verb.","whyCN":"图表曲线就是重量向前落，正是这个动词最古老的意象。"},{"no":"08","title":"The older sense of attending","titleCN":"照应、侍候（较旧用法）","definition":"an older sense of waiting upon or looking after, still found in formal prose","definitionCN":"较旧的「侍候、照应」义，仍见于正式文字","example":"Staff tend to the needs of every guest.","exampleCN":"员工照应每位客人的需求。","why":"This surviving sense is the one that shares a root with attention and attend.","whyCN":"这一留存的义项与「注意」「出席」共享词根。"}],"etymology":{"intro":{"en":"Tend in the sense of incline comes from Latin tendere, to stretch, through Old French tendre. The sense of caring for someone comes from a different line, Old French attendre, from Latin attendere, to stretch towards. The two senses are homonyms in modern English, not one history. The phrase is modern and its first date is approximate.","cn":"表示「倾向」的 tend 经古法语来自拉丁语 tendere「伸展」。表示「照料」的 tend 来自另一条线：古法语 attendre，出自拉丁语 attendere「朝……伸展」。现代英语中两者是同形异源，并非同一历史。短语属近代，首见年代为约数。"},"items":[{"era":"LATIN TENDERE","en":"Tendere means to stretch or point towards, the source of tendency and tension.","cn":"tendere 意为「伸展、指向」，是 tendency 与 tension 的来源。"},{"era":"OLD FRENCH TENDRE","en":"Tendre carried the stretching verb into English with the sense of inclining.","cn":"古法语 tendre 把这个「伸展」动词带入英语，带「倾向」义。"},{"era":"LATIN ATTENDERE","en":"Attendere, ad- plus tendere, means to stretch one's mind towards something.","cn":"attendere 由 ad- 加 tendere 构成，意为「把心思朝某物伸展」。"},{"era":"OLD FRENCH ATTENDRE","en":"Attendre gave English the caring sense of tend, as in tending the sick.","cn":"古法语 attendre 给出「照料」义，如照看病人。"},{"era":"ENGLISH HOMONYMS","en":"The two verbs look alike but descend from different French forms.","cn":"两个动词形似，却出自不同的法语形式。"},{"era":"ENGLISH PHRASE","en":"The frame is modern; first dates are approximate.","cn":"这一框架属近代用法，首见年代为约数。"}]},"similar":{"note":{"en":"The first group shares the verb and changes the particle; the second group holds other ways of stating a tendency.","cn":"第一组共用该动词而更换介词；第二组是其他表述倾向的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"tend toward","ipa":"/tend təˈwɔːd/","tag":"direction, often a state","definition":"It points at a state or quality rather than an action.","definitionCN":"它指向状态或性质，而非动作。"},{"word":"tend","ipa":"/tend/","tag":"care for","definition":"Without a particle it often means to look after, a separate sense.","definitionCN":"不带介词时多指照料，属另一义项。"},{"word":"attend to","ipa":"/əˈtend tuː/","tag":"deal with","definition":"It means to handle a task or a patient, with the same root but a different verb.","definitionCN":"意为处理事务或照看病人，词根相同但动词不同。"},{"word":"tendency","ipa":"/ˈtendənsi/","tag":"the noun","definition":"The noun states the inclination itself, with no verb after it.","definitionCN":"名词直接陈述倾向，后面不接动词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"be inclined to","ipa":"/biː ɪnˈklaɪnd tuː/","tag":"leaning of will","definition":"It stresses a personal or deliberate leaning more than a statistical pattern.","definitionCN":"它更强调个人或有意的偏向，而非统计规律。"},{"word":"be likely to","ipa":"/biː ˈlaɪkli tuː/","tag":"probability","definition":"It states probability plain and simple, with no image of direction.","definitionCN":"它直白陈述概率，不带方向意象。"},{"word":"usually","ipa":"/ˈjuːʒuəli/","tag":"frequency adverb","definition":"It marks frequency rather than an inner inclination.","definitionCN":"它标记频率，而非内在倾向。"},{"word":"lean towards","ipa":"/liːn təˈwɔːdz/","tag":"preference","definition":"It pictures an actual tilt in a direction, common in decisions.","definitionCN":"它画出真实的倾斜，多见于决策语境。"}]}]},"mnemonics":{"normalIntro":{"en":"The normal associations use the real Latin stretch, the two separate verb lines and the tendency-probability split.","cn":"正常联想使用真实的拉丁语「伸展」、两条独立动词来源以及「倾向」与「概率」的分工。"},"normal":[{"en":"Tendere is to stretch, so a tendency is a weight pulling one way.","cn":"词根意为「伸展」，倾向就是一端被拉过去。"},{"en":"The caring sense comes from another verb line, attend.","cn":"「照料」义出自另一动词线，与「注意」同根。"},{"en":"The phrase takes an action, not a person, when it means inclination.","cn":"表倾向时后接动作，而非人。"},{"en":"It allows exceptions, which is why research writing likes it.","cn":"它允许例外，因此研究写作偏爱它。"},{"en":"Be inclined to stresses will; be likely to stresses probability.","cn":"一个强调意愿，一个强调概率。"}],"abstract":[{"en":"Like a seedling bending towards the window day by day.","cn":"像幼苗一天天弯向窗口。"},{"en":"Like a weight on a string pulling slowly to one side.","cn":"像绳上的重物慢慢被拉向一侧。"},{"en":"Like a river that always finds the lower ground.","cn":"像河流总是找到低处。"}]},"examples":[{"en":"Companies tend to cut training first when money is tight.","cn":"资金紧张时，公司往往先削减培训。"},{"en":"These metals tend to corrode near salt water.","cn":"这些金属在海水附近往往腐蚀。"},{"en":"Volunteers tend to the injured during the night shift.","cn":"志愿者在夜班期间照看伤者。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「坦德 图」——窗台上的幼苗一天天弯向有光的一侧：倾向于；往往会","word":"tend to"},"root":"表「倾向」的 tend 经古法语来自拉丁语 tendere「伸展」；表「照料」的 tend 来自古法语 attendre，出自拉丁语 attendere「朝……伸展」。两条线同形异源。这一框架属近代用法，首见年代为约数。","sensesIntro":{"en":"Eight senses split between inclination and care: habit, general trend, liability, statistics, looking after someone, opinion, chart direction and attending to needs.","cn":"八个义项分属「倾向」与「照料」两侧：习惯、一般趋势、易发性、统计、看护、看法、图表走势、照应需求。"},"semanticMap":{"core":{"en":"CORE IMAGE: a seedling bending towards the lit side of a window day after day.","cn":"核心意象：窗台上的幼苗一天天弯向有光的一侧。"},"chain":["STRETCH TOWARDS","POINT ONE WAY","REPEAT AS HABIT","SHOW AS TREND","LEAN IN OPINION","CARE FOR A PERSON"],"branches":[{"senses":"01 · 02","en":"THE WEIGHT: habit and general trend are the same pull repeated.","cn":"重量：习惯与一般趋势是同一拉力反复出现。"},{"senses":"03 · 04","en":"THE RISK AND THE DATA: liability and statistics report patterns, not laws.","cn":"风险与数据：易发性与统计报告规律，而非定律。"},{"senses":"05 · 08","en":"THE CARE: the homonym from attend takes a person or a need.","cn":"照料：来自「注意」的同形词接人或需求。"},{"senses":"06","en":"THE VIEW: reviewers lean one way, so the frame reports a bias.","cn":"看法：评审者偏向一侧，框架报告偏向。"},{"senses":"07","en":"THE CHART: a curve falling forward repeats the oldest image.","cn":"图表：曲线向前落，重复最古老的意象。"}]},"affixes":{"intro":{"en":"Two Latin lines meet here: tendere, to stretch, and attendere, to stretch towards; only the first gives the inclination sense.","cn":"此处汇合两条拉丁线：tendere「伸展」与 attendere「朝……伸展」；只有前者给出「倾向」义。"},"latinIntro":{"en":"The Latin etyma are tendere, to stretch, and attendere, ad- plus tendere.","cn":"拉丁语词源是 tendere「伸展」与 attendere（ad- 加 tendere）。"},"items":[{"word":"tendere","structure":"Latin verb, third conjugation","meaning":"to stretch; point","meaningCN":"伸展；指向","example":"The verb gives tendency, tension and tendon.","exampleCN":"这个动词给出「倾向」「张力」「腱」诸词。"},{"word":"tendre","structure":"Old French verb","meaning":"to incline","meaningCN":"倾向","example":"French carried the verb into English.","exampleCN":"法语把这个动词带入英语。"},{"word":"tend","structure":"English verb","meaning":"to incline","meaningCN":"倾向","example":"The inclination sense takes an action after to.","exampleCN":"倾向义在介词后接动作。"},{"word":"tendency","structure":"tend + -ency","meaning":"an inclination","meaningCN":"倾向；趋势","example":"The noun names the pull itself.","exampleCN":"名词命名这股拉力本身。"},{"word":"attendere","structure":"ad- + tendere, Latin verb","meaning":"to stretch towards; heed","meaningCN":"朝……伸展；留心","example":"The compound verb supplies the caring sense.","exampleCN":"复合动词提供「照料」义。"},{"word":"attendre","structure":"Old French verb","meaning":"to wait for; care for","meaningCN":"等待；照料","example":"French gives the second English homonym.","exampleCN":"法语给出第二个英语同形词。"},{"word":"attend","structure":"English verb","meaning":"to be present; care for","meaningCN":"出席；照料","example":"The verb shares a root with attention.","exampleCN":"这个动词与「注意」同根。"},{"word":"tend to","structure":"verb + preposition, fixed phrase","meaning":"to be likely to","meaningCN":"倾向于","example":"The frame fixes the action after the preposition.","exampleCN":"框架把动作固定在介词后。"}],"latinEntries":[{"word":"tendere","structure":"tendere, tendo, tetendi, tensum (verb, third conjugation)","meaning":"to stretch","meaningCN":"伸展"},{"word":"attendere","structure":"attendere, attendo, attendi, attentum (ad- + tendere)","meaning":"to stretch towards","meaningCN":"朝……伸展"}],"derivatives":[{"word":"tend","pos":"v.","zh":"倾向；照料"},{"word":"tendency","pos":"n.","zh":"倾向；趋势"},{"word":"tendentious","pos":"adj.","zh":"有倾向性的"},{"word":"attention","pos":"n.","zh":"注意"},{"word":"attend","pos":"v.","zh":"出席；照料"}]}},{"word":"be subject to","ipa_uk":"/biː ˈsʌbdʒɪkt tuː/","ipa_us":"/biː ˈsʌbdʒɪkt tuː/","definition_zh":"受制于；须遵守；易遭受；须经（批准或条件），表示处于某种约束或可能之下","definition_en":"to be governed by a rule, exposed to a risk, or conditional upon something else","core_image":"一块木牌挂在铁链下，牌上压着一枚公章，链子的另一端钉在墙上","scene":"墙边一块木牌被铁链拴住，牌上盖着公章，链头钉在墙上。All such exports will be subject to a licence.","sceneCN":"这里指这类出口须经许可（第 3 个义项：须经批准）；句意为所有这类出口都将受许可证约束。图中可辨识物件：木牌、铁链、公章、墙面。","pos":[{"tag":"adj. phr.","zh":"形容词短语：受制于；易遭受"},{"tag":"idiom","zh":"固定搭配：以……为条件"}],"collocations":[{"phrase":"be subject to change","zh":"可能会有变动"},{"phrase":"be subject to approval","zh":"须经批准"},{"phrase":"be subject to inspection","zh":"须接受检查"},{"phrase":"be subject to strict rules","zh":"受严格规则约束"},{"phrase":"be subject to damage","zh":"易受损害"},{"phrase":"be subject to confirmation","zh":"有待确认"}],"forms":[{"label":"原形","form":"be subject to"},{"label":"现在时","form":"is subject to"},{"label":"过去时","form":"was subject to"},{"label":"情态结构","form":"may be subject to"},{"label":"名词","form":"subject"},{"label":"被动动作形","form":"be subjected to"}],"derivatives":[{"word":"subject","pos":"n./adj.","zh":"由拉丁语「置于其下」的分词而来，义为「主题；受制于」"},{"word":"subjection","pos":"n.","zh":"由该分词加名词尾构成，义为「征服；服从」"},{"word":"subjective","pos":"adj.","zh":"由该词干加形容词尾构成，义为「主观的」"},{"word":"subject matter","pos":"n.","zh":"由该名词加「内容」构成的复合词，义为「题材」"},{"word":"be subjected to","pos":"v. phr.","zh":"由该分词加被动结构构成，义为「被施加；遭受」"}],"senses":[{"no":"01","title":"Bound by a rule","titleCN":"受规则约束","definition":"to be required to obey a law or regulation","definitionCN":"必须遵守法律或规章","example":"All such exports will be subject to a licence.","exampleCN":"所有这类出口都将受许可证约束。","why":"The image is of something placed under an authority, so the rule sits above the thing and governs it.","whyCN":"意象是把某物置于权威之下，规则因此高悬其上并管着它。"},{"no":"02","title":"Exposed to harm","titleCN":"易遭受损害","definition":"to be open to damage, disease or loss","definitionCN":"暴露在损害、疾病或损失之下","example":"These crops can be subject to frost damage.","exampleCN":"这些作物可能遭受霜冻损害。","why":"Here the thing hangs under a risk rather than under a rule, but the grammar is the same.","whyCN":"这里悬在风险而非规则之下，但语法结构相同。"},{"no":"03","title":"Requiring approval","titleCN":"须经批准","definition":"to need permission or a formal step before it can proceed","definitionCN":"必须先取得许可或完成正式程序","example":"Any change to the design must be subject to review.","exampleCN":"设计的任何改动都必须经过评审。","why":"Approval is a gate placed above the thing, so nothing moves until it opens.","whyCN":"批准是设在上方的一道门，门不开就动不了。"},{"no":"04","title":"Conditional on something","titleCN":"以……为条件","definition":"to depend on a condition that may alter it","definitionCN":"取决于某项可能改变它的条件","example":"Prices may be subject to change without notice.","exampleCN":"价格可能变动，恕不另行通知。","why":"A condition is written into the frame, so the statement is true only while the condition holds.","whyCN":"条件被写进框架，因此陈述只在条件成立时有效。"},{"no":"05","title":"Affected by a force","titleCN":"受某种影响","definition":"to be liable to be affected by fluctuations or pressure","definitionCN":"易受波动或压力的影响","example":"The results can be subject to seasonal swings.","exampleCN":"结果可能受季节波动影响。","why":"An external force pushes the thing, and the frame records that it cannot resist.","whyCN":"外力推动某物，框架记录的是它无法抗拒。"},{"no":"06","title":"Under a jurisdiction","titleCN":"受……管辖","definition":"to fall under the legal or political authority of a body","definitionCN":"处于某机构的法律或政治管辖之下","example":"The islands will be subject to local law.","exampleCN":"这些岛屿将受当地法律管辖。","why":"Jurisdiction is authority over a place, the same image of standing under applied to territory.","whyCN":"管辖是对一片地方的权威，仍是「处于其下」的意象用于领土。"},{"no":"07","title":"Awaiting confirmation","titleCN":"有待确认","definition":"used when a figure or plan is not yet final","definitionCN":"数字或计划尚未最终确定时使用","example":"The dates may be subject to confirmation.","exampleCN":"日期可能还有待确认。","why":"This sense is a polite hedge: the thing is true for now but can still move.","whyCN":"这一义项是礼貌的留白：目前成立，但仍可能变动。"},{"no":"08","title":"Under someone's power","titleCN":"受某人支配","definition":"to be controlled by a person or an authority","definitionCN":"处于某人或某权威的控制之下","example":"No official can be subject to pressure from a single firm.","exampleCN":"任何官员都不应受单一公司的压力支配。","why":"Power is the personal form of the same relation: one party stands above another.","whyCN":"权力是同一关系的个人形式：一方高居另一方之上。"}],"etymology":{"intro":{"en":"Subject comes from Latin subiectus, the past participle of subicere, to throw under, from sub-, under, and iacere, to throw. The adjective use with to is a later English development; its first date is approximate.","cn":"subject 源自拉丁语 subiectus，是 subicere 的过去分词，后者由 sub-「在下」与 iacere「投掷」构成，意为「置于其下」。与介词连用的形容词用法是较晚的英语发展，首见年代为约数。"},"items":[{"era":"LATIN IACERE","en":"Iacere means to throw and also underlies project, reject and inject.","cn":"iacere 意为「投掷」，也是 project、reject、inject 的根基。"},{"era":"LATIN SUB-","en":"Sub- means under, so the compound pictures something thrown beneath.","cn":"sub- 意为「在下」，复合词画出某物被投到下面。"},{"era":"LATIN SUBICERE","en":"Subicere means to place under, to submit or to subject.","cn":"subicere 意为「置于其下、使服从」。"},{"era":"LATIN SUBIECTUS","en":"The participle names the thing placed under an authority.","cn":"分词指被置于权威之下的东西。"},{"era":"ENGLISH ADJECTIVE USE","en":"English uses subject as noun and adjective; the frame with to marks what governs it.","cn":"英语中该词作名词与形容词；带介词的框架标出支配者。"},{"era":"ENGLISH PHRASE","en":"The fixed frame is modern; first dates are approximate.","cn":"固定框架属近代用法，首见年代为约数。"}]},"similar":{"note":{"en":"The first group looks nearly identical but reverses the direction of the action; the second group holds other ways of stating exposure or condition.","cn":"第一组形近但动作方向相反；第二组是其他表述「暴露」或「条件」的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"be subjected to","ipa":"/biː səbˈdʒektɪd tuː/","tag":"action, not state","definition":"It means someone actively imposes something on the subject; this phrase describes a standing condition.","definitionCN":"它指有人主动把某事施加于对象；本短语只描述持续状态。"},{"word":"subject to","ipa":"/ˈsʌbdʒɪkt tuː/","tag":"without be","definition":"The shorter form works as a modifier, as in prices subject to change.","definitionCN":"较短形式作修饰语，如「可能变动的价格」。"},{"word":"subject","ipa":"/ˈsʌbdʒɪkt/","tag":"noun or adjective","definition":"Alone it means a topic, a person under rule, or a grammatical subject.","definitionCN":"单独使用时指主题、受治者或语法主语。"},{"word":"subjective","ipa":"/səbˈdʒektɪv/","tag":"opinion, not rule","definition":"It describes what belongs to a person's view, from the same root but a different branch.","definitionCN":"它描述属于个人看法的东西，同根但另一分支。"}]},{"heading":"NEAR MEANING","entries":[{"word":"be liable to","ipa":"/biː ˈlaɪəbl tuː/","tag":"exposure to harm","definition":"It stresses legal or physical exposure, close to the risk sense.","definitionCN":"它强调法律或身体上的暴露，接近「风险」义。"},{"word":"be prone to","ipa":"/biː prəʊn tuː/","tag":"inherent tendency","definition":"It stresses an inner tendency to suffer something.","definitionCN":"它强调内在的易发倾向。"},{"word":"be bound by","ipa":"/biː baʊnd baɪ/","tag":"rule or promise","definition":"It names the rule or promise that constrains, without the risk sense.","definitionCN":"它点出约束的规则或承诺，不带风险义。"},{"word":"depend on","ipa":"/dɪˈpend ɒn/","tag":"condition","definition":"It states that one thing follows from another, close to the conditional sense.","definitionCN":"它说明一物取决于另一物，接近「条件」义。"}]}]},"mnemonics":{"normalIntro":{"en":"The normal associations use the real Latin throw, the active-passive contrast and the three core layers.","cn":"正常联想使用真实的拉丁语「投掷」、主动与被动的对比以及三层核心义。"},"normal":[{"en":"Iacere is to throw, so subject means thrown under something.","cn":"词根意为「投掷」，subject 就是被投到某物之下。"},{"en":"The three core layers are rule, risk and approval.","cn":"三层核心义是规则、风险与批准。"},{"en":"Be subjected to is an action; be subject to is a state.","cn":"一个是被施加的动作，一个是持续的状态。"},{"en":"With change and confirmation, the phrase becomes a polite hedge.","cn":"与「变动」「确认」连用时，短语变成礼貌留白。"},{"en":"The same root gives subjective, which is about opinion, not rule.","cn":"同根词「主观的」关乎看法，与规则无关。"}],"abstract":[{"en":"Like a wooden board chained to a wall with a seal stamped on it.","cn":"像木牌被铁链拴在墙上，牌上盖着公章。"},{"en":"Like a boat tied to a dock: it floats, but it cannot drift away.","cn":"像系在码头的船：能浮，却漂不走。"},{"en":"Like a price tag with a small note saying it may change.","cn":"像价签上附一行小字，写着可能变动。"}]},"examples":[{"en":"All such exports will be subject to a licence.","cn":"所有这类出口都将受许可证约束。"},{"en":"These crops can be subject to frost damage.","cn":"这些作物可能遭受霜冻损害。"},{"en":"The dates may be subject to confirmation.","cn":"日期可能还有待确认。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「比 萨布杰克特 图」——木牌被铁链拴在墙上，牌上盖着公章：受制于；须经","word":"be subject to"},"root":"subject 源自拉丁语 subiectus，是 subicere 的过去分词，后者由表示「在下」的前缀与 iacere「投掷」构成；形容词与介词连用的框架是较晚的英语发展，首见年代为约数。","sensesIntro":{"en":"Eight senses split by what governs the subject: a rule, a harm, an approval step, a condition, a force, a jurisdiction, a pending confirmation and a person's power.","cn":"八个义项按支配者区分：规则、伤害、审批环节、条件、外力、司法管辖、待确认、他人权力。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wooden board chained to a wall with an official seal stamped on it.","cn":"核心意象：木牌被铁链拴在墙上，牌上盖着公章。"},"chain":["THROW UNDER","PLACE BENEATH AUTHORITY","OBEY THE RULE","RISK OF HARM","NEED APPROVAL","WAIT FOR CONFIRMATION"],"branches":[{"senses":"01 · 06","en":"THE AUTHORITY: a law or a jurisdiction sits above the subject and governs it.","cn":"权威：法律或辖区高居其上并治理它。"},{"senses":"08","en":"THE PERSONAL POWER: one party stands above another, the same relation in human form.","cn":"人身权力：一方高居另一方之上，是同一关系的人身形式。"},{"senses":"02 · 05","en":"THE EXPOSURE: harm and fluctuation hang over the thing that cannot resist.","cn":"暴露：伤害与波动悬在无力抗拒之物上。"},{"senses":"03","en":"THE GATE: approval must be passed before anything proceeds.","cn":"关口：未过审批就不能推进。"},{"senses":"04 · 07","en":"THE CONDITION: change and confirmation keep the statement provisional.","cn":"条件：变动与确认让陈述保持临时性。"}]},"affixes":{"intro":{"en":"The Latin core is sub-, under, plus iacere, to throw; subicere and its participle subiectus give the English word.","cn":"拉丁核心是 sub-「在下」加 iacere「投掷」；subicere 及其分词提供英语词形。"},"latinIntro":{"en":"The Latin elements are sub-, under, and iacere, to throw; subicere joins them.","cn":"拉丁成分是 sub-「在下」与 iacere「投掷」，subicere 由两者合成。"},"items":[{"word":"sub-","structure":"Latin prefix","meaning":"under; below","meaningCN":"在下；低于","example":"The prefix puts the thing beneath something else.","exampleCN":"前缀把某物置于另一物之下。"},{"word":"iacere","structure":"Latin verb, third conjugation","meaning":"to throw; cast","meaningCN":"投掷；抛","example":"The verb also gives project and reject.","exampleCN":"这个动词也给出「投射」「拒绝」诸词。"},{"word":"subicere","structure":"sub- + iacere, Latin verb","meaning":"to place under; submit","meaningCN":"置于其下；使服从","example":"The compound is the direct source of the English word.","exampleCN":"复合动词是英语词形的直接来源。"},{"word":"subiectus","structure":"Past participle of subicere","meaning":"placed under","meaningCN":"被置于其下的","example":"The participle becomes the English adjective.","exampleCN":"分词成为英语形容词。"},{"word":"subject","structure":"English noun and adjective","meaning":"topic; under authority","meaningCN":"主题；受制的","example":"The word serves as noun, adjective and verb.","exampleCN":"这个词兼作名词、形容词与动词。"},{"word":"subjection","structure":"subject + -ion","meaning":"the state of being under control","meaningCN":"服从；征服","example":"The noun names the state of being placed under.","exampleCN":"名词指被置于其下的状态。"},{"word":"subjective","structure":"subject + -ive","meaning":"belonging to a personal view","meaningCN":"主观的","example":"The branch shifts from rule to opinion.","exampleCN":"这一分支从规则转向看法。"},{"word":"be subject to","structure":"be + adjective + preposition, fixed phrase","meaning":"to be governed or exposed","meaningCN":"受制于；易遭受","example":"The frame fixes the governing thing after the preposition.","exampleCN":"框架把支配者固定在介词后。"}],"latinEntries":[{"word":"iacere","structure":"iacere, iacio, ieci, iactum (verb, third conjugation)","meaning":"to throw","meaningCN":"投掷"},{"word":"subicere","structure":"subicere, subicio, subieci, subiectum (sub- + iacere)","meaning":"to place under","meaningCN":"置于其下"}],"derivatives":[{"word":"subject","pos":"n./adj.","zh":"主题；受制的"},{"word":"subjection","pos":"n.","zh":"服从；征服"},{"word":"subjective","pos":"adj.","zh":"主观的"},{"word":"subject matter","pos":"n.","zh":"题材"},{"word":"be subjected to","pos":"v. phr.","zh":"被施加；遭受"}]}},{"word":"be attributed to","ipa_uk":"/biː əˈtrɪbjuːtɪd tuː/","ipa_us":"/biː əˈtrɪbjuːtɪd tuː/","definition_zh":"被归因于；被认为是……所作、所引起或所属（由观察者把结果归给某方）","definition_en":"to be credited or charged to a particular cause, author or source by an observer","core_image":"一幅无名画作旁放着一张小牌，牌上写着一个名字，指向画框","scene":"展厅里一幅无名画作旁立着小牌，牌上的名字用一条线指向画框。The painting can be attributed to a later copyist.","sceneCN":"这里指这幅画被认定出自较晚的临摹者（第 2 个义项：被认为某人所做）；句意为这幅画可能被归到一位较晚的临摹者名下。图中可辨识物件：画作、标签牌、名字、连线。","pos":[{"tag":"v. phr.","zh":"动词短语（被动）：被归因于"},{"tag":"idiom","zh":"固定搭配：归属判断"}],"collocations":[{"phrase":"be attributed to a lack of","zh":"被归因于缺乏……"},{"phrase":"be attributed to climate change","zh":"被归因于气候变化"},{"phrase":"be attributed to human error","zh":"被归因于人为失误"},{"phrase":"be attributed to the author","zh":"被认定出自该作者"},{"phrase":"be attributed to chance","zh":"被归因于偶然"},{"phrase":"be widely attributed to","zh":"被普遍归因于"}],"forms":[{"label":"原形","form":"be attributed to"},{"label":"现在时","form":"is attributed to"},{"label":"过去时","form":"was attributed to"},{"label":"情态结构","form":"may be attributed to"},{"label":"主动形","form":"attribute to"},{"label":"名词","form":"attribution"}],"derivatives":[{"word":"attribute","pos":"v./n.","zh":"由拉丁语「分配、归给」动词而来，义为「把……归因于；属性」"},{"word":"attribution","pos":"n.","zh":"由该动词加名词尾构成，义为「归属；归因」"},{"word":"attributable","pos":"adj.","zh":"由该动词加「可……的」形容词尾构成，义为「可归因的」"},{"word":"contributor","pos":"n.","zh":"同出「分配」词根的另一族词，义为「贡献者」"},{"word":"distribute","pos":"v.","zh":"同出「分配」词根的另一族词，义为「分发」"}],"senses":[{"no":"01","title":"Assigned as a cause","titleCN":"被归因为原因","definition":"used when an outcome is credited to a cause","definitionCN":"把某个结果归到某个原因","example":"The decline may be attributed to a fall in demand.","exampleCN":"这一下降可能被归因于需求减少。","why":"The passive hides the observer: the sentence presents the attribution as if it were settled.","whyCN":"被动式隐去观察者，句子把归因呈现得像已定之论。"},{"no":"02","title":"Assigned to an author","titleCN":"被认为出自某人之手","definition":"used when a work is credited to a particular maker","definitionCN":"把作品归到某位创作者","example":"The painting can be attributed to a later copyist.","exampleCN":"这幅画可能被归到一位较晚的临摹者名下。","why":"Attribution here is an expert judgement, and the passive keeps the judgement provisional.","whyCN":"这里的归属是专家判断，被动式让判断保持未定。"},{"no":"03","title":"Credited for a success","titleCN":"归功于","definition":"used when praise for a success is assigned to someone","definitionCN":"把成功的功劳归给某人","example":"The recovery can be attributed to the new treatment.","exampleCN":"这次康复可能归功于新疗法。","why":"Credit is the positive face of attribution, with the same grammar.","whyCN":"「归功」是归因的正面，语法完全相同。"},{"no":"04","title":"Blamed for a failure","titleCN":"归咎于","definition":"used when responsibility for a failure is assigned","definitionCN":"把失败的责任归给某方","example":"The accident may be attributed to poor maintenance.","exampleCN":"这起事故可能被归咎于维护不善。","why":"Blame is the negative face; the frame itself does not judge whether the charge is fair.","whyCN":"「归咎」是负面，框架本身并不判断指控是否公允。"},{"no":"05","title":"Explained by a factor","titleCN":"用某因素解释","definition":"used when a phenomenon is explained by a factor rather than caused by it","definitionCN":"用某因素解释现象，而非断言它造成现象","example":"The gap can be attributed to differences in sample size.","exampleCN":"这一差距可以用样本量的差异来解释。","why":"In research the phrase often means explanation, not proof of causation.","whyCN":"在研究里，这一短语常表示解释，而非因果证明。"},{"no":"06","title":"Dated or located by experts","titleCN":"被认定出自某时期","definition":"used when an object is assigned to a period, school or region","definitionCN":"把器物归到某时期、流派或地区","example":"The vase can be attributed to the northern workshops.","exampleCN":"这只花瓶可能被归到北方作坊。","why":"Experts assign an object to a workshop by style, so the phrase reports a professional judgement.","whyCN":"专家按风格把器物归到某作坊，因此短语报告的是专业判断。"},{"no":"07","title":"Assigned to a category","titleCN":"被归入某类别","definition":"used when something is placed in a class or source group","definitionCN":"把某物归入某一类别或来源组","example":"These sayings can be attributed to oral tradition.","exampleCN":"这些谚语可以被归入口头传统。","why":"Sayings have no single author, so the source is a tradition rather than a name.","whyCN":"谚语没有单一作者，因此来源是传统而非姓名。"},{"no":"08","title":"Citation and credit in scholarship","titleCN":"学术引用中的归属","definition":"used in academic prose to name the source of an idea","definitionCN":"在学术文字中点出某一想法的来源","example":"The idea can be attributed to an earlier study.","exampleCN":"这一想法可以被归到一项更早的研究。","why":"Scholarship uses the passive to place an idea without claiming originality or blame.","whyCN":"学术写作借此为想法定位，既不宣称原创也不追责。"}],"etymology":{"intro":{"en":"Attribute comes from Latin attribuere, to assign or allot, from ad-, to, and tribuere, to allot, which derives from tribus, a tribe or division. The verb passed through French into English; the passive frame is modern and its first date is approximate.","cn":"attribute 源自拉丁语 attribuere「分配、归给」，由 ad-「向」与 tribuere「分配」构成，后者出自 tribus「部落、分区」。动词经法语进入英语；被动框架属近代，首见年代为约数。"},"items":[{"era":"LATIN TRIBUS","en":"Tribus means a tribe or a division of the people.","cn":"tribus 意为「部落、民众的分区」。"},{"era":"LATIN TRIBUERE","en":"Tribuere means to allot or assign, the source of tribute and contribute.","cn":"tribuere 意为「分配、给予」，是 tribute 与 contribute 的来源。"},{"era":"LATIN AD-","en":"The prefix ad- means to or towards, turning allotment into assignment.","cn":"前缀 ad- 意为「向」，把「分配」变成「归给」。"},{"era":"LATIN ATTRIBUERE","en":"Attribuere means to assign something to a person or a cause.","cn":"attribuere 意为「把某物归给某人或某因」。"},{"era":"FRENCH AND ENGLISH","en":"French attribuer carried the verb into English, where it works actively and passively.","cn":"法语 attribuer 把这个动词带入英语，英语中兼有主动与被动用法。"},{"era":"ENGLISH PHRASE","en":"The passive frame is modern; first dates are approximate.","cn":"这一被动框架属近代用法，首见年代为约数。"}]},"similar":{"note":{"en":"The first group shares the root or the frame and shifts the direction; the second group holds other verbs of assigning credit or blame.","cn":"第一组共用词根或框架而改变方向；第二组是其他表示归功或归咎的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"attribute to","ipa":"/əˈtrɪbjuːt tuː/","tag":"active form","definition":"The active form names the observer: critics attribute the decline to demand.","definitionCN":"主动式点出观察者：评论者把下降归因于需求。"},{"word":"be contributed to","ipa":"/biː kənˈtrɪbjuːtɪd tuː/","tag":"same root, giving","definition":"Contribute shares the root but means to give towards something.","definitionCN":"这个词同根，但意为「向某处贡献」。"},{"word":"be distributed to","ipa":"/biː dɪˈstrɪbjuːtɪd tuː/","tag":"same root, spreading","definition":"Distribute shares the root but means to hand out among many.","definitionCN":"这个词同根，但意为「分发给多方」。"},{"word":"attribution","ipa":"/ˌætrɪˈbjuːʃn/","tag":"the noun","definition":"The noun names the act or the record of assigning a source.","definitionCN":"名词指归源的行为或记录。"}]},{"heading":"NEAR MEANING","entries":[{"word":"be ascribed to","ipa":"/biː əˈskraɪbd tuː/","tag":"formal assignment","definition":"It is the formal twin and often appears in older scholarship.","definitionCN":"它是正式的双胞胎，多见于较早的学术文字。"},{"word":"be credited to","ipa":"/biː ˈkredɪtɪd tuː/","tag":"positive assignment","definition":"It assigns praise or authorship, rarely blame.","definitionCN":"它归功或归作者，很少用于归咎。"},{"word":"be blamed on","ipa":"/biː ˈbleɪmd ɒn/","tag":"negative assignment","definition":"It assigns responsibility informally and usually with disapproval.","definitionCN":"它非正式地归责，通常带不满。"},{"word":"be put down to","ipa":"/biː pʊt daʊn tuː/","tag":"conversational","definition":"It is the everyday spoken way to explain something by a cause.","definitionCN":"它是口语里用原因解释某事的日常说法。"}]}]},"mnemonics":{"normalIntro":{"en":"The normal associations use the real Latin allotment, the active-passive pair and the credit-blame scale.","cn":"正常联想使用真实的拉丁语「分配」、主动与被动配对以及归功—归咎的刻度。"},"normal":[{"en":"Tribuere is to allot, so attribution hands a result to a party.","cn":"词根意为「分配」，归因就是把结果分给一方。"},{"en":"The passive hides who is doing the assigning.","cn":"被动式隐去是谁在做归给。"},{"en":"The active attribute to names the observer and is safer in argument.","cn":"主动式点出观察者，在论证中更稳妥。"},{"en":"Credit and blame are the two faces of the same grammar.","cn":"归功与归咎是同一语法的两张脸。"},{"en":"In research it often means explanation, not proof.","cn":"在研究里它常表示解释，而非证明。"}],"abstract":[{"en":"Like a small label beside an unsigned painting, a name linked to the frame.","cn":"像无名画作旁的小牌，一个名字连到画框。"},{"en":"Like a bill handed to the person the waiter believes ordered the meal.","cn":"像侍者把小票递给自认为点菜的那位。"},{"en":"Like a footnote pointing back to an earlier page.","cn":"像脚注指向前面的一页。"}]},"examples":[{"en":"The decline may be attributed to a fall in demand.","cn":"这一下降可能被归因于需求减少。"},{"en":"The painting can be attributed to a later copyist.","cn":"这幅画可能被归到一位较晚的临摹者名下。"},{"en":"The gap can be attributed to differences in sample size.","cn":"这一差距可以用样本量的差异来解释。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「比 阿吹比尤特 图」——无名画作旁立着小牌，名字用线指向画框：被归因于；被认为出自","word":"be attributed to"},"root":"attribute 源自拉丁语 attribuere「分配、归给」，由表示「向」的前缀与 tribuere「分配」构成，后者出自 tribus「部落、分区」；这一被动框架属近代用法，首见年代为约数。","sensesIntro":{"en":"Eight senses split by what is assigned: a cause, an author, a credit, a blame, an explanation, a period, a category and a scholarly source.","cn":"八个义项按被归给的对象区分：原因、作者、功劳、责任、解释、时期、类别、学术来源。"},"semanticMap":{"core":{"en":"CORE IMAGE: a small label beside an unsigned painting, a name linked by a line to the frame.","cn":"核心意象：无名画作旁的小牌，名字用线连到画框。"},"chain":["ALLOT","HAND THE RESULT OVER","NAME A CAUSE","NAME AN AUTHOR","CREDIT OR BLAME","PLACE IN A SOURCE"],"branches":[{"senses":"01","en":"THE CAUSE: an outcome is handed to a factor and stated as settled.","cn":"原因：结果被归给某个因素，并被陈述为已定。"},{"senses":"05","en":"THE EXPLANATION: research often explains rather than proves causation.","cn":"解释：研究常作解释，而非证明因果。"},{"senses":"02 · 06","en":"THE MAKER AND THE PERIOD: experts assign works to hands and dates.","cn":"作者与时期：专家把作品归到人手与年代。"},{"senses":"03 · 04","en":"THE SCALE OF VALUE: credit and blame sit at opposite ends of one grammar.","cn":"价值刻度：归功与归咎处于同一语法的两端。"},{"senses":"07 · 08","en":"THE SOURCE: sayings go to oral tradition, ideas to earlier studies.","cn":"来源：谚语归口头传统，想法归早先研究。"}]},"affixes":{"intro":{"en":"The Latin core is ad-, towards, plus tribuere, to allot; attribuere supplies the English verb and its nouns.","cn":"拉丁核心是 ad-「向」加 tribuere「分配」；attribuere 提供英语动词及其名词。"},"latinIntro":{"en":"The Latin elements are ad-, to, and tribuere, to allot, from tribus, a division of the people.","cn":"拉丁成分是 ad-「向」与 tribuere「分配」，后者出自 tribus「民众的分区」。"},"items":[{"word":"ad-","structure":"Latin prefix","meaning":"to; towards","meaningCN":"向；朝","example":"The prefix turns allotment into assignment to a party.","exampleCN":"前缀把「分配」变成「归给一方」。"},{"word":"tribus","structure":"Latin noun, fourth declension","meaning":"a tribe; a division","meaningCN":"部落；分区","example":"The noun explains why allotment is the root idea.","exampleCN":"名词解释了为何「分配」是核心义。"},{"word":"tribuere","structure":"Latin verb, third conjugation","meaning":"to allot; assign","meaningCN":"分配；给予","example":"The verb also gives tribute and contribute.","exampleCN":"这个动词也给出「贡品」「贡献」诸词。"},{"word":"attribuere","structure":"ad- + tribuere, Latin verb","meaning":"to assign to","meaningCN":"归给","example":"The compound is the direct source of the English verb.","exampleCN":"复合动词是英语动词的直接来源。"},{"word":"attribute","structure":"English verb and noun","meaning":"to assign; a quality","meaningCN":"归因；属性","example":"The verb works actively and passively.","exampleCN":"这个动词兼有主动与被动用法。"},{"word":"attribution","structure":"attribute + -ion","meaning":"the act of assigning","meaningCN":"归属；归因","example":"The noun names the act or its record.","exampleCN":"名词指行为或其记录。"},{"word":"attributable","structure":"attribute + -able","meaning":"able to be assigned","meaningCN":"可归因的","example":"The adjective marks what can be assigned.","exampleCN":"形容词标记可被归给之物。"},{"word":"be attributed to","structure":"be + past participle + preposition, fixed phrase","meaning":"to be credited to","meaningCN":"被归因于","example":"The passive frame leaves the observer unnamed.","exampleCN":"被动框架不点出观察者。"}],"latinEntries":[{"word":"tribuere","structure":"tribuere, tribuo, tribui, tributum (verb, third conjugation)","meaning":"to allot","meaningCN":"分配"},{"word":"attribuere","structure":"attribuere, attribuo, attribui, attributum (ad- + tribuere)","meaning":"to assign to","meaningCN":"归给"}],"derivatives":[{"word":"attribute","pos":"v./n.","zh":"归因；属性"},{"word":"attribution","pos":"n.","zh":"归属；归因"},{"word":"attributable","pos":"adj.","zh":"可归因的"},{"word":"contributor","pos":"n.","zh":"贡献者"},{"word":"distribute","pos":"v.","zh":"分发"}]}},{"word":"be dependent on","ipa_uk":"/biː dɪˈpendənt ɒn/","ipa_us":"/biː dɪˈpendənt ɑːn/","definition_zh":"依赖；取决于；依靠（某物或某人）才能存在、运作或成立","definition_en":"to need something in order to exist, work or be decided, or to be controlled by it","core_image":"一盏吊灯悬在一根细链上，链子的另一端固定在房梁，灯下没有别的东西支撑","scene":"屋梁上垂下一根细链，吊灯全靠它悬着，灯下没有任何支撑。The whole ceiling will be dependent on that single beam.","sceneCN":"这里指整片顶棚都靠那根梁承托（第 1 个义项：依靠某物才能成立）；句意为整个顶棚都将依赖于那一根梁。图中可辨识物件：房梁、细链、吊灯、空荡的灯下。","pos":[{"tag":"adj. phr.","zh":"形容词短语：依赖；取决于"},{"tag":"idiom","zh":"固定搭配：受……决定"}],"collocations":[{"phrase":"be dependent on income","zh":"依赖收入"},{"phrase":"be dependent on rainfall","zh":"取决于降雨"},{"phrase":"be dependent on technology","zh":"依赖技术"},{"phrase":"be dependent on the outcome","zh":"取决于结果"},{"phrase":"be heavily dependent on","zh":"严重依赖"},{"phrase":"be dependent on a single supplier","zh":"依赖单一供应商"}],"forms":[{"label":"原形","form":"be dependent on"},{"label":"现在时","form":"is dependent on"},{"label":"过去时","form":"was dependent on"},{"label":"情态结构","form":"may be dependent on"},{"label":"动词形","form":"depend on"},{"label":"名词","form":"dependence"}],"derivatives":[{"word":"depend","pos":"v.","zh":"由拉丁语「悬挂于下」动词经法语而来，义为「依赖；取决于」"},{"word":"dependence","pos":"n.","zh":"由该动词加名词尾构成，义为「依赖」"},{"word":"dependency","pos":"n.","zh":"由该形容词加名词尾构成，义为「依赖关系；属地」"},{"word":"dependent","pos":"n.","zh":"由该形容词转作名词，义为「受抚养者」"},{"word":"independent","pos":"adj.","zh":"由否定前缀加该形容词构成，义为「独立的」"}],"senses":[{"no":"01","title":"Needing something to exist","titleCN":"依靠某物才能存在","definition":"to need a resource in order to survive or function","definitionCN":"需要某种资源才能存活或运作","example":"The whole ceiling will be dependent on that single beam.","exampleCN":"整个顶棚都将依赖那一根梁。","why":"The image is of a lamp hanging from a chain: remove the support and the thing falls.","whyCN":"意象是吊灯挂在链上：抽掉支撑，东西就落下。"},{"no":"02","title":"Decided by a factor","titleCN":"取决于某因素","definition":"used when an outcome is settled by another variable","definitionCN":"结果由另一变量决定时使用","example":"The final yield will be dependent on rainfall.","exampleCN":"最终产量将取决于降雨。","why":"Here dependence is logical rather than physical: one value fixes another.","whyCN":"这里的依赖是逻辑性的：一个数值定住另一个。"},{"no":"03","title":"Relying on a person","titleCN":"依靠某人","definition":"used when someone needs another person's help or income","definitionCN":"需要他人帮助或收入时使用","example":"Many students can be dependent on part-time work.","exampleCN":"许多学生可能要靠兼职工作。","why":"Personal dependence often carries a social judgement, so the phrase appears in policy writing.","whyCN":"人身依赖常带社会评判，因此短语多见于政策文字。"},{"no":"04","title":"Subordinate in status","titleCN":"地位上附属于","definition":"used when a territory or body is governed by another","definitionCN":"属地或机构受另一方治理时使用","example":"The smaller islands will be dependent on the mainland for fuel.","exampleCN":"较小的岛屿将依赖大陆供应燃料。","why":"A territory under another's supply chain hangs from that support, as the beam image shows.","whyCN":"属地靠他方供应链支撑，正如横梁意象所示。"},{"no":"05","title":"Controlled by a substance or mood","titleCN":"受某物支配","definition":"used when a person's state is controlled by a substance or feeling","definitionCN":"人的状态受某种物质或情绪控制时使用","example":"Patients can be dependent on pain relief after long treatment.","exampleCN":"长期治疗后病人可能依赖止痛药。","why":"Here the support is chemical: the body comes to need it in order to function.","whyCN":"这里的支撑是化学性的：身体为了运转而离不开它。"},{"no":"06","title":"A variable in mathematics","titleCN":"数学与统计中的变量依赖","definition":"used when one quantity changes according to another","definitionCN":"一个量随另一个量变化时使用","example":"The measured value will be dependent on the starting temperature.","exampleCN":"测量值将取决于起始温度。","why":"Statistics speaks of a dependent variable, the one that moves in response.","whyCN":"统计学讲「因变量」，即随之变动的那个量。"},{"no":"07","title":"A system's reliance on a component","titleCN":"系统对部件的依赖","definition":"used when a machine or network cannot work without a part","definitionCN":"机器或网络缺少某部件就无法工作时使用","example":"The network will be dependent on a single server.","exampleCN":"这个网络将依赖一台服务器。","why":"Remove the server and the network stops, exactly like removing the chain.","whyCN":"抽走服务器网络就停摆，正如抽走链条。"},{"no":"08","title":"Conditioned on circumstances","titleCN":"以特定条件为前提","definition":"used when a plan holds only under certain conditions","definitionCN":"计划只在特定条件下成立时使用","example":"The schedule can be dependent on the weather.","exampleCN":"日程可能取决于天气。","why":"Weather is the condition the plan hangs on, so the frame is conditional.","whyCN":"天气是计划所悬挂的条件，因此框架带条件意味。"}],"etymology":{"intro":{"en":"Depend comes from Latin dependere, to hang down or hang from, from de-, down, and pendere, to hang. The adjective came through French dépendant. The frame with on is modern and its first date is approximate.","cn":"depend 源自拉丁语 dependere「垂下、悬挂于」，由 de-「向下」与 pendere「悬挂」构成。形容词经法语 dépendant 而来。与介词连用的框架属近代，首见年代为约数。"},"items":[{"era":"LATIN PENDERE","en":"Pendere means to hang and also gives pendulum and pension.","cn":"pendere 意为「悬挂」，也是 pendulum 与 pension 的根基。"},{"era":"LATIN DE-","en":"The prefix de- means down, so the compound pictures something hanging from a support.","cn":"前缀 de- 意为「向下」，复合词画出某物自支撑垂下。"},{"era":"LATIN DEPENDERE","en":"Dependere means to hang from or to be attached to something above.","cn":"dependere 意为「悬挂于、附着于上方之物」。"},{"era":"FRENCH DEPENDRE","en":"French dépendre shifted the image to needing or being decided by.","cn":"法语 dépendre 把意象转向「需要」或「由……决定」。"},{"era":"ENGLISH ADJECTIVE","en":"English dependent keeps the participle shape and pairs with on or upon.","cn":"英语形容词保留分词形态，与介词连用。"},{"era":"ENGLISH PHRASE","en":"The frame is modern; first dates are approximate.","cn":"这一框架属近代用法，首见年代为约数。"}]},"similar":{"note":{"en":"The first group shares the root but changes the form or reverses the meaning; the second group holds other verbs of reliance.","cn":"第一组共用词根而改变形式或反转意义；第二组是其他表示依靠的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"depend on","ipa":"/dɪˈpend ɒn/","tag":"plain verb","definition":"The verb states reliance directly and is less formal than the adjective frame.","definitionCN":"动词更直接陈述依赖，也不如形容词框架正式。"},{"word":"be dependent upon","ipa":"/biː dɪˈpendənt əˈpɒn/","tag":"bookish variant","definition":"Upon is the formal alternative to on in older prose.","definitionCN":"upon 是 on 的书面替代，多见于较早文字。"},{"word":"be independent of","ipa":"/biː ɪnˈdɪpendənt ɒv/","tag":"opposite","definition":"The negative form marks freedom from control, with a different preposition.","definitionCN":"否定形式表示不受控制，介词也不同。"},{"word":"dependency","ipa":"/dɪˈpendənsi/","tag":"the noun","definition":"The noun names the relation, or a territory governed by another.","definitionCN":"名词指依赖关系，或受他方治理的属地。"}]},{"heading":"NEAR MEANING","entries":[{"word":"rely on","ipa":"/rɪˈlaɪ ɒn/","tag":"trust as well as need","definition":"It adds trust to need, and often takes a person.","definitionCN":"它在「需要」之外加上「信任」，常接人。"},{"word":"be contingent on","ipa":"/biː kənˈtɪndʒənt ɒn/","tag":"formal condition","definition":"It stresses that an outcome holds only if a condition holds.","definitionCN":"它强调结果只在条件成立时才成立。"},{"word":"hinge on","ipa":"/hɪndʒ ɒn/","tag":"pivotal dependence","definition":"It pictures a door turning on a hinge, so the factor is decisive.","definitionCN":"它画出门绕铰链转动，因此该因素具有决定性。"},{"word":"be conditional on","ipa":"/biː kənˈdɪʃənl ɒn/","tag":"stated condition","definition":"It is the legal and contractual way to state a precondition.","definitionCN":"它是法律与合同里陈述前提条件的方式。"}]}]},"mnemonics":{"normalIntro":{"en":"The normal associations use the real hanging image, the verb-adjective pair and the independent opposite.","cn":"正常联想使用真实的悬挂意象、动词与形容词配对以及「独立」的反面。"},"normal":[{"en":"Pendere is to hang, so dependence is hanging from a support.","cn":"词根意为「悬挂」，依赖就是挂在支撑上。"},{"en":"Remove the beam and the lamp falls: that is the test of dependence.","cn":"抽掉梁，灯就落下：这是依赖的检验。"},{"en":"The verb depend on is plainer; the adjective frame is more formal.","cn":"动词形更朴素，形容词框架更正式。"},{"en":"Independent takes of, not on, because the direction reverses.","cn":"「独立的」用另一介词，因为方向反转。"},{"en":"Statistics calls the moving quantity the dependent variable.","cn":"统计学把随之变动的量称作因变量。"}],"abstract":[{"en":"Like a lamp hanging from one thin chain with nothing beneath it.","cn":"像吊灯只靠一根细链悬着，下方空无一物。"},{"en":"Like a row of dominoes waiting for the first push.","cn":"像一排骨牌，等着第一推。"},{"en":"Like a plant whose roots reach one thin layer of water.","cn":"像根系只够到一层薄水的植物。"}]},"examples":[{"en":"The whole ceiling will be dependent on that single beam.","cn":"整个顶棚都将依赖那一根梁。"},{"en":"The final yield will be dependent on rainfall.","cn":"最终产量将取决于降雨。"},{"en":"The schedule can be dependent on the weather.","cn":"日程可能取决于天气。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「比 迪彭登特 昂」——屋梁垂下细链，吊灯全靠它悬着：依赖；取决于","word":"be dependent on"},"root":"depend 源自拉丁语 dependere「垂下、悬挂于」，由表示「向下」的前缀与 pendere「悬挂」构成；形容词经法语 dépendant 而来。这一形容词加介词的框架属近代用法，首见年代为约数。","sensesIntro":{"en":"Eight senses split by the support: a beam, a factor, a person, a territory, a substance, a variable, a component and a condition.","cn":"八个义项按支撑物区分：横梁、因素、人、属地、物质、变量、部件、条件。"},"semanticMap":{"core":{"en":"CORE IMAGE: a lamp hanging from one thin chain fixed to a beam, nothing beneath it.","cn":"核心意象：吊灯只靠一根细链挂在房梁上，下方空无一物。"},"chain":["HANG DOWN","NEED THE SUPPORT","FOLLOW THE FACTOR","RELY ON PEOPLE","BE GOVERNED","BE CONDITIONED"],"branches":[{"senses":"01 · 07","en":"THE SUPPORT: a beam or a server holds everything above it.","cn":"支撑：横梁或服务器承托上方一切。"},{"senses":"02 · 06","en":"THE VARIABLE: one quantity moves because another moves.","cn":"变量：一个量因另一个量而变。"},{"senses":"03 · 04","en":"THE PERSON AND THE TERRITORY: people and islands are supported by others.","cn":"人与属地：人与岛屿靠他方供养。"},{"senses":"05","en":"THE SUBSTANCE: relief or a mood takes control of the person.","cn":"物质：药物或情绪控制了人。"},{"senses":"08","en":"THE CONDITION: the plan holds only if the weather holds.","cn":"条件：天气成立，计划才成立。"}]},"affixes":{"intro":{"en":"The Latin core is de-, down, plus pendere, to hang; dependere and its French participle supply the English forms.","cn":"拉丁核心是 de-「向下」加 pendere「悬挂」；dependere 及其法语分词提供英语形式。"},"latinIntro":{"en":"The Latin elements are de-, down, and pendere, to hang; dependere joins them.","cn":"拉丁成分是 de-「向下」与 pendere「悬挂」，dependere 由两者合成。"},"items":[{"word":"de-","structure":"Latin prefix","meaning":"down; from","meaningCN":"向下；自","example":"The prefix points the hanging downward.","exampleCN":"前缀把悬挂的方向指向下方。"},{"word":"pendere","structure":"Latin verb, third conjugation","meaning":"to hang; weigh","meaningCN":"悬挂；称量","example":"The verb also gives pendulum and pension.","exampleCN":"这个动词也给出「摆」「年金」诸词。"},{"word":"dependere","structure":"de- + pendere, Latin verb","meaning":"to hang from","meaningCN":"悬挂于","example":"The compound is the source of the English family.","exampleCN":"复合动词是英语同族词的来源。"},{"word":"dépendant","structure":"French participle and adjective","meaning":"depending","meaningCN":"依赖的","example":"French supplied the adjective form.","exampleCN":"法语提供了形容词形式。"},{"word":"dependent","structure":"English adjective and noun","meaning":"relying; a person supported","meaningCN":"依赖的；受抚养者","example":"The adjective pairs with on or upon.","exampleCN":"形容词与介词连用。"},{"word":"dependence","structure":"depend + -ence","meaning":"the state of relying","meaningCN":"依赖","example":"The noun names the relation itself.","exampleCN":"名词命名这种关系本身。"},{"word":"dependency","structure":"dependent + -cy","meaning":"a reliant relationship or territory","meaningCN":"依赖关系；属地","example":"The noun also names governed territories.","exampleCN":"名词也指受治理的属地。"},{"word":"be dependent on","structure":"be + adjective + preposition, fixed phrase","meaning":"to need for support","meaningCN":"依赖；取决于","example":"The frame fixes the support after the preposition.","exampleCN":"框架把支撑物固定在介词后。"}],"latinEntries":[{"word":"pendere","structure":"pendere, pendo, pependi, pensum (verb, third conjugation)","meaning":"to hang; weigh","meaningCN":"悬挂；称量"},{"word":"dependere","structure":"dependere, dependeo, dependi, dependum (de- + pendere)","meaning":"to hang from","meaningCN":"悬挂于"}],"derivatives":[{"word":"depend","pos":"v.","zh":"依赖；取决于"},{"word":"dependence","pos":"n.","zh":"依赖"},{"word":"dependency","pos":"n.","zh":"依赖关系；属地"},{"word":"dependent","pos":"n.","zh":"受抚养者"},{"word":"independent","pos":"adj.","zh":"独立的"}]}}]);
